    private static String oracleFloatBits(float value) {
        String hex = Integer.toHexString(Float.floatToRawIntBits(value));
        if (hex.length() >= 8) return hex;
        return "00000000".substring(hex.length()) + hex;
    }

    private static String oracleDoubleBits(double value) {
        String hex = Long.toHexString(Double.doubleToRawLongBits(value));
        if (hex.length() >= 16) return hex;
        return "0000000000000000".substring(hex.length()) + hex;
    }

