    private static final class OracleEntityCollisionCapture {
        final int selfEid;
        final int otherEid;
        final double[] before;
        double[] after;

        OracleEntityCollisionCapture(Entity self, Entity other) {
            selfEid = self.getEntityId();
            otherEid = other.getEntityId();
            before = collisionState(self, other);
        }

        void finish(Entity self, Entity other) {
            after = collisionState(self, other);
        }

        JsonObject toJson() {
            JsonObject row = new JsonObject();
            row.addProperty("self_eid", selfEid);
            row.addProperty("other_eid", otherEid);
            row.add("before_bits", oracleDoubleArrayBits(before));
            if (after != null)
                row.add("after_bits", oracleDoubleArrayBits(after));
            return row;
        }

        private static JsonArray oracleDoubleArrayBits(double[] values) {
            JsonArray out = new JsonArray();
            for (double value : values)
                out.add(new JsonPrimitive(
                    OracleWorldEventCapture.ParticleRecord.bits(value)));
            return out;
        }

        private static double[] collisionState(Entity self, Entity other) {
            net.minecraft.util.math.AxisAlignedBB selfBox =
                self.getEntityBoundingBox();
            net.minecraft.util.math.AxisAlignedBB otherBox =
                other.getEntityBoundingBox();
            return new double[] {
                self.posX, self.posY, self.posZ,
                self.motionX, self.motionY, self.motionZ,
                other.posX, other.posY, other.posZ,
                other.motionX, other.motionY, other.motionZ,
                selfBox.minX, selfBox.minY, selfBox.minZ,
                selfBox.maxX, selfBox.maxY, selfBox.maxZ,
                otherBox.minX, otherBox.minY, otherBox.minZ,
                otherBox.maxX, otherBox.maxY, otherBox.maxZ,
            };
        }
    }
