    /** Client-thread hook from MixinRecordPlayerVelocity. Raw packet shorts are
     * retained so replay reproduces SPacketEntityVelocity's 1/8000 quantization. */
    public static void recordPlayerVelocityPacket(
            net.minecraft.network.play.server.SPacketEntityVelocity packet) {
        Minecraft mc = Minecraft.getMinecraft();
        if (mc == null || mc.player == null ||
            packet.getEntityID() != mc.player.getEntityId()) return;
        recVelocityX = packet.getMotionX();
        recVelocityY = packet.getMotionY();
        recVelocityZ = packet.getMotionZ();
        recVelocityPending = true;
    }

    /** Client-thread hook from MixinRecordExplosion. Serialized immediately:
     * the packet's block list is authoritative (Explosion.doExplosionB clears
     * exactly these positions client-side) and the motion components are the
     * knockback added to the local player. */
    public static void recordExplosionPacket(
            net.minecraft.network.play.server.SPacketExplosion packet) {
        Recorder bridge = oracleInstance;
        if (bridge == null || bridge.recWriter == null) return;
        StringBuilder e = new StringBuilder();
        e.append('[').append(packet.getX())
         .append(',').append(packet.getY())
         .append(',').append(packet.getZ())
         .append(',').append(packet.getStrength())
         .append(',').append(packet.getMotionX())
         .append(',').append(packet.getMotionY())
         .append(',').append(packet.getMotionZ())
         .append(",[");
        java.util.List<net.minecraft.util.math.BlockPos> blocks =
            packet.getAffectedBlockPositions();
        for (int i = 0; i < blocks.size(); i++) {
            net.minecraft.util.math.BlockPos bp = blocks.get(i);
            if (i > 0) e.append(',');
            e.append('[').append(bp.getX()).append(',')
             .append(bp.getY()).append(',').append(bp.getZ()).append(']');
        }
        e.append("]]");
        recExplosions.add(e.toString());
    }

    private static String encodeParticleState(int id, double x, double y,
            double z, double vx, double vy, double vz,
            net.minecraft.client.particle.Particle particle) {
        com.microsoft.Malmo.Mixins.AccessorParticleState s =
            (com.microsoft.Malmo.Mixins.AccessorParticleState)(Object)particle;
        StringBuilder p = new StringBuilder(384);
        p.append('[').append(id)
         .append(',').append(x).append(',').append(y).append(',').append(z)
         .append(',').append(vx).append(',').append(vy).append(',').append(vz)
         .append(",{\"v\":1")
         .append(",\"prev\":[").append(s.qrl$getPrevPosX()).append(',')
             .append(s.qrl$getPrevPosY()).append(',').append(s.qrl$getPrevPosZ()).append(']')
         .append(",\"pos\":[").append(s.qrl$getPosX()).append(',')
             .append(s.qrl$getPosY()).append(',').append(s.qrl$getPosZ()).append(']')
         .append(",\"motion\":[").append(s.qrl$getMotionX()).append(',')
             .append(s.qrl$getMotionY()).append(',').append(s.qrl$getMotionZ()).append(']')
         .append(",\"age\":").append(s.qrl$getParticleAge())
         .append(",\"max_age\":").append(s.qrl$getParticleMaxAge())
         .append(",\"ground\":").append(s.qrl$getOnGround())
         .append(",\"collide\":").append(s.qrl$getCanCollide())
         .append(",\"scale\":").append(s.qrl$getParticleScale())
         .append(",\"gravity\":").append(s.qrl$getParticleGravity())
         .append(",\"rgba\":[").append(s.qrl$getParticleRed()).append(',')
             .append(s.qrl$getParticleGreen()).append(',')
             .append(s.qrl$getParticleBlue()).append(',')
             .append(s.qrl$getParticleAlpha()).append(']')
         .append(",\"tex\":[").append(s.qrl$getTextureIndexX()).append(',')
             .append(s.qrl$getTextureIndexY()).append(']')
         .append(",\"jitter\":[").append(s.qrl$getTextureJitterX()).append(',')
             .append(s.qrl$getTextureJitterY()).append(']')
         /* ParticleDigging chooses between its interpolated-position light
          * and sourcePos light here. Preserve the resulting packed OpenGL
          * coordinates instead of asking native to reconstruct client light
          * propagation from the block position. */
         .append(",\"lightmap\":").append(
             particle.getBrightnessForRender(1.0F));
        if (particle instanceof net.minecraft.client.particle.ParticleExplosionLarge) {
            com.microsoft.Malmo.Mixins.AccessorParticleExplosionLargeState ls =
                (com.microsoft.Malmo.Mixins.AccessorParticleExplosionLargeState)(Object)particle;
            p.append(",\"life\":").append(ls.qrl$getLife())
             .append(",\"life_time\":").append(ls.qrl$getLifeTime())
             .append(",\"size\":").append(ls.qrl$getSize());
        } else if (particle instanceof net.minecraft.client.particle.ParticleExplosionHuge) {
            com.microsoft.Malmo.Mixins.AccessorParticleExplosionHugeState hs =
                (com.microsoft.Malmo.Mixins.AccessorParticleExplosionHugeState)(Object)particle;
            p.append(",\"time\":").append(hs.qrl$getTimeSinceStart());
        } else if (particle instanceof net.minecraft.client.particle.ParticleSpell) {
            com.microsoft.Malmo.Mixins.AccessorParticleSpellState ss =
                (com.microsoft.Malmo.Mixins.AccessorParticleSpellState)(Object)particle;
            p.append(",\"base_tex\":").append(
                ss.qrl$getBaseSpellTextureIndex());
        }
        p.append("}]");
        return p.toString();
    }

    /** Client-thread hook from MixinRecordParticles. Capture after the factory
     * returns so constructor-private entropy is an observation, not a guessed
     * replay RNG. The full base state stays in the tape for future render work;
     * class-private render clocks are added for LARGE/HUGE. */
    public static void recordParticleSpawn(int id, double x, double y,
            double z, double vx, double vy, double vz,
            net.minecraft.client.particle.Particle particle) {
        Recorder bridge = oracleInstance;
        if (bridge == null || particle == null
                || (bridge.recWriter == null
                    && !bridge.renderParticleCaptureActive))
            return;
        String encoded = encodeParticleState(
            id, x, y, z, vx, vy, vz, particle);
        if (bridge.recWriter != null) recParticles.add(encoded);
        if (bridge.renderParticleCaptureActive)
            bridge.renderParticleCapture.add(encoded);
    }

    /** Snapshot the live ParticleDigging rows used by a frame_pair. Unlike
     * status particles these are already in fxLayers after the fixture's
     * settle ticks, so observing the list captures their exact age, motion,
     * scale, tint, and constructor-private jitter without perturbing it. */
    private JsonArray captureCurrentDigParticles(Minecraft mc) {
        JsonArray result = new JsonArray();
        try {
            java.lang.reflect.Field fl =
                net.minecraft.client.particle.ParticleManager.class
                    .getDeclaredField("fxLayers");
            fl.setAccessible(true);
            @SuppressWarnings("unchecked")
            java.util.ArrayDeque<net.minecraft.client.particle.Particle>[][] layers =
                (java.util.ArrayDeque<net.minecraft.client.particle.Particle>[][])
                    fl.get(mc.effectRenderer);
            JsonParser parser = new JsonParser();
            if (layers != null)
                for (int i = 0; i < layers.length; ++i)
                    for (int j = 0; j < layers[i].length; ++j) {
                        java.util.ArrayDeque<net.minecraft.client.particle.Particle>
                            layer = layers[i][j];
                        if (layer == null) continue;
                        for (net.minecraft.client.particle.Particle particle : layer) {
                            if (!(particle instanceof net.minecraft.client.particle
                                    .ParticleDigging))
                                continue;
                            com.microsoft.Malmo.Mixins.AccessorParticleState s =
                                (com.microsoft.Malmo.Mixins.AccessorParticleState)
                                    (Object)particle;
                            result.add(parser.parse(encodeParticleState(
                                9004,
                                s.qrl$getPosX(), s.qrl$getPosY(),
                                s.qrl$getPosZ(), s.qrl$getMotionX(),
                                s.qrl$getMotionY(), s.qrl$getMotionZ(),
                                particle)));
                        }
                    }
        } catch (Throwable t) {
            throw new IllegalStateException("dig particle snapshot failed", t);
        }
        if (result.size() == 0)
            throw new IllegalStateException("dig particle snapshot is empty");
        return result;
    }

    /** Spawn one horse status burst on the pinned client entity and make it
     * renderable without advancing a particle tick. The returned constructor
     * states are the exact native replay inputs for this same frame pair. */
    private JsonArray capturePinnedHorseParticles(Minecraft mc, int status) {
        if (status != 6 && status != 7)
            throw new IllegalArgumentException("horse_status must be 6 or 7");
        net.minecraft.entity.Entity entity = findClientRenderPinEntity(mc);
        if (!(entity instanceof net.minecraft.entity.passive.AbstractHorse))
            throw new IllegalStateException("no pinned client horse");
        applyClientEntityRenderFields(entity);
        mc.effectRenderer.clearEffects(mc.world);
        try {
            java.lang.reflect.Field queue =
                net.minecraft.client.particle.ParticleManager.class
                    .getDeclaredField("queueEntityFX");
            queue.setAccessible(true);
            Object value = queue.get(mc.effectRenderer);
            if (value instanceof java.util.Queue)
                ((java.util.Queue<?>)value).clear();
        } catch (Throwable ignored) {}
        renderParticleCapture.clear();
        renderParticleCaptureActive = true;
        try {
            entity.handleStatusUpdate((byte)status);
        } finally {
            renderParticleCaptureActive = false;
        }
        mc.effectRenderer.updateEffects();
        if (renderParticleCapture.size() != 7)
            throw new IllegalStateException("horse status captured "
                + renderParticleCapture.size() + " particles");
        JsonArray result = new JsonArray();
        JsonParser parser = new JsonParser();
        for (String encoded : renderParticleCapture)
            result.add(parser.parse(encoded));
        return result;
    }

    private static boolean tapeRecording() {
        Recorder bridge = oracleInstance;
        return bridge != null && bridge.recWriter != null;
    }

    private static String tapeStackNbt(
            net.minecraft.item.ItemStack stack) {
        if (stack == null || stack.isEmpty()) return "";
        net.minecraft.nbt.NBTTagCompound compound =
            new net.minecraft.nbt.NBTTagCompound();
        stack.writeToNBT(compound);
        return oracleNbtHex(compound);
    }

    public static void recordGuiMouse(String screen, int x, int y,
            int button, boolean down, int wheel) {
        if (!tapeRecording()) return;
        recGuiInputs.add("{\"kind\":\"mouse\",\"screen\":\"" + screen
            + "\",\"x\":" + x + ",\"y\":" + y + ",\"button\":"
            + button + ",\"down\":" + (down ? 1 : 0) + ",\"wheel\":"
            + wheel + "}");
    }

