                (net.minecraft.entity.monster.EntitySkeleton)e;
            snap.isSkeleton = true;
            snap.ticksExisted = skeleton.ticksExisted;
            snap.yaw = skeleton.rotationYaw; snap.pitch = skeleton.rotationPitch;
            snap.prevYaw = skeleton.prevRotationYaw;
            snap.prevPitch = skeleton.prevRotationPitch;
