    /** EntitySnowball.onImpact against the two ordinary damage branches:
     * Blaze receives 3 while every other living target receives 0. Ordinary
     * living mobs traverse EntityLivingBase's zero-damage feedback path;
     * EntityPlayer rejects zero before calling its superclass. */
    private String oracleSnowballImpactLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "snowball_impact_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            JsonObject oldSeedHelper = null;
            int oldNextEntityId = -1;
            long oldUuidSeed = -1L, oldMathSeed = -1L;
            long oldPlayerSeed = -1L;
            double oldPlayerGaussian = 0.0D;
            boolean oldPlayerHaveGaussian = false;
            boolean oldUuidPinned = false;
            boolean oldUuidFixtureIsolation = false;
            java.lang.reflect.Field respawnInvulnerabilityField = null;
            int oldRespawnInvulnerability = 0;
            net.minecraft.scoreboard.ScorePlayerTeam oldPlayerTeam = null;
            boolean oldPlayerTeamFriendlyFire = false;
            try {
                String targetKind = action.get("target").getAsString();
                boolean snowmanThrower = action.has("thrower")
                    && action.get("thrower").getAsString().equals("snowman");
                float health = action.get("health").getAsFloat();
                int hurtResistant =
                    action.get("hurt_resistant_time").getAsInt();
                float lastDamage = action.get("last_damage").getAsFloat();
                boolean onGround = action.get("on_ground").getAsBoolean();
                long targetSeed = action.get("target_seed48").getAsLong();
                long mathSeed = action.get("math_seed48").getAsLong();
                if ((!targetKind.equals("pig")
                            && !targetKind.equals("blaze")
                            && !targetKind.equals("zombie")
                            && !targetKind.equals("player"))
                        || (snowmanThrower && targetKind.equals("player"))
                        || health <= 0.0F
                        || health > (targetKind.equals("pig") ? 10.0F : 20.0F)
                        || hurtResistant < 0 || hurtResistant > 20
                        || lastDamage < 0.0F || targetSeed < 0L
                        || targetSeed >= (1L << 48) || mathSeed < 0L
                        || mathSeed >= (1L << 48))
                    return err("invalid snowball impact fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                net.minecraft.world.WorldServer world =
                    player.getServerWorld();
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldSeedHelper = oracleSeedHelperState();
                oldNextEntityId = nextEntityId();
                oldUuidSeed = javaRandomSeed48(oracleServerUuidRandom);
                oldUuidPinned = oracleServerUuidPinned;
                oldUuidFixtureIsolation = oracleServerUuidFixtureIsolation;
                oldMathSeed = mathRandomSeed48();
                oldPlayerSeed = javaRandomSeed48(entityRandom(player));
                oldPlayerHaveGaussian =
                    javaRandomHaveNextGaussian(entityRandom(player));
                oldPlayerGaussian = javaRandomNextGaussian(
                    entityRandom(player));
                respawnInvulnerabilityField =
                    net.minecraft.entity.player.EntityPlayerMP.class
                        .getDeclaredField("respawnInvulnerabilityTicks");
                respawnInvulnerabilityField.setAccessible(true);
                oldRespawnInvulnerability =
                    respawnInvulnerabilityField.getInt(player);
                respawnInvulnerabilityField.setInt(player, 0);
                player.setEntityInvulnerable(false);
                player.capabilities.disableDamage = false;
                if (player.getTeam()
                        instanceof net.minecraft.scoreboard.ScorePlayerTeam) {
                    oldPlayerTeam = (net.minecraft.scoreboard.ScorePlayerTeam)
                        player.getTeam();
                    oldPlayerTeamFriendlyFire =
                        oldPlayerTeam.getAllowFriendlyFire();
                    oldPlayerTeam.setAllowFriendlyFire(true);
                }

                player.setLocationAndAngles(
                    24.5D, 220.0D, 24.5D, 0.0F, 0.0F);
                player.motionX = player.motionY = player.motionZ = 0.0D;
                player.onGround = true;
                net.minecraft.entity.EntityLivingBase target =
                    targetKind.equals("player") ? player
                    : targetKind.equals("pig")
                    ? new net.minecraft.entity.passive.EntityPig(world)
                    : targetKind.equals("blaze")
                    ? new net.minecraft.entity.monster.EntityBlaze(world)
                    : new net.minecraft.entity.monster.EntityZombie(world);
                net.minecraft.entity.monster.EntitySnowman snowman = null;
                net.minecraft.entity.EntityLivingBase thrower = player;
                if (snowmanThrower) {
                    snowman = new net.minecraft.entity.monster.EntitySnowman(
                        world);
                    snowman.setLocationAndAngles(
                        24.5D, 220.0D, 24.5D, 0.0F, 0.0F);
                    snowman.setEntityId(100);
                    thrower = snowman;
                }
                target.setLocationAndAngles(
                    25.5D, 220.0D, 24.5D, 0.0F, 0.0F);
                target.motionX = target.motionY = target.motionZ = 0.0D;
                target.onGround = onGround;
                target.setHealth(health);
                target.hurtTime = 0;
                target.maxHurtTime = 0;
                target.hurtResistantTime = hurtResistant;
                target.limbSwingAmount = 0.0F;
                target.attackedAtYaw = 0.0F;
                target.velocityChanged = false;
                target.setRevengeTarget(null);
                java.lang.reflect.Field lastDamageField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("lastDamage");
                java.lang.reflect.Field entityAgeField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("entityAge");
                java.lang.reflect.Field recentlyHitField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("recentlyHit");
                java.lang.reflect.Field attackingPlayerField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("attackingPlayer");
                lastDamageField.setAccessible(true);
                entityAgeField.setAccessible(true);
                recentlyHitField.setAccessible(true);
                attackingPlayerField.setAccessible(true);
                lastDamageField.setFloat(target, lastDamage);
                entityAgeField.setInt(target, 42);
                recentlyHitField.setInt(target, 0);
                attackingPlayerField.set(target, null);
                setJavaRandomSeed48(entityRandom(target), targetSeed);
                setJavaRandomGaussianState(
                    entityRandom(target), false, 0.0D);
                setMathRandomSeed48(mathSeed);

                net.minecraft.entity.projectile.EntitySnowball snowball =
                    new net.minecraft.entity.projectile.EntitySnowball(
                        world, thrower);
                snowball.setPosition(25.0D, 220.9D, 24.5D);
                java.lang.reflect.Method impact =
                    net.minecraft.entity.projectile.EntitySnowball.class
                        .getDeclaredMethod("onImpact", RayTraceResult.class);
                impact.setAccessible(true);
                impact.invoke(snowball, new RayTraceResult(target));

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("target_health_bits",
                    oracleFloatBits(target.getHealth()));
                out.add("target_motion_bits", oracleEntityDoubleBits(
                    target.motionX, target.motionY, target.motionZ));
                out.addProperty("target_hurt_time", target.hurtTime);
                out.addProperty("target_max_hurt_time", target.maxHurtTime);
                out.addProperty("target_hurt_resistant_time",
                    target.hurtResistantTime);
                out.addProperty("target_last_damage_bits",
                    oracleFloatBits(lastDamageField.getFloat(target)));
                out.addProperty("target_recently_hit",
                    recentlyHitField.getInt(target));
                out.addProperty("target_attacking_player",
                    attackingPlayerField.get(target) == player);
                out.addProperty("target_revenge_player",
                    target.getAITarget() == player);
                if (snowmanThrower)
                    out.addProperty("target_revenge_eid",
                        target.getAITarget() == null
                            ? -1 : target.getAITarget().getEntityId());
                out.addProperty("target_entity_age",
                    entityAgeField.getInt(target));
                out.addProperty("target_limb_swing_amount_bits",
                    oracleFloatBits(target.limbSwingAmount));
                out.addProperty("target_attacked_yaw_bits",
                    oracleFloatBits(target.attackedAtYaw));
                out.addProperty("target_velocity_changed",
                    target.velocityChanged);
                out.addProperty("target_seed48",
                    javaRandomSeed48(entityRandom(target)));
                out.addProperty("math_seed48", mathRandomSeed48());
                out.addProperty("snowball_dead", snowball.isDead);
                return out.toString();
            } catch (Throwable t) {
                return err("snowball_impact_locked: " + t);
            } finally {
                try {
                    if (player != null && saved != null)
                        player.readFromNBT(saved);
                    if (oldSeedHelper != null)
                        oracleRestoreSeedHelperState(oldSeedHelper);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                    if (oldUuidSeed >= 0L)
                        setJavaRandomSeed48(
                            oracleServerUuidRandom, oldUuidSeed);
                    oracleServerUuidPinned = oldUuidPinned;
                    oracleServerUuidFixtureIsolation =
                        oldUuidFixtureIsolation;
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (player != null && oldPlayerSeed >= 0L) {
                        setJavaRandomSeed48(
                            entityRandom(player), oldPlayerSeed);
                        setJavaRandomGaussianState(
                            entityRandom(player), oldPlayerHaveGaussian,
                            oldPlayerGaussian);
                    }
                    if (player != null
                            && respawnInvulnerabilityField != null)
                        respawnInvulnerabilityField.setInt(
                            player, oldRespawnInvulnerability);
                    if (oldPlayerTeam != null)
                        oldPlayerTeam.setAllowFriendlyFire(
                            oldPlayerTeamFriendlyFire);
                    if (player != null)
                        oracleCaptureAuthoritativePlayerLocked(player);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Ordinary server EntityEnderPearl.onImpact boundary: all 32 portal
     * particle payloads, optional Endermite construction, teleport, FALL
     * damage feedback, and every participating continuation cursor. */
    private String oracleEnderPearlImpactLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "ender_pearl_impact_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.world.WorldServer world = null;
            net.minecraft.entity.item.EntityEnderPearl pearl = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            OracleWorldEventCapture events = null;
            JsonObject oldSeedHelper = null;
            java.util.ArrayList<net.minecraft.entity.monster.EntityEndermite>
                spawned = new java.util.ArrayList<
                    net.minecraft.entity.monster.EntityEndermite>();
            java.lang.reflect.Field respawnField = null;
            long oldPlayerSeed = -1L, oldMathSeed = -1L;
            long oldUuidSeed = -1L;
            int oldNextId = -1, oldRespawn = 0;
            double oldPlayerGaussian = 0.0D;
            boolean oldPlayerHaveGaussian = false;
            boolean oldUuidPinned = false;
            boolean oldUuidFixtureIsolation = false;
            String oldMobSpawning = null;
            try {
                long pearlSeed = action.get("pearl_seed48").getAsLong();
                long playerSeed = action.get("player_seed48").getAsLong();
                long mathSeed = action.get("math_seed48").getAsLong();
                long entitySeed = action.get("entity_seed48").getAsLong();
                long uuidSeed = action.get("server_uuid_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                boolean mobSpawning =
                    action.get("do_mob_spawning").getAsBoolean();
                float health = action.get("health").getAsFloat();
                int hurtResistant =
                    action.get("hurt_resistant_time").getAsInt();
                float lastDamage = action.get("last_damage").getAsFloat();
                double x = action.get("x").getAsDouble();
                double y = action.get("y").getAsDouble();
                double z = action.get("z").getAsDouble();
                if (pearlSeed < 0L || pearlSeed >= (1L << 48)
                        || playerSeed < 0L || playerSeed >= (1L << 48)
                        || mathSeed < 0L || mathSeed >= (1L << 48)
                        || entitySeed < 0L || entitySeed >= (1L << 48)
                        || uuidSeed < 0L || uuidSeed >= (1L << 48)
                        || nextId <= 0 || nextId > Integer.MAX_VALUE - 2
                        || health <= 5.0F || health > 20.0F
                        || hurtResistant < 0 || hurtResistant > 20
                        || lastDamage < 0.0F
                        || !Double.isFinite(x) || !Double.isFinite(y)
                        || !Double.isFinite(z)
                        || x < 16.0D || x > 32.0D
                        || y < 200.0D || y > 240.0D
                        || z < 16.0D || z > 32.0D)
                    return err("invalid Ender Pearl impact fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                world.getChunkProvider().provideChunk(
                    net.minecraft.util.math.MathHelper.floor(x) >> 4,
                    net.minecraft.util.math.MathHelper.floor(z) >> 4);
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldSeedHelper = oracleSeedHelperState();
                oldNextId = nextEntityId();
                oldUuidSeed = javaRandomSeed48(oracleServerUuidRandom);
                oldUuidPinned = oracleServerUuidPinned;
                oldUuidFixtureIsolation = oracleServerUuidFixtureIsolation;
                oldMathSeed = mathRandomSeed48();
                oldPlayerSeed = javaRandomSeed48(entityRandom(player));
                oldPlayerHaveGaussian =
                    javaRandomHaveNextGaussian(entityRandom(player));
                oldPlayerGaussian =
                    javaRandomNextGaussian(entityRandom(player));
                oldMobSpawning =
                    world.getGameRules().getString("doMobSpawning");
                respawnField =
                    net.minecraft.entity.player.EntityPlayerMP.class
                        .getDeclaredField("respawnInvulnerabilityTicks");
                respawnField.setAccessible(true);
                oldRespawn = respawnField.getInt(player);

                player.dismountRidingEntity();
                player.setEntityInvulnerable(false);
                player.capabilities.disableDamage = false;
                respawnField.setInt(player, 0);
                player.inventory.clear();
                player.clearActivePotions();
                player.setAbsorptionAmount(0.0F);
                player.setLocationAndAngles(
                    24.5D, 220.0D, 24.5D, 37.5F, -15.0F);
                player.motionX = 0.25D;
                player.motionY = -0.5D;
                player.motionZ = 0.75D;
                player.onGround = true;
                player.fallDistance = 7.0F;
                player.setHealth(health);
                player.hurtTime = 0;
                player.maxHurtTime = 0;
                player.hurtResistantTime = hurtResistant;
                player.limbSwingAmount = 0.0F;
                player.attackedAtYaw = 0.0F;
                player.velocityChanged = false;
                java.lang.reflect.Field lastDamageField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("lastDamage");
                java.lang.reflect.Field entityAgeField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("entityAge");
                java.lang.reflect.Field exhaustionField =
                    net.minecraft.util.FoodStats.class
                        .getDeclaredField("foodExhaustionLevel");
                lastDamageField.setAccessible(true);
                entityAgeField.setAccessible(true);
                exhaustionField.setAccessible(true);
                lastDamageField.setFloat(player, lastDamage);
                entityAgeField.setInt(player, 42);
                exhaustionField.setFloat(player.getFoodStats(), 0.0F);
                setJavaRandomSeed48(entityRandom(player), playerSeed);
                setJavaRandomGaussianState(
                    entityRandom(player), false, 0.0D);
                setMathRandomSeed48(mathSeed);
                world.getGameRules().setOrCreateGameRule(
                    "doMobSpawning", mobSpawning ? "true" : "false");

                pearl = new net.minecraft.entity.item.EntityEnderPearl(
                    world, player);
                pearl.setLocationAndAngles(x, y, z, 12.5F, 3.0F);
                setJavaRandomSeed48(entityRandom(pearl), pearlSeed);
                setJavaRandomGaussianState(
                    entityRandom(pearl), false, 0.0D);

                java.lang.reflect.Field currentSeed =
                    com.microsoft.Malmo.Utils.SeedHelper.class
                        .getDeclaredField("currentSeed");
                currentSeed.setAccessible(true);
                currentSeed.set(null, Long.valueOf(0L));
                setJavaRandomSeed48(
                    oracleSeedHelperGeneratorEnsure("entity"), entitySeed);
                setJavaRandomGaussianState(
                    oracleSeedHelperGenerator("entity"), false, 0.0D);
                setJavaRandomSeed48(oracleServerUuidRandom, uuidSeed);
                oracleServerUuidPinned = true;
                oracleServerUuidFixtureIsolation = true;
                setNextEntityId(nextId);

                int bx = net.minecraft.util.math.MathHelper.floor(x);
                int by = net.minecraft.util.math.MathHelper.floor(y);
                int bz = net.minecraft.util.math.MathHelper.floor(z);
                events = new OracleWorldEventCapture(
                    bx - 8, by - 8, bz - 8, bx + 8, by + 8, bz + 8);
                events.captureParticles = true;
                events.captureEndermiteSpawns = true;
                world.addEventListener(events);
                java.lang.reflect.Method impact =
                    net.minecraft.entity.item.EntityEnderPearl.class
                        .getDeclaredMethod("onImpact", RayTraceResult.class);
                impact.setAccessible(true);
                impact.invoke(pearl, new RayTraceResult(
                    new net.minecraft.util.math.Vec3d(x, y, z),
                    net.minecraft.util.EnumFacing.UP,
                    new BlockPos(bx, by, bz)));

                spawned.addAll(events.endermites);
                JsonArray endermites = new JsonArray();
                JsonArray loadedOrder = new JsonArray();
                for (net.minecraft.entity.monster.EntityEndermite endermite
                        : spawned) {
                    JsonObject row = new JsonObject();
                    row.addProperty("eid", endermite.getEntityId());
                    row.add("position_bits", oracleEntityDoubleBits(
                        endermite.posX, endermite.posY, endermite.posZ));
                    row.add("motion_bits", oracleEntityDoubleBits(
                        endermite.motionX, endermite.motionY,
                        endermite.motionZ));
                    row.addProperty("yaw_bits",
                        oracleFloatBits(endermite.rotationYaw));
                    row.addProperty("pitch_bits",
                        oracleFloatBits(endermite.rotationPitch));
                    row.addProperty("health_bits",
                        oracleFloatBits(endermite.getHealth()));
                    row.addProperty("player_spawned",
                        endermite.isSpawnedByPlayer());
                    row.addProperty("lifetime", ((Integer)
                        oraclePrivateField(endermite,
                            net.minecraft.entity.monster.EntityEndermite.class,
                            "lifetime")).intValue());
                    row.addProperty("seed48",
                        javaRandomSeed48(entityRandom(endermite)));
                    row.addProperty("have_gaussian",
                        javaRandomHaveNextGaussian(entityRandom(endermite)));
                    row.addProperty("gaussian_bits", oracleDoubleBits(
                        javaRandomNextGaussian(entityRandom(endermite))));
                    row.addProperty("uuid_most",
                        endermite.getUniqueID().getMostSignificantBits());
                    row.addProperty("uuid_least",
                        endermite.getUniqueID().getLeastSignificantBits());
                    endermites.add(row);
                    loadedOrder.add(
                        new JsonPrimitive(endermite.getEntityId()));
                }
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("pearl_dead", pearl.isDead);
                out.addProperty("pearl_seed48",
                    javaRandomSeed48(entityRandom(pearl)));
                out.addProperty("pearl_have_gaussian",
                    javaRandomHaveNextGaussian(entityRandom(pearl)));
                out.addProperty("pearl_gaussian_bits", oracleDoubleBits(
                    javaRandomNextGaussian(entityRandom(pearl))));
                out.add("particles", events.particlesToJson());
                out.add("endermites", endermites);
                out.add("loaded_order", loadedOrder);
                out.add("player_position_bits", oracleEntityDoubleBits(
                    player.posX, player.posY, player.posZ));
                out.add("player_motion_bits", oracleEntityDoubleBits(
                    player.motionX, player.motionY, player.motionZ));
                out.addProperty("player_health_bits",
                    oracleFloatBits(player.getHealth()));
                out.addProperty("player_fall_distance_bits",
                    oracleFloatBits(player.fallDistance));
                out.addProperty("player_hurt_time", player.hurtTime);
                out.addProperty("player_max_hurt_time",
                    player.maxHurtTime);
                out.addProperty("player_hurt_resistant_time",
                    player.hurtResistantTime);
                out.addProperty("player_last_damage_bits",
                    oracleFloatBits(lastDamageField.getFloat(player)));
                out.addProperty("player_entity_age",
                    entityAgeField.getInt(player));
                out.addProperty("player_limb_swing_amount_bits",
                    oracleFloatBits(player.limbSwingAmount));
                out.addProperty("player_attacked_yaw_bits",
                    oracleFloatBits(player.attackedAtYaw));
                out.addProperty("player_velocity_changed",
                    player.velocityChanged);
                out.addProperty("player_exhaustion_bits", oracleFloatBits(
                    exhaustionField.getFloat(player.getFoodStats())));
                out.addProperty("player_seed48",
                    javaRandomSeed48(entityRandom(player)));
                out.addProperty("math_seed48", mathRandomSeed48());
                out.addProperty("entity_seed48",
                    oracleSeedHelperGeneratorSeed48("entity"));
                out.addProperty("server_uuid_seed48",
                    javaRandomSeed48(oracleServerUuidRandom));
                out.addProperty("next_entity_id", nextEntityId());
                return out.toString();
            } catch (Throwable t) {
                return err("ender_pearl_impact_locked: " + t);
            } finally {
                if (world != null && events != null) try {
                    world.removeEventListener(events);
                } catch (Throwable ignored) { }
                if (world != null)
                    for (net.minecraft.entity.monster.EntityEndermite endermite
                            : spawned)
                        try {
                            world.removeEntityDangerously(endermite);
                        } catch (Throwable ignored) { }
                try {
                    if (world != null && oldMobSpawning != null)
                        world.getGameRules().setOrCreateGameRule(
                            "doMobSpawning", oldMobSpawning);
                    if (player != null && saved != null)
                        player.readFromNBT(saved);
                    if (oldSeedHelper != null)
                        oracleRestoreSeedHelperState(oldSeedHelper);
                    if (oldNextId > 0) setNextEntityId(oldNextId);
                    if (oldUuidSeed >= 0L)
                        setJavaRandomSeed48(
                            oracleServerUuidRandom, oldUuidSeed);
                    oracleServerUuidPinned = oldUuidPinned;
                    oracleServerUuidFixtureIsolation =
                        oldUuidFixtureIsolation;
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (player != null && oldPlayerSeed >= 0L) {
                        setJavaRandomSeed48(
                            entityRandom(player), oldPlayerSeed);
                        setJavaRandomGaussianState(
                            entityRandom(player), oldPlayerHaveGaussian,
                            oldPlayerGaussian);
                    }
                    if (player != null && respawnField != null)
                        respawnField.setInt(player, oldRespawn);
                    if (player != null)
                        oracleCaptureAuthoritativePlayerLocked(player);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** EntityEnderPearl's End Gateway early-return branch. Exact exits and a
     * cooling gateway lock both the teleport/no-teleport outcomes without
     * involving outer-island generation. */
    private String oracleEnderPearlGatewayLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "ender_pearl_gateway_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.world.WorldServer world = null;
            net.minecraft.entity.item.EntityEnderPearl pearl = null;
            net.minecraft.nbt.NBTTagCompound savedPlayer = null;
            net.minecraft.block.state.IBlockState oldState = null;
            net.minecraft.nbt.NBTTagCompound oldTile = null;
            BlockPos gatePos = new BlockPos(8, 230, 8);
            try {
                long pearlSeed = action.get("pearl_seed48").getAsLong();
                int exitX = action.get("exit_x").getAsInt();
                int exitY = action.get("exit_y").getAsInt();
                int exitZ = action.get("exit_z").getAsInt();
                int cooldown = action.get("cooldown").getAsInt();
                if (pearlSeed < 0L || pearlSeed >= (1L << 48)
                        || Math.abs((long)exitX) > 1000000L
                        || exitY < 1 || exitY > 254
                        || Math.abs((long)exitZ) > 1000000L
                        || cooldown < 0 || cooldown > 100)
                    return err("invalid Ender Pearl gateway fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                world = server.worldServerForDimension(1);
                world.getChunkProvider().provideChunk(0, 0);
                savedPlayer = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                player.setLocationAndAngles(
                    24.5D, 220.0D, 24.5D, 37.5F, -15.0F);
                player.motionX = 0.25D;
                player.motionY = -0.5D;
                player.motionZ = 0.75D;
                player.onGround = true;
                player.fallDistance = 7.0F;

                oldState = world.getBlockState(gatePos);
                net.minecraft.tileentity.TileEntity prior =
                    world.getTileEntity(gatePos);
                if (prior != null)
                    oldTile = prior.writeToNBT(
                        new net.minecraft.nbt.NBTTagCompound());
                world.setBlockState(gatePos,
                    net.minecraft.init.Blocks.END_GATEWAY
                        .getDefaultState(), 3);
                net.minecraft.tileentity.TileEntity tile =
                    world.getTileEntity(gatePos);
                if (!(tile instanceof
                        net.minecraft.tileentity.TileEntityEndGateway))
                    return err("could not stage End Gateway");
                net.minecraft.tileentity.TileEntityEndGateway gateway =
                    (net.minecraft.tileentity.TileEntityEndGateway)tile;
                gateway.setExactPosition(
                    new BlockPos(exitX, exitY, exitZ));
                java.lang.reflect.Field cooldownField =
                    net.minecraft.tileentity.TileEntityEndGateway.class
                        .getDeclaredField("teleportCooldown");
                cooldownField.setAccessible(true);
                cooldownField.setInt(gateway, cooldown);

                pearl = new net.minecraft.entity.item.EntityEnderPearl(
                    world, player);
                pearl.setLocationAndAngles(
                    8.5D, 230.5D, 8.5D, 12.5F, 3.0F);
                setJavaRandomSeed48(entityRandom(pearl), pearlSeed);
                setJavaRandomGaussianState(
                    entityRandom(pearl), false, 0.0D);
                java.lang.reflect.Method impact =
                    net.minecraft.entity.item.EntityEnderPearl.class
                        .getDeclaredMethod("onImpact", RayTraceResult.class);
                impact.setAccessible(true);
                impact.invoke(pearl, new RayTraceResult(
                    new net.minecraft.util.math.Vec3d(
                        8.5D, 230.5D, 8.5D),
                    net.minecraft.util.EnumFacing.UP, gatePos));

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("pearl_dead", pearl.isDead);
                out.addProperty("pearl_seed48",
                    javaRandomSeed48(entityRandom(pearl)));
                out.addProperty("pearl_have_gaussian",
                    javaRandomHaveNextGaussian(entityRandom(pearl)));
                out.addProperty("pearl_gaussian_bits", oracleDoubleBits(
                    javaRandomNextGaussian(entityRandom(pearl))));
                out.add("player_position_bits", oracleEntityDoubleBits(
                    player.posX, player.posY, player.posZ));
                out.add("player_motion_bits", oracleEntityDoubleBits(
                    player.motionX, player.motionY, player.motionZ));
                out.addProperty("player_on_ground", player.onGround);
                out.addProperty("player_fall_distance_bits",
                    oracleFloatBits(player.fallDistance));
                out.addProperty("gateway_cooldown",
                    cooldownField.getInt(gateway));
                return out.toString();
            } catch (Throwable t) {
                return err("ender_pearl_gateway_locked: " + t);
            } finally {
                try {
                    if (world != null && oldState != null) {
                        world.setBlockState(gatePos, oldState, 3);
                        if (oldTile != null) {
                            net.minecraft.tileentity.TileEntity tile =
                                world.getTileEntity(gatePos);
                            if (tile != null) tile.readFromNBT(oldTile);
                        }
                    }
                    if (player != null && savedPlayer != null) {
                        player.readFromNBT(savedPlayer);
                        oracleCaptureAuthoritativePlayerLocked(player);
                    }
                } catch (Throwable ignored) { }
            }
        }
    }

    /** EntityThrowable construction plus player-heading seam shared by eggs,
     * snowballs, XP bottles, Ender Pearls, and thrown potions. */
    private String oracleThrowableLaunchLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "throwable_launch_locked requires a parked oracle server");
            JsonObject oldSeedHelper = null;
            int oldNextEntityId = -1;
            long oldUuidSeed = -1L;
            boolean oldUuidPinned = false;
            boolean oldUuidFixtureIsolation = false;
            try {
                String kind = action.get("kind").getAsString();
                long entitySeed = action.get("entity_seed48").getAsLong();
                long uuidSeed = action.get("server_uuid_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                double x = action.get("x").getAsDouble();
                double y = action.get("y").getAsDouble();
                double z = action.get("z").getAsDouble();
                double vx = action.get("vx").getAsDouble();
                double vy = action.get("vy").getAsDouble();
                double vz = action.get("vz").getAsDouble();
                float yaw = action.get("yaw").getAsFloat();
                float pitch = action.get("pitch").getAsFloat();
                boolean onGround = action.get("on_ground").getAsBoolean();
                int ticks = action.has("ticks")
                    ? action.get("ticks").getAsInt() : 0;
                java.util.Random expectedEntityCursor =
                    new java.util.Random();
                setJavaRandomSeed48(expectedEntityCursor, entitySeed);
                long expectedPrivateSeed = expectedEntityCursor.nextLong();
                long expectedEntitySeed =
                    javaRandomSeed48(expectedEntityCursor);
                java.util.Random expectedPrivateRandom =
                    new java.util.Random(expectedPrivateSeed);
                long expectedPrivateSeed48 =
                    javaRandomSeed48(expectedPrivateRandom);
                java.util.Random expectedUuidCursor =
                    new java.util.Random();
                setJavaRandomSeed48(expectedUuidCursor, uuidSeed);
                long expectedUuidMost =
                    expectedUuidCursor.nextLong() & -61441L | 16384L;
                long expectedUuidLeast =
                    expectedUuidCursor.nextLong()
                        & 4611686018427387903L | Long.MIN_VALUE;
                long expectedUuidSeed =
                    javaRandomSeed48(expectedUuidCursor);
                if ((!kind.equals("egg") && !kind.equals("snowball")
                            && !kind.equals("xp_bottle")
                            && !kind.equals("ender_pearl")
                            && !kind.equals("splash_potion")
                            && !kind.equals("lingering_potion"))
                        || entitySeed < 0L || entitySeed >= (1L << 48)
                        || uuidSeed < 0L || uuidSeed >= (1L << 48)
                        || nextId <= 0 || nextId == Integer.MAX_VALUE
                        || ticks < 0 || ticks > 200
                        || !Double.isFinite(x) || !Double.isFinite(y)
                        || !Double.isFinite(z) || !Double.isFinite(vx)
                        || !Double.isFinite(vy) || !Double.isFinite(vz)
                        || !Float.isFinite(yaw) || !Float.isFinite(pitch))
                    return err("invalid throwable launch fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player =
                    server.getPlayerList().getPlayers().get(0);
                net.minecraft.world.WorldServer world =
                    server.worldServerForDimension(-1);

                oldSeedHelper = oracleSeedHelperState();
                oldNextEntityId = nextEntityId();
                oldUuidSeed = javaRandomSeed48(oracleServerUuidRandom);
                oldUuidPinned = oracleServerUuidPinned;
                oldUuidFixtureIsolation = oracleServerUuidFixtureIsolation;
                java.lang.reflect.Field currentSeed =
                    com.microsoft.Malmo.Utils.SeedHelper.class
                        .getDeclaredField("currentSeed");
                currentSeed.setAccessible(true);
                currentSeed.set(null, Long.valueOf(0L));
                setJavaRandomSeed48(
                    oracleSeedHelperGeneratorEnsure("entity"), entitySeed);
                setJavaRandomGaussianState(
                    oracleSeedHelperGenerator("entity"), false, 0.0D);
                setJavaRandomSeed48(oracleServerUuidRandom, uuidSeed);
                oracleServerUuidPinned = true;
                oracleServerUuidFixtureIsolation = true;
                setNextEntityId(nextId);

                double oldX = player.posX, oldY = player.posY;
                double oldZ = player.posZ, oldVx = player.motionX;
                double oldVy = player.motionY, oldVz = player.motionZ;
                float oldYaw = player.rotationYaw;
                float oldPitch = player.rotationPitch;
                boolean oldOnGround = player.onGround;
                net.minecraft.entity.projectile.EntityThrowable projectile;
                try {
                    player.setPositionAndRotation(x, y, z, yaw, pitch);
                    player.motionX = vx;
                    player.motionY = vy;
                    player.motionZ = vz;
                    player.onGround = onGround;
                    if (kind.equals("egg"))
                        projectile = new net.minecraft.entity.projectile
                            .EntityEgg(world, player);
                    else if (kind.equals("snowball"))
                        projectile = new net.minecraft.entity.projectile
                            .EntitySnowball(world, player);
                    else if (kind.equals("xp_bottle"))
                        projectile = new net.minecraft.entity.item
                            .EntityExpBottle(world, player);
                    else if (kind.equals("ender_pearl"))
                        projectile = new net.minecraft.entity.item
                            .EntityEnderPearl(world, player);
                    else {
                        net.minecraft.item.ItemStack stack =
                            net.minecraft.potion.PotionUtils
                                .addPotionToItemStack(
                                    new net.minecraft.item.ItemStack(
                                        kind.equals("splash_potion")
                                            ? net.minecraft.init.Items
                                                .SPLASH_POTION
                                            : net.minecraft.init.Items
                                                .LINGERING_POTION),
                                    net.minecraft.init.PotionTypes.WATER);
                        projectile = new net.minecraft.entity.projectile
                            .EntityPotion(world, player, stack);
                    }
                    /* Entity.nextEntityID and SeedHelper's generator are
                     * process globals shared with the integrated client.
                     * Pin the newly constructed server object itself so a
                     * client constructor cannot steal this fixture's cursor
                     * between our global write and the constructor call. */
                    projectile.setEntityId(nextId);
                    projectile.setUniqueId(new java.util.UUID(
                        expectedUuidMost, expectedUuidLeast));
                    setJavaRandomSeed48(
                        entityRandom(projectile), expectedPrivateSeed48);
                    setJavaRandomGaussianState(
                        entityRandom(projectile), false, 0.0D);
                    float pitchOffset = kind.equals("xp_bottle")
                        || kind.equals("splash_potion")
                        || kind.equals("lingering_potion") ? -20.0F : 0.0F;
                    float velocity = kind.equals("xp_bottle")
                        ? 0.7F : kind.equals("splash_potion")
                            || kind.equals("lingering_potion")
                            ? 0.5F : 1.5F;
                    projectile.setHeadingFromThrower(
                        player, pitch, yaw, pitchOffset, velocity, 1.0F);
                } finally {
                    player.setPositionAndRotation(
                        oldX, oldY, oldZ, oldYaw, oldPitch);
                    player.motionX = oldVx;
                    player.motionY = oldVy;
                    player.motionZ = oldVz;
                    player.onGround = oldOnGround;
                }
                for (int tick = 0; tick < ticks && !projectile.isDead;
                        ++tick) {
                    ++projectile.ticksExisted;
                    projectile.onUpdate();
                }

                java.util.Random random = entityRandom(projectile);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("eid", projectile.getEntityId());
                out.add("position_bits", oracleEntityDoubleBits(
                    projectile.posX, projectile.posY, projectile.posZ));
                out.add("motion_bits", oracleEntityDoubleBits(
                    projectile.motionX, projectile.motionY,
                    projectile.motionZ));
                JsonArray rotation = new JsonArray();
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(projectile.rotationYaw)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(projectile.rotationPitch)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(projectile.prevRotationYaw)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(projectile.prevRotationPitch)));
                out.add("rotation_bits", rotation);
                out.addProperty("seed48", javaRandomSeed48(random));
                out.addProperty("have_gaussian",
                    javaRandomHaveNextGaussian(random));
                out.addProperty("next_gaussian_bits",
                    oracleDoubleBits(javaRandomNextGaussian(random)));
                out.addProperty("uuid_most",
                    projectile.getUniqueID().getMostSignificantBits());
                out.addProperty("uuid_least",
                    projectile.getUniqueID().getLeastSignificantBits());
                out.addProperty("entity_seed48",
                    expectedEntitySeed);
                out.addProperty("server_uuid_seed48",
                    expectedUuidSeed);
                out.addProperty("next_entity_id", nextId + 1);
                if (action.has("ticks")) {
                    out.addProperty("ticks_existed", projectile.ticksExisted);
                    out.addProperty("ticks_in_air", ((Integer)
                        oraclePrivateField(projectile,
                            net.minecraft.entity.projectile
                                .EntityThrowable.class,
                            "ticksInAir")).intValue());
                    Object ignored = oraclePrivateField(projectile,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "ignoreEntity");
                    out.addProperty("ignore_player", ignored == player);
                    out.addProperty("ignore_player_time", ((Integer)
                        oraclePrivateField(projectile,
                            net.minecraft.entity.projectile
                                .EntityThrowable.class,
                            "ignoreTime")).intValue());
                    out.addProperty("portal_cooldown", ((Integer)
                        oraclePrivateField(projectile,
                            net.minecraft.entity.Entity.class,
                            "timeUntilPortal")).intValue());
                    out.addProperty("dead", projectile.isDead);
                }
                return out.toString();
            } catch (Throwable t) {
                return err("throwable_launch_locked: " + t);
            } finally {
                try {
                    if (oldSeedHelper != null)
                        oracleRestoreSeedHelperState(oldSeedHelper);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                    if (oldUuidSeed >= 0L)
                        setJavaRandomSeed48(
                            oracleServerUuidRandom, oldUuidSeed);
                    oracleServerUuidPinned = oldUuidPinned;
                    oracleServerUuidFixtureIsolation =
                        oldUuidFixtureIsolation;
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Entity.onEntityUpdate portal reconstruction for throwables and Boat. The
     * destination portal and Teleporter cache are staged explicitly so this
     * measures the NBT-copy boundary without an unrelated portal search or
     * construction RNG path. */
    private String oracleThrowablePortalLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "throwable_portal_locked requires a parked oracle server");
            JsonObject oldSeedHelper = null;
            int oldNextEntityId = -1;
            long oldUuidSeed = -1L;
            boolean oldUuidPinned = false;
            boolean oldUuidFixtureIsolation = false;
            net.minecraft.entity.Entity projectile = null;
            net.minecraft.entity.Entity replacement = null;
            net.minecraft.world.WorldServer source = null;
            net.minecraft.world.WorldServer target = null;
            net.minecraft.world.Teleporter teleporter = null;
            it.unimi.dsi.fastutil.longs.Long2ObjectMap<Object> cache = null;
            Object oldCacheValue = null;
            long cacheKey = 0L;
            net.minecraft.util.math.BlockPos[] portalCells = null;
            net.minecraft.block.state.IBlockState[] oldPortalStates = null;
            net.minecraft.util.math.BlockPos obstructionPos = null;
            net.minecraft.block.state.IBlockState oldObstructionState = null;
            try {
                String kind = action.get("kind").getAsString();
                long oldEntitySeed = action.get("entity_seed48").getAsLong();
                long cloneGeneratorSeed =
                    action.get("clone_generator_seed48").getAsLong();
                long uuidSeed = action.get("server_uuid_seed48").getAsLong();
                int oldEid = action.get("eid").getAsInt();
                int cloneNextId = action.get("next_entity_id").getAsInt();
                double x = action.get("x").getAsDouble();
                double y = action.get("y").getAsDouble();
                double z = action.get("z").getAsDouble();
                double vx = action.get("vx").getAsDouble();
                double vy = action.get("vy").getAsDouble();
                double vz = action.get("vz").getAsDouble();
                float yaw = action.get("yaw").getAsFloat();
                float pitch = action.get("pitch").getAsFloat();
                int age = action.get("ticks_existed").getAsInt();
                int ticksInAir = action.get("ticks_in_air").getAsInt();
                int continuationTicks = action.has("continuation_ticks")
                    ? action.get("continuation_ticks").getAsInt() : 0;
                boolean destinationLoaded = action.has("destination_loaded")
                    && action.get("destination_loaded").getAsBoolean();
                int portalX = action.get("portal_x").getAsInt();
                int portalY = action.get("portal_y").getAsInt();
                int portalZ = action.get("portal_z").getAsInt();
                String portalAxis = action.has("portal_axis")
                    ? action.get("portal_axis").getAsString() : "x";
                double lastPortalVecX = action.has("last_portal_vec_x")
                    ? action.get("last_portal_vec_x").getAsDouble() : 0.5D;
                double lastPortalVecY = action.has("last_portal_vec_y")
                    ? action.get("last_portal_vec_y").getAsDouble() : 0.5D;
                String teleportDirection = action.has("teleport_direction")
                    ? action.get("teleport_direction").getAsString()
                    : "north";
                String obstructionSide = action.has("obstruction_side")
                    ? action.get("obstruction_side").getAsString() : "none";
                net.minecraft.util.EnumFacing teleportFacing;
                if (teleportDirection.equals("south"))
                    teleportFacing = net.minecraft.util.EnumFacing.SOUTH;
                else if (teleportDirection.equals("west"))
                    teleportFacing = net.minecraft.util.EnumFacing.WEST;
                else if (teleportDirection.equals("north"))
                    teleportFacing = net.minecraft.util.EnumFacing.NORTH;
                else if (teleportDirection.equals("east"))
                    teleportFacing = net.minecraft.util.EnumFacing.EAST;
                else
                    return err("invalid throwable teleport direction");
                if ((!kind.equals("egg") && !kind.equals("snowball")
                            && !kind.equals("xp_bottle")
                            && !kind.equals("ender_pearl")
                            && !kind.equals("boat"))
                        || oldEntitySeed < 0L
                        || oldEntitySeed >= (1L << 48)
                        || cloneGeneratorSeed < 0L
                        || cloneGeneratorSeed >= (1L << 48)
                        || uuidSeed < 0L || uuidSeed >= (1L << 48)
                        || oldEid <= 0 || cloneNextId <= 0
                        || cloneNextId == Integer.MAX_VALUE
                        || age < 0 || ticksInAir < 0
                        || continuationTicks < 0 || continuationTicks > 20
                        || portalY < 4 || portalY > 250
                        || (!portalAxis.equals("x")
                            && !portalAxis.equals("z"))
                        || (!obstructionSide.equals("none")
                            && !obstructionSide.equals("positive")
                            && !obstructionSide.equals("negative"))
                        || !Double.isFinite(lastPortalVecX)
                        || !Double.isFinite(lastPortalVecY)
                        || lastPortalVecX < 0.0D || lastPortalVecX > 1.0D
                        || lastPortalVecY < 0.0D || lastPortalVecY > 1.0D
                        || !Double.isFinite(x) || !Double.isFinite(y)
                        || !Double.isFinite(z) || !Double.isFinite(vx)
                        || !Double.isFinite(vy) || !Double.isFinite(vz)
                        || !Float.isFinite(yaw) || !Float.isFinite(pitch))
                    return err("invalid throwable portal fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player =
                    server.getPlayerList().getPlayers().get(0);
                if (player.dimension != 0)
                    return err("throwable portal fixture requires player dim 0");
                source = server.worldServerForDimension(0);
                if (net.minecraftforge.common.DimensionManager.getWorld(-1)
                        == null)
                    net.minecraftforge.common.DimensionManager.initDimension(-1);
                target = server.worldServerForDimension(-1);
                if (source == null || target == null)
                    return err("missing portal fixture world");

                oldSeedHelper = oracleSeedHelperState();
                oldNextEntityId = nextEntityId();
                oldUuidSeed = javaRandomSeed48(oracleServerUuidRandom);
                oldUuidPinned = oracleServerUuidPinned;
                oldUuidFixtureIsolation = oracleServerUuidFixtureIsolation;

                if (kind.equals("boat")) {
                    net.minecraft.entity.item.EntityBoat boat =
                        new net.minecraft.entity.item.EntityBoat(source);
                    int variant = action.has("boat_variant")
                        ? action.get("boat_variant").getAsInt() : 0;
                    if (variant < 0 || variant > 5)
                        return err("invalid boat portal variant");
                    boat.setBoatType(net.minecraft.entity.item.EntityBoat.Type
                        .values()[variant]);
                    projectile = boat;
                } else if (kind.equals("egg"))
                    projectile = new net.minecraft.entity.projectile
                        .EntityEgg(source, player);
                else if (kind.equals("snowball"))
                    projectile = new net.minecraft.entity.projectile
                        .EntitySnowball(source, player);
                else if (kind.equals("xp_bottle"))
                    projectile = new net.minecraft.entity.item
                        .EntityExpBottle(source, player);
                else
                    projectile = new net.minecraft.entity.item
                        .EntityEnderPearl(source, player);
                projectile.setEntityId(oldEid);
                projectile.setUniqueId(java.util.UUID.fromString(
                    action.get("uuid").getAsString()));
                setJavaRandomSeed48(entityRandom(projectile), oldEntitySeed);
                setJavaRandomGaussianState(
                    entityRandom(projectile), false, 0.0D);
                projectile.setLocationAndAngles(x, y, z, yaw, pitch);
                projectile.motionX = vx;
                projectile.motionY = vy;
                projectile.motionZ = vz;
                projectile.ticksExisted = age;
                if (projectile instanceof
                        net.minecraft.entity.projectile.EntityThrowable) {
                    java.lang.reflect.Field ticksAirField =
                        net.minecraft.entity.projectile.EntityThrowable.class
                            .getDeclaredField("ticksInAir");
                    ticksAirField.setAccessible(true);
                    ticksAirField.setInt(projectile, ticksInAir);
                }
                java.lang.reflect.Field inPortalField =
                    net.minecraft.entity.Entity.class
                        .getDeclaredField("inPortal");
                java.lang.reflect.Field portalCounterField =
                    net.minecraft.entity.Entity.class
                        .getDeclaredField("portalCounter");
                java.lang.reflect.Field lastPortalPosField =
                    net.minecraft.entity.Entity.class
                        .getDeclaredField("lastPortalPos");
                java.lang.reflect.Field lastPortalVecField =
                    net.minecraft.entity.Entity.class
                        .getDeclaredField("lastPortalVec");
                java.lang.reflect.Field teleportDirectionField =
                    net.minecraft.entity.Entity.class
                        .getDeclaredField("teleportDirection");
                for (java.lang.reflect.Field field :
                        new java.lang.reflect.Field[] {
                            inPortalField, portalCounterField,
                            lastPortalPosField, lastPortalVecField,
                            teleportDirectionField})
                    field.setAccessible(true);
                inPortalField.setBoolean(projectile, true);
                portalCounterField.setInt(projectile, 1);
                lastPortalPosField.set(projectile,
                    new net.minecraft.util.math.BlockPos(
                        net.minecraft.util.math.MathHelper.floor(x),
                        net.minecraft.util.math.MathHelper.floor(y),
                        net.minecraft.util.math.MathHelper.floor(z)));
                lastPortalVecField.set(projectile,
                    new net.minecraft.util.math.Vec3d(
                        lastPortalVecX, lastPortalVecY, 0.0D));
                teleportDirectionField.set(projectile, teleportFacing);
                source.getChunkFromChunkCoords(
                    net.minecraft.util.math.MathHelper.floor(x) >> 4,
                    net.minecraft.util.math.MathHelper.floor(z) >> 4);
                if (!source.spawnEntity(projectile))
                    return err("could not spawn throwable portal fixture");

                java.util.ArrayList<net.minecraft.util.math.BlockPos> cells =
                    new java.util.ArrayList<
                        net.minecraft.util.math.BlockPos>();
                for (int pa = -1; pa <= 2; ++pa)
                    for (int py = portalY - 1; py <= portalY + 3; ++py)
                        cells.add(new net.minecraft.util.math.BlockPos(
                            portalAxis.equals("x") ? portalX + pa : portalX,
                            py,
                            portalAxis.equals("z") ? portalZ + pa : portalZ));
                portalCells = cells.toArray(
                    new net.minecraft.util.math.BlockPos[cells.size()]);
                oldPortalStates =
                    new net.minecraft.block.state.IBlockState[
                        portalCells.length];
                for (int i = 0; i < portalCells.length; ++i) {
                    net.minecraft.util.math.BlockPos pos = portalCells[i];
                    oldPortalStates[i] = target.getBlockState(pos);
                    int axisPosition = portalAxis.equals("x")
                        ? pos.getX() : pos.getZ();
                    int axisOrigin = portalAxis.equals("x")
                        ? portalX : portalZ;
                    boolean frame = axisPosition == axisOrigin - 1
                        || axisPosition == axisOrigin + 2
                        || pos.getY() == portalY - 1
                        || pos.getY() == portalY + 3;
                    net.minecraft.block.state.IBlockState state = frame
                        ? net.minecraft.init.Blocks.OBSIDIAN.getDefaultState()
                        : net.minecraft.init.Blocks.PORTAL.getDefaultState()
                            .withProperty(
                                net.minecraft.block.BlockPortal.AXIS,
                                portalAxis.equals("x")
                                    ? net.minecraft.util.EnumFacing.Axis.X
                                    : net.minecraft.util.EnumFacing.Axis.Z);
                    target.setBlockState(pos, state, 2);
                }
                if (!obstructionSide.equals("none")) {
                    int normalOffset = obstructionSide.equals("positive")
                        ? 1 : -1;
                    obstructionPos = new net.minecraft.util.math.BlockPos(
                        portalAxis.equals("z")
                            ? portalX + normalOffset : portalX,
                        portalY,
                        portalAxis.equals("x")
                            ? portalZ + normalOffset : portalZ);
                    oldObstructionState = target.getBlockState(obstructionPos);
                    target.setBlockState(
                        obstructionPos,
                        net.minecraft.init.Blocks.STONE.getDefaultState(), 2);
                }
                teleporter = target.getDefaultTeleporter();
                java.lang.reflect.Field cacheField =
                    net.minecraft.world.Teleporter.class.getDeclaredField(
                        "destinationCoordinateCache");
                cacheField.setAccessible(true);
                @SuppressWarnings("unchecked")
                it.unimi.dsi.fastutil.longs.Long2ObjectMap<Object> value =
                    (it.unimi.dsi.fastutil.longs.Long2ObjectMap<Object>)
                        cacheField.get(teleporter);
                cache = value;
                int scaledX = net.minecraft.util.math.MathHelper.floor(x / 8.0D);
                int scaledZ = net.minecraft.util.math.MathHelper.floor(z / 8.0D);
                cacheKey = net.minecraft.util.math.ChunkPos.asLong(
                    scaledX, scaledZ);
                oldCacheValue = cache.get(cacheKey);
                cache.put(cacheKey, teleporter.new PortalPosition(
                    new net.minecraft.util.math.BlockPos(
                        portalX, portalY, portalZ),
                    target.getTotalWorldTime()));

                java.lang.reflect.Field currentSeed =
                    com.microsoft.Malmo.Utils.SeedHelper.class
                        .getDeclaredField("currentSeed");
                currentSeed.setAccessible(true);
                currentSeed.set(null, Long.valueOf(0L));
                setJavaRandomSeed48(
                    oracleSeedHelperGeneratorEnsure("entity"),
                    cloneGeneratorSeed);
                setJavaRandomGaussianState(
                    oracleSeedHelperGenerator("entity"), false, 0.0D);
                setJavaRandomSeed48(oracleServerUuidRandom, uuidSeed);
                oracleServerUuidPinned = true;
                oracleServerUuidFixtureIsolation = true;
                setNextEntityId(cloneNextId);

                ++projectile.ticksExisted;
                projectile.onUpdate();
                for (net.minecraft.entity.Entity candidate
                        : target.loadedEntityList)
                    if (candidate.getUniqueID().equals(
                            projectile.getUniqueID())) {
                        replacement = candidate;
                        break;
                    }
                if (kind.equals("boat")
                        ? !(replacement instanceof
                            net.minecraft.entity.item.EntityBoat)
                        : !(replacement instanceof
                            net.minecraft.entity.projectile.EntityThrowable))
                    return err("portal replacement was not created");
                net.minecraft.entity.Entity moved = replacement;
                if (destinationLoaded) {
                    int minChunkX = (net.minecraft.util.math.MathHelper.floor(
                        moved.posX) - 32) >> 4;
                    int maxChunkX = (net.minecraft.util.math.MathHelper.floor(
                        moved.posX) + 32) >> 4;
                    int minChunkZ = (net.minecraft.util.math.MathHelper.floor(
                        moved.posZ) - 32) >> 4;
                    int maxChunkZ = (net.minecraft.util.math.MathHelper.floor(
                        moved.posZ) + 32) >> 4;
                    for (int chunkX = minChunkX;
                            chunkX <= maxChunkX; ++chunkX)
                        for (int chunkZ = minChunkZ;
                                chunkZ <= maxChunkZ; ++chunkZ)
                            target.getChunkFromChunkCoords(chunkX, chunkZ);
                }
                for (int tick = 0; tick < continuationTicks
                        && !moved.isDead; ++tick)
                    target.updateEntityWithOptionalForce(moved, true);
                java.util.Random random = entityRandom(moved);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("eid", moved.getEntityId());
                out.addProperty("dimension", moved.dimension);
                out.add("position_bits", oracleEntityDoubleBits(
                    moved.posX, moved.posY, moved.posZ));
                out.add("motion_bits", oracleEntityDoubleBits(
                    moved.motionX, moved.motionY, moved.motionZ));
                JsonArray rotation = new JsonArray();
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(moved.rotationYaw)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(moved.rotationPitch)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(moved.prevRotationYaw)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(moved.prevRotationPitch)));
                out.add("rotation_bits", rotation);
                out.addProperty("ticks_existed", moved.ticksExisted);
                net.minecraft.entity.projectile.EntityThrowable movedThrowable =
                    moved instanceof net.minecraft.entity.projectile
                        .EntityThrowable
                    ? (net.minecraft.entity.projectile.EntityThrowable)moved
                    : null;
                out.addProperty("ticks_in_air", movedThrowable == null ? 0
                    : ((Integer)oraclePrivateField(movedThrowable,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "ticksInAir")).intValue());
                out.addProperty("portal_counter", ((Integer)
                    oraclePrivateField(moved, net.minecraft.entity.Entity.class,
                        "portalCounter")).intValue());
                out.addProperty("portal_cooldown", moved.timeUntilPortal);
                out.addProperty("in_portal", ((Boolean)
                    oraclePrivateField(moved, net.minecraft.entity.Entity.class,
                        "inPortal")).booleanValue());
                out.addProperty("throwable_shake",
                    movedThrowable == null ? 0 : movedThrowable.throwableShake);
                out.addProperty("in_ground", movedThrowable != null
                    && ((Boolean)oraclePrivateField(movedThrowable,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "inGround")).booleanValue());
                out.addProperty("ticks_in_ground", movedThrowable == null ? 0
                    : ((Integer)oraclePrivateField(movedThrowable,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "ticksInGround")).intValue());
                out.addProperty("ignore_present",
                    movedThrowable != null && oraclePrivateField(movedThrowable,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "ignoreEntity") != null);
                out.addProperty("ignore_time", movedThrowable == null ? 0
                    : ((Integer)oraclePrivateField(movedThrowable,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "ignoreTime")).intValue());
                out.addProperty("owner_pending",
                    movedThrowable != null && oraclePrivateField(movedThrowable,
                        net.minecraft.entity.projectile.EntityThrowable.class,
                        "throwerName") != null);
                out.addProperty("pearl_private_thrower",
                    moved instanceof net.minecraft.entity.item.EntityEnderPearl
                        && oraclePrivateField(moved,
                            net.minecraft.entity.item.EntityEnderPearl.class,
                            "thrower") != null);
                if (moved instanceof net.minecraft.entity.item.EntityBoat) {
                    net.minecraft.entity.item.EntityBoat boat =
                        (net.minecraft.entity.item.EntityBoat)moved;
                    out.addProperty("boat_variant",
                        boat.getBoatType().ordinal());
                    out.addProperty("boat_damage_bits",
                        oracleFloatBits(boat.getDamageTaken()));
                    out.addProperty("boat_time_since_hit",
                        boat.getTimeSinceHit());
                    out.addProperty("boat_forward_direction",
                        boat.getForwardDirection());
                }
                net.minecraft.util.math.Vec3d movedPortalVec =
                    (net.minecraft.util.math.Vec3d)oraclePrivateField(
                        moved, net.minecraft.entity.Entity.class,
                        "lastPortalVec");
                JsonArray portalVecBits = new JsonArray();
                portalVecBits.add(new JsonPrimitive(
                    oracleDoubleBits(movedPortalVec.xCoord)));
                portalVecBits.add(new JsonPrimitive(
                    oracleDoubleBits(movedPortalVec.yCoord)));
                out.add("last_portal_vec_bits", portalVecBits);
                out.addProperty("teleport_direction", ((net.minecraft.util
                    .EnumFacing)oraclePrivateField(
                        moved, net.minecraft.entity.Entity.class,
                        "teleportDirection")).getHorizontalIndex());
                out.addProperty("seed48", javaRandomSeed48(random));
                out.addProperty("have_gaussian",
                    javaRandomHaveNextGaussian(random));
                out.addProperty("next_gaussian_bits",
                    oracleDoubleBits(javaRandomNextGaussian(random)));
                out.addProperty("uuid_most",
                    moved.getUniqueID().getMostSignificantBits());
                out.addProperty("uuid_least",
                    moved.getUniqueID().getLeastSignificantBits());
                out.addProperty("entity_seed48",
                    oracleSeedHelperGeneratorSeed48("entity"));
                out.addProperty("server_uuid_seed48",
                    javaRandomSeed48(oracleServerUuidRandom));
                out.addProperty("next_entity_id", nextEntityId());
                return out.toString();
            } catch (Throwable t) {
                return err("throwable_portal_locked: " + t);
            } finally {
                try {
                    if (source != null && projectile != null)
                        source.removeEntityDangerously(projectile);
                    if (target != null && replacement != null)
                        target.removeEntityDangerously(replacement);
                    if (target != null && portalCells != null
                            && oldPortalStates != null)
                        for (int i = 0; i < portalCells.length; ++i)
                            target.setBlockState(
                                portalCells[i], oldPortalStates[i], 2);
                    if (target != null && obstructionPos != null
                            && oldObstructionState != null)
                        target.setBlockState(
                            obstructionPos, oldObstructionState, 2);
                    if (cache != null) {
                        if (oldCacheValue == null) cache.remove(cacheKey);
                        else cache.put(cacheKey, oldCacheValue);
                    }
                    if (oldSeedHelper != null)
                        oracleRestoreSeedHelperState(oldSeedHelper);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                    if (oldUuidSeed >= 0L)
                        setJavaRandomSeed48(
                            oracleServerUuidRandom, oldUuidSeed);
                    oracleServerUuidPinned = oldUuidPinned;
                    oracleServerUuidFixtureIsolation =
                        oldUuidFixtureIsolation;
                } catch (Throwable ignored) { }
            }
        }
    }

    /** EntityEnderEye.moveTowards plus every server onUpdate boundary through
     * despawnTimer 81. This locks the private target clamp, render rotations,
     * entity RNG particle stream, and shatter-vs-drop terminal branch. */
    private String oracleEnderEyeTickLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "ender_eye_tick_locked requires a parked oracle server");
            net.minecraft.world.WorldServer world = null;
            OracleWorldEventCapture events = null;
            net.minecraft.entity.item.EntityEnderEye eye = null;
            java.util.ArrayList<net.minecraft.entity.item.EntityItem> spawned =
                new java.util.ArrayList<
                    net.minecraft.entity.item.EntityItem>();
            BlockPos waterPos = null;
            net.minecraft.block.state.IBlockState oldWaterState = null;
            long oldMathSeed = -1L;
            int oldNextEntityId = -1;
            try {
                long seed48 = action.get("seed48").getAsLong();
                long mathSeed48 = action.get("math_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                int ticks = action.get("ticks").getAsInt();
                boolean water = action.has("water")
                    && action.get("water").getAsBoolean();
                double x = action.get("x").getAsDouble();
                double y = action.get("y").getAsDouble();
                double z = action.get("z").getAsDouble();
                int targetX = action.get("target_x").getAsInt();
                int targetY = action.get("target_y").getAsInt();
                int targetZ = action.get("target_z").getAsInt();
                if (seed48 < 0L || seed48 >= (1L << 48)
                        || mathSeed48 < 0L
                        || mathSeed48 >= (1L << 48)
                        || nextId <= 0
                        || nextId > Integer.MAX_VALUE - 2
                        || ticks < 1 || ticks > 81
                        || !Double.isFinite(x) || !Double.isFinite(y)
                        || !Double.isFinite(z)
                        || Math.abs(x) > 1000000.0D
                        || y < 180.0D || y > 240.0D
                        || Math.abs(z) > 1000000.0D
                        || Math.abs((long)targetX) > 1000000L
                        || targetY < 0 || targetY > 255
                        || Math.abs((long)targetZ) > 1000000L)
                    return err("invalid Ender Eye fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                world = server.getPlayerList().getPlayers().get(0)
                    .getServerWorld();
                oldMathSeed = mathRandomSeed48();
                oldNextEntityId = nextEntityId();
                setMathRandomSeed48(mathSeed48);
                if (water) {
                    waterPos = new BlockPos(
                        net.minecraft.util.math.MathHelper.floor(x),
                        net.minecraft.util.math.MathHelper.floor(y),
                        net.minecraft.util.math.MathHelper.floor(z));
                    oldWaterState = world.getBlockState(waterPos);
                    world.setBlockState(
                        waterPos,
                        net.minecraft.init.Blocks.WATER.getDefaultState(), 2);
                }
                setNextEntityId(nextId);
                eye = new net.minecraft.entity.item.EntityEnderEye(
                    world, x, y, z);
                setJavaRandomSeed48(entityRandom(eye), seed48);
                setJavaRandomGaussianState(entityRandom(eye), false, 0.0D);
                eye.moveTowards(new BlockPos(targetX, targetY, targetZ));

                java.lang.reflect.Field targetXField =
                    net.minecraft.entity.item.EntityEnderEye.class
                        .getDeclaredField("targetX");
                java.lang.reflect.Field targetYField =
                    net.minecraft.entity.item.EntityEnderEye.class
                        .getDeclaredField("targetY");
                java.lang.reflect.Field targetZField =
                    net.minecraft.entity.item.EntityEnderEye.class
                        .getDeclaredField("targetZ");
                java.lang.reflect.Field timerField =
                    net.minecraft.entity.item.EntityEnderEye.class
                        .getDeclaredField("despawnTimer");
                java.lang.reflect.Field dropField =
                    net.minecraft.entity.item.EntityEnderEye.class
                        .getDeclaredField("shatterOrDrop");
                targetXField.setAccessible(true);
                targetYField.setAccessible(true);
                targetZField.setAccessible(true);
                timerField.setAccessible(true);
                dropField.setAccessible(true);

                int bx = net.minecraft.util.math.MathHelper.floor(x);
                int by = net.minecraft.util.math.MathHelper.floor(y);
                int bz = net.minecraft.util.math.MathHelper.floor(z);
                events = new OracleWorldEventCapture(
                    bx - 32, by - 32, bz - 32,
                    bx + 32, by + 32, bz + 32);
                events.captureParticles = true;
                events.captureEyeEvents = true;
                events.captureItemSpawns = true;
                world.addEventListener(events);

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("eid", eye.getEntityId());
                out.add("target_bits", oracleEntityDoubleBits(
                    targetXField.getDouble(eye),
                    targetYField.getDouble(eye),
                    targetZField.getDouble(eye)));
                out.addProperty(
                    "shatter_or_drop", dropField.getBoolean(eye));
                JsonArray rows = new JsonArray();
                for (int tick = 1; tick <= ticks; ++tick) {
                    int particleBefore = events.particles.size();
                    double nextX = eye.posX + eye.motionX;
                    double nextZ = eye.posZ + eye.motionZ;
                    float steerHorizontal =
                        net.minecraft.util.math.MathHelper.sqrt(
                            eye.motionX * eye.motionX
                                + eye.motionZ * eye.motionZ);
                    double steerDx = targetXField.getDouble(eye) - nextX;
                    double steerDz = targetZField.getDouble(eye) - nextZ;
                    float steerTargetHorizontal = (float)Math.sqrt(
                        steerDx * steerDx + steerDz * steerDz);
                    float steerAngle = (float)
                        net.minecraft.util.math.MathHelper.atan2(
                            steerDz, steerDx);
                    double steerSpeed = (double)steerHorizontal
                        + (double)(steerTargetHorizontal - steerHorizontal)
                            * 0.0025D;
                    double steerCos = Math.cos((double)steerAngle);
                    double steerSin = Math.sin((double)steerAngle);
                    /* World.updateEntityWithOptionalForce owns this base
                     * increment immediately before Entity.onUpdate. */
                    ++eye.ticksExisted;
                    eye.onUpdate();
                    JsonObject row = new JsonObject();
                    row.addProperty("tick", tick);
                    row.addProperty("alive", !eye.isDead);
                    row.addProperty("ticks_existed", eye.ticksExisted);
                    row.addProperty("despawn_timer", timerField.getInt(eye));
                    row.add("position_bits", oracleEntityDoubleBits(
                        eye.posX, eye.posY, eye.posZ));
                    row.add("motion_bits", oracleEntityDoubleBits(
                        eye.motionX, eye.motionY, eye.motionZ));
                    JsonArray steeringBits = new JsonArray();
                    steeringBits.add(new JsonPrimitive(
                        oracleFloatBits(steerHorizontal)));
                    steeringBits.add(new JsonPrimitive(
                        oracleFloatBits(steerTargetHorizontal)));
                    steeringBits.add(new JsonPrimitive(
                        oracleFloatBits(steerAngle)));
                    steeringBits.add(new JsonPrimitive(
                        oracleDoubleBits(steerSpeed)));
                    steeringBits.add(new JsonPrimitive(
                        oracleDoubleBits(steerCos)));
                    steeringBits.add(new JsonPrimitive(
                        oracleDoubleBits(steerSin)));
                    steeringBits.add(new JsonPrimitive(
                        oracleDoubleBits(steerCos * steerSpeed)));
                    steeringBits.add(new JsonPrimitive(
                        oracleDoubleBits(steerSin * steerSpeed)));
                    row.add("steering_bits", steeringBits);
                    row.addProperty(
                        "yaw_bits", oracleFloatBits(eye.rotationYaw));
                    row.addProperty(
                        "pitch_bits", oracleFloatBits(eye.rotationPitch));
                    row.addProperty("seed48",
                        javaRandomSeed48(entityRandom(eye)));
                    JsonArray particles = new JsonArray();
                    for (int index = particleBefore;
                            index < events.particles.size(); ++index) {
                        OracleWorldEventCapture.ParticleRecord particle =
                            events.particles.get(index);
                        JsonObject particleRow = new JsonObject();
                        particleRow.addProperty("id", particle.id);
                        particleRow.add(
                            "payload_bits", particle.payloadBits());
                        particles.add(particleRow);
                    }
                    row.add("particles", particles);
                    rows.add(row);
                }
                spawned.addAll(events.itemEntities);
                out.add("rows", rows);
                JsonArray items = new JsonArray();
                for (net.minecraft.entity.item.EntityItem item : spawned) {
                    net.minecraft.item.ItemStack stack = item.getEntityItem();
                    JsonObject row = new JsonObject();
                    row.addProperty("eid", item.getEntityId());
                    row.addProperty("item", stackId(stack));
                    row.addProperty("count", stackCount(stack));
                    row.addProperty("meta", stackMeta(stack));
                    row.add("position_bits", oracleEntityDoubleBits(
                        item.posX, item.posY, item.posZ));
                    row.add("motion_bits", oracleEntityDoubleBits(
                        item.motionX, item.motionY, item.motionZ));
                    row.addProperty(
                        "yaw_bits", oracleFloatBits(item.rotationYaw));
                    row.addProperty(
                        "hover_bits", oracleFloatBits(item.hoverStart));
                    row.addProperty("pickup_delay",
                        itemField(item, "delayBeforeCanPickup"));
                    items.add(row);
                }
                out.add("items", items);
                out.add("world_events", events.toJson());
                out.addProperty("math_seed48", mathRandomSeed48());
                return out.toString();
            } catch (Throwable t) {
                return err("ender_eye_tick_locked: " + t);
            } finally {
                if (world != null && events != null) try {
                    world.removeEventListener(events);
                } catch (Throwable ignored) { }
                if (world != null && waterPos != null
                        && oldWaterState != null) try {
                    world.setBlockState(waterPos, oldWaterState, 2);
                } catch (Throwable ignored) { }
                if (world != null)
                    for (net.minecraft.entity.item.EntityItem item : spawned)
                        try {
                            world.removeEntityDangerously(item);
                        } catch (Throwable ignored) { }
                try {
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** DamageSource.FLY_INTO_WALL routing after the separately verified
     * elytra collision calculation. */
    private String oracleElytraWallDamageLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "elytra_wall_damage_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            java.lang.reflect.Field lastDamageField = null;
            int oldHurtTime = 0, oldHurtResistant = 0;
            float oldLastDamage = 0.0F;
            boolean oldCreative = false;
            net.minecraft.world.GameType oldGameType = null;
            try {
                float amount = action.get("amount").getAsFloat();
                float health = action.get("health").getAsFloat();
                float absorption = action.get("absorption").getAsFloat();
                int hurtResistant =
                    action.get("hurt_resistant_time").getAsInt();
                float lastDamage = action.get("last_damage").getAsFloat();
                int resistance = action.get("resistance").getAsInt();
                JsonArray protection = action.getAsJsonArray("protection");
                JsonArray damage = action.getAsJsonArray("damage");
                if (!Float.isFinite(amount) || amount <= 0.0F
                        || amount > 1024.0F || !Float.isFinite(health)
                        || health <= 0.0F || health > 20.0F
                        || !Float.isFinite(absorption) || absorption < 0.0F
                        || absorption > 1024.0F
                        || hurtResistant < 0 || hurtResistant > 20
                        || !Float.isFinite(lastDamage) || lastDamage < 0.0F
                        || resistance < -1 || resistance > 4
                        || protection.size() != 4 || damage.size() != 4)
                    return err("invalid Elytra wall-damage fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldHurtTime = player.hurtTime;
                oldHurtResistant = player.hurtResistantTime;
                oldCreative = player.capabilities.isCreativeMode;
                oldGameType = player.interactionManager.getGameType();
                lastDamageField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("lastDamage");
                lastDamageField.setAccessible(true);
                oldLastDamage = lastDamageField.getFloat(player);

                net.minecraft.item.Item[] items = {
                    net.minecraft.init.Items.DIAMOND_BOOTS,
                    net.minecraft.init.Items.DIAMOND_LEGGINGS,
                    net.minecraft.init.Items.ELYTRA,
                    net.minecraft.init.Items.DIAMOND_HELMET
                };
                for (int i = 0; i < 4; ++i) {
                    int level = protection.get(i).getAsInt();
                    int itemDamage = damage.get(i).getAsInt();
                    if (level < 0 || level > 32
                            || itemDamage < 0 || itemDamage > 4096)
                        return err("invalid Elytra wall-damage equipment");
                    net.minecraft.item.ItemStack stack =
                        new net.minecraft.item.ItemStack(
                            items[i], 1, itemDamage);
                    if (level > 0)
                        stack.addEnchantment(
                            net.minecraft.init.Enchantments.PROTECTION,
                            level);
                    player.inventory.armorInventory.set(i, stack);
                }
                player.clearActivePotions();
                player.capabilities.isCreativeMode = false;
                player.interactionManager.setGameType(
                    net.minecraft.world.GameType.SURVIVAL);
                if (resistance >= 0)
                    player.addPotionEffect(new net.minecraft.potion.PotionEffect(
                        net.minecraft.init.MobEffects.RESISTANCE,
                        1000, resistance));
                player.setHealth(health);
                player.setAbsorptionAmount(absorption);
                player.hurtTime = 0;
                player.hurtResistantTime = hurtResistant;
                lastDamageField.setFloat(player, lastDamage);
                boolean accepted = player.attackEntityFrom(
                    net.minecraft.util.DamageSource.FLY_INTO_WALL, amount);

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("accepted", accepted);
                out.addProperty("health_bits",
                    oracleFloatBits(player.getHealth()));
                out.addProperty("absorption_bits",
                    oracleFloatBits(player.getAbsorptionAmount()));
                out.addProperty("hurt_time", player.hurtTime);
                out.addProperty("hurt_resistant_time",
                    player.hurtResistantTime);
                out.addProperty("last_damage_bits",
                    oracleFloatBits(lastDamageField.getFloat(player)));
                JsonArray equipment = new JsonArray();
                for (int i = 0; i < 4; ++i) {
                    net.minecraft.item.ItemStack stack =
                        player.inventory.armorInventory.get(i);
                    JsonArray row = new JsonArray();
                    row.add(new JsonPrimitive(stackId(stack)));
                    row.add(new JsonPrimitive(
                        stack.isEmpty() ? 0 : stack.getCount()));
                    row.add(new JsonPrimitive(oracleStackMeta(stack)));
                    equipment.add(row);
                }
                out.add("equipment", equipment);
                return out.toString();
            } catch (Throwable t) {
                return err("elytra_wall_damage_locked: " + t);
            } finally {
                try {
                    if (player != null && saved != null)
                        player.readFromNBT(saved);
                    if (player != null) {
                        player.capabilities.isCreativeMode = oldCreative;
                        if (oldGameType != null)
                            player.interactionManager.setGameType(oldGameType);
                        player.hurtTime = oldHurtTime;
                        player.hurtResistantTime = oldHurtResistant;
                        if (lastDamageField != null)
                            lastDamageField.setFloat(player, oldLastDamage);
                        oracleCaptureAuthoritativePlayerLocked(player);
                    }
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Exact ItemStack.onBlockDestroyed durability and player RNG boundary. */
    private String oracleBlockHarvestToolLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "block_harvest_tool_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            long oldSeed = -1L;
            try {
                int blockId = action.get("block").getAsInt();
                int toolId = action.get("tool").getAsInt();
                int damage = action.get("damage").getAsInt();
                int unbreaking = action.get("unbreaking").getAsInt();
                long seed = action.get("player_seed48").getAsLong();
                if (blockId <= 0 || blockId > 4095 || toolId <= 0
                        || toolId > 32767 || damage < 0 || damage > 32767
                        || unbreaking < 0 || unbreaking > 32
                        || seed < 0L || seed >= (1L << 48))
                    return err("invalid block tool fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldSeed = javaRandomSeed48(entityRandom(player));
                net.minecraft.block.Block block =
                    net.minecraft.block.Block.getBlockById(blockId);
                net.minecraft.item.Item tool =
                    net.minecraft.item.Item.getItemById(toolId);
                if (block == null || tool == null)
                    return err("unknown block tool fixture");
                net.minecraft.item.ItemStack held =
                    new net.minecraft.item.ItemStack(tool, 1, damage);
                if (unbreaking > 0)
                    held.addEnchantment(
                        net.minecraft.init.Enchantments.UNBREAKING, unbreaking);
                player.inventory.currentItem = 0;
                player.inventory.mainInventory.set(0, held);
                setJavaRandomSeed48(entityRandom(player), seed);
                net.minecraft.block.state.IBlockState state =
                    block.getDefaultState();
                BlockPos pos = new BlockPos(
                    (int)Math.floor(player.posX), 220,
                    (int)Math.floor(player.posZ));
                held.onBlockDestroyed(player.getServerWorld(), state, pos, player);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("item", stackId(held));
                out.addProperty("count", held.isEmpty() ? 0 : held.getCount());
                out.addProperty("damage", oracleStackMeta(held));
                out.addProperty("player_seed48",
                    javaRandomSeed48(entityRandom(player)));
                return out.toString();
            } catch (Throwable t) {
                return err("block_harvest_tool_locked: " + t);
            } finally {
                try {
                    if (player != null && saved != null) {
                        player.readFromNBT(saved);
                        if (oldSeed >= 0L)
                            setJavaRandomSeed48(entityRandom(player), oldSeed);
                        oracleCaptureAuthoritativePlayerLocked(player);
                    }
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Block.getDrops plus the Silk Touch branch against the real 1.11.2
     * block registry and World.rand. The returned list is pre-spawn, matching
     * the boundary before chance/offset and EntityItem construction draws. */
    private String oracleBlockHarvestDropsLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "block_harvest_drops_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            net.minecraft.world.WorldServer world = null;
            long oldSeed = -1L;
            try {
                int blockId = action.has("block")
                    ? action.get("block").getAsInt() : -1;
                int meta = action.has("meta")
                    ? action.get("meta").getAsInt() : 0;
                int toolId = action.has("tool")
                    ? action.get("tool").getAsInt() : 0;
                int silk = action.has("silk")
                    ? action.get("silk").getAsInt() : 0;
                int fortune = action.has("fortune")
                    ? action.get("fortune").getAsInt() : 0;
                long seed = action.has("world_seed48")
                    ? action.get("world_seed48").getAsLong() : 0L;
                if (blockId <= 0 || blockId > 4095 || meta < 0 || meta > 15
                        || toolId < 0 || toolId > 32767
                        || silk < 0 || silk > 32
                        || fortune < 0 || fortune > 32
                        || seed < 0L || seed >= (1L << 48))
                    return err("invalid block harvest fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldSeed = javaRandomSeed48(world.rand);
                net.minecraft.block.Block block =
                    net.minecraft.block.Block.getBlockById(blockId);
                net.minecraft.item.Item tool = toolId == 0 ? null
                    : net.minecraft.item.Item.getItemById(toolId);
                if (block == null || (toolId != 0 && tool == null))
                    return err("unknown harvest block or tool");
                net.minecraft.block.state.IBlockState state =
                    block.getStateFromMeta(meta);
                net.minecraft.item.ItemStack held = tool == null
                    ? net.minecraft.item.ItemStack.EMPTY
                    : new net.minecraft.item.ItemStack(tool);
                if (silk > 0)
                    held.addEnchantment(
                        net.minecraft.init.Enchantments.SILK_TOUCH, silk);
                if (fortune > 0)
                    held.addEnchantment(
                        net.minecraft.init.Enchantments.FORTUNE, fortune);
                player.inventory.currentItem = 0;
                player.inventory.mainInventory.set(0, held);
                setJavaRandomSeed48(world.rand, seed);
                BlockPos pos = new BlockPos(
                    (int)Math.floor(player.posX), 220,
                    (int)Math.floor(player.posZ));
                java.util.List<net.minecraft.item.ItemStack> drops =
                    new java.util.ArrayList<net.minecraft.item.ItemStack>();
                if (player.canHarvestBlock(state)) {
                    if (silk > 0
                            && block.canSilkHarvest(
                                world, pos, state, player)) {
                        java.lang.reflect.Method method = null;
                        Class<?> type = block.getClass();
                        while (type != null && method == null) {
                            try {
                                method = type.getDeclaredMethod(
                                    "getSilkTouchDrop",
                                    net.minecraft.block.state
                                        .IBlockState.class);
                            } catch (NoSuchMethodException ignored) {
                                type = type.getSuperclass();
                            }
                        }
                        if (method == null)
                            return err("no Silk Touch drop method");
                        method.setAccessible(true);
                        net.minecraft.item.ItemStack stack =
                            (net.minecraft.item.ItemStack)method.invoke(
                                block, state);
                        if (!stack.isEmpty()) drops.add(stack);
                    } else {
                        drops.addAll(block.getDrops(
                            world, pos, state, fortune));
                    }
                }
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                JsonArray encodedDrops = new JsonArray();
                for (net.minecraft.item.ItemStack stack : drops) {
                    JsonArray encoded = new JsonArray();
                    encoded.add(new JsonPrimitive(stackId(stack)));
                    encoded.add(new JsonPrimitive(stack.getCount()));
                    encoded.add(new JsonPrimitive(oracleStackMeta(stack)));
                    encodedDrops.add(encoded);
                }
                out.add("drops", encodedDrops);
                out.addProperty("world_seed48", javaRandomSeed48(world.rand));
                return out.toString();
            } catch (Throwable t) {
                return err("block_harvest_drops_locked: " + t);
            } finally {
                try {
                    if (world != null && oldSeed >= 0L)
                        setJavaRandomSeed48(world.rand, oldSeed);
                    if (player != null && saved != null) {
                        player.readFromNBT(saved);
                        oracleCaptureAuthoritativePlayerLocked(player);
                    }
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Aqua Affinity, Depth Strider, Respiration, and Frost Walker against the
     * real 1.11.2 player/world implementations. Each mode is synchronous and
     * restores the parked player, fixture blocks, pending ticks, and RNG. */
    private String oracleEquipmentEnchantmentLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "equipment_enchantment_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.world.WorldServer world = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            java.lang.reflect.Field waterField = null;
            boolean oldWater = false, oldFlying = false, oldCreative = false;
            float oldAiSpeed = 0.0F;
            double oldMovementBase = 0.0D;
            long oldSeed = -1L;
            net.minecraft.world.GameType oldGameType = null;
            java.util.ArrayList<BlockPos> fixturePositions =
                new java.util.ArrayList<BlockPos>();
            java.util.ArrayList<net.minecraft.block.state.IBlockState>
                fixtureStates =
                    new java.util.ArrayList<net.minecraft.block.state.IBlockState>();
            net.minecraft.world.gen.structure.StructureBoundingBox cleanupBox = null;
            try {
                String mode = action.has("mode")
                    ? action.get("mode").getAsString() : "";
                int level = action.has("level")
                    ? action.get("level").getAsInt() : 0;
                boolean onGround = !action.has("on_ground")
                    || action.get("on_ground").getAsBoolean();
                long seed = action.has("player_seed48")
                    ? action.get("player_seed48").getAsLong() : 0L;
                if ((!mode.equals("respiration") && !mode.equals("aqua")
                        && !mode.equals("depth") && !mode.equals("frost")
                        && !mode.equals("binding")
                        && !mode.equals("thorns")
                        && !mode.equals("armor_damage"))
                        || level < 0 || level > 32 || seed < 0L
                        || seed >= (1L << 48))
                    return err("invalid equipment enchantment fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldSeed = javaRandomSeed48(entityRandom(player));
                oldAiSpeed = player.getAIMoveSpeed();
                oldMovementBase = player.getEntityAttribute(
                    net.minecraft.entity.SharedMonsterAttributes.MOVEMENT_SPEED)
                        .getBaseValue();
                oldFlying = player.capabilities.isFlying;
                oldCreative = player.capabilities.isCreativeMode;
                oldGameType = player.interactionManager.getGameType();
                waterField = net.minecraft.entity.Entity.class
                    .getDeclaredField("inWater");
                waterField.setAccessible(true);
                oldWater = waterField.getBoolean(player);

                if (mode.equals("armor_damage")) {
                    if (!action.has("unbreaking")
                            || !action.has("damage")
                            || !action.has("amount"))
                        return err("invalid armor-damage fixture");
                    JsonArray unbreaking =
                        action.getAsJsonArray("unbreaking");
                    JsonArray damage = action.getAsJsonArray("damage");
                    float amount = action.get("amount").getAsFloat();
                    if (unbreaking.size() != 4 || damage.size() != 4
                            || !Float.isFinite(amount) || amount <= 0.0F
                            || amount > 2048.0F)
                        return err("invalid armor-damage fixture values");
                    net.minecraft.item.Item[] items = {
                        net.minecraft.init.Items.DIAMOND_BOOTS,
                        net.minecraft.init.Items.DIAMOND_LEGGINGS,
                        net.minecraft.init.Items.DIAMOND_CHESTPLATE,
                        net.minecraft.init.Items.DIAMOND_HELMET
                    };
                    for (int i = 0; i < 4; ++i) {
                        int unbreakingLevel = unbreaking.get(i).getAsInt();
                        int initialDamage = damage.get(i).getAsInt();
                        if (unbreakingLevel < 0 || unbreakingLevel > 32
                                || initialDamage < 0
                                || initialDamage > 4096)
                            return err("invalid armor-damage stack");
                        net.minecraft.item.ItemStack stack =
                            new net.minecraft.item.ItemStack(
                                items[i], 1, initialDamage);
                        if (unbreakingLevel > 0)
                            stack.addEnchantment(
                                net.minecraft.init.Enchantments.UNBREAKING,
                                unbreakingLevel);
                        player.inventory.armorInventory.set(i, stack);
                    }
                    setJavaRandomSeed48(entityRandom(player), seed);
                    player.inventory.damageArmor(amount);
                    JsonObject out = new JsonObject();
                    out.addProperty("ok", true);
                    out.addProperty("mode", mode);
                    JsonArray stacks = new JsonArray();
                    for (int i = 0; i < 4; ++i) {
                        net.minecraft.item.ItemStack stack =
                            player.inventory.armorInventory.get(i);
                        JsonArray encoded = new JsonArray();
                        encoded.add(new JsonPrimitive(stackId(stack)));
                        encoded.add(new JsonPrimitive(
                            stack.isEmpty() ? 0 : stack.getCount()));
                        encoded.add(new JsonPrimitive(
                            oracleStackMeta(stack)));
                        stacks.add(encoded);
                    }
                    out.add("equipment", stacks);
                    out.addProperty("player_seed48",
                        javaRandomSeed48(entityRandom(player)));
                    return out.toString();
                }

                if (mode.equals("thorns")) {
                    if (!action.has("levels")
                            || !action.has("unbreaking")
                            || !action.has("damage"))
                        return err("invalid Thorns fixture arrays");
                    JsonArray levels = action.getAsJsonArray("levels");
                    JsonArray unbreaking =
                        action.getAsJsonArray("unbreaking");
                    JsonArray damage = action.getAsJsonArray("damage");
                    if (levels.size() != 6 || unbreaking.size() != 4
                            || damage.size() != 4)
                        return err("invalid Thorns fixture array lengths");
                    net.minecraft.item.Item[] items = {
                        net.minecraft.init.Items.DIAMOND_SWORD,
                        net.minecraft.init.Items.SHIELD,
                        net.minecraft.init.Items.DIAMOND_BOOTS,
                        net.minecraft.init.Items.DIAMOND_LEGGINGS,
                        net.minecraft.init.Items.DIAMOND_CHESTPLATE,
                        net.minecraft.init.Items.DIAMOND_HELMET
                    };
                    net.minecraft.item.ItemStack[] equipment =
                        new net.minecraft.item.ItemStack[6];
                    for (int i = 0; i < 6; ++i) {
                        int thornLevel = levels.get(i).getAsInt();
                        int initialDamage = i < 2
                            ? 0 : damage.get(i - 2).getAsInt();
                        int unbreakingLevel = i < 2
                            ? 0 : unbreaking.get(i - 2).getAsInt();
                        if (thornLevel < 0 || thornLevel > 32
                                || initialDamage < 0
                                || initialDamage > 4096
                                || unbreakingLevel < 0
                                || unbreakingLevel > 32)
                            return err("invalid Thorns fixture values");
                        equipment[i] = new net.minecraft.item.ItemStack(
                            items[i], 1, initialDamage);
                        if (thornLevel > 0)
                            equipment[i].addEnchantment(
                                net.minecraft.init.Enchantments.THORNS,
                                thornLevel);
                        if (unbreakingLevel > 0)
                            equipment[i].addEnchantment(
                                net.minecraft.init.Enchantments.UNBREAKING,
                                unbreakingLevel);
                    }
                    player.inventory.currentItem = 0;
                    player.inventory.mainInventory.set(0, equipment[0]);
                    player.inventory.offHandInventory.set(0, equipment[1]);
                    for (int i = 0; i < 4; ++i)
                        player.inventory.armorInventory.set(
                            i, equipment[i + 2]);
                    setJavaRandomSeed48(entityRandom(player), seed);
                    ThornsOracleTarget target =
                        new ThornsOracleTarget(world);
                    net.minecraft.enchantment.EnchantmentHelper
                        .applyThornEnchantments(player, target);

                    JsonObject out = new JsonObject();
                    out.addProperty("ok", true);
                    out.addProperty("mode", mode);
                    JsonArray retaliation = new JsonArray();
                    for (Float amount : target.damage)
                        retaliation.add(new JsonPrimitive(
                            (int)amount.floatValue()));
                    out.add("retaliation", retaliation);
                    JsonArray stacks = new JsonArray();
                    for (int i = 0; i < 6; ++i) {
                        net.minecraft.item.ItemStack stack = i == 0
                            ? player.inventory.mainInventory.get(0)
                            : i == 1
                            ? player.inventory.offHandInventory.get(0)
                            : player.inventory.armorInventory.get(i - 2);
                        JsonArray encoded = new JsonArray();
                        encoded.add(new JsonPrimitive(stackId(stack)));
                        encoded.add(new JsonPrimitive(
                            stack.isEmpty() ? 0 : stack.getCount()));
                        encoded.add(new JsonPrimitive(
                            oracleStackMeta(stack)));
                        stacks.add(encoded);
                    }
                    out.add("equipment", stacks);
                    out.addProperty("player_seed48",
                        javaRandomSeed48(entityRandom(player)));
                    return out.toString();
                }

                if (mode.equals("binding")) {
                    boolean creative = action.has("creative")
                        && action.get("creative").getAsBoolean();
                    net.minecraft.item.ItemStack boots =
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.DIAMOND_BOOTS);
                    if (level > 0) boots.addEnchantment(
                        net.minecraft.init.Enchantments.BINDING_CURSE, level);
                    player.inventory.armorInventory.set(0, boots);
                    player.interactionManager.setGameType(
                        creative ? net.minecraft.world.GameType.CREATIVE
                                 : net.minecraft.world.GameType.SURVIVAL);
                    net.minecraft.inventory.ContainerPlayer container =
                        new net.minecraft.inventory.ContainerPlayer(
                            player.inventory, false, player);
                    JsonObject out = new JsonObject();
                    out.addProperty("ok", true);
                    out.addProperty("mode", mode);
                    /* ContainerPlayer slot 8 is feet (5 head, 6 chest,
                     * 7 legs, 8 feet). */
                    out.addProperty(
                        "can_take", container.getSlot(8).canTakeStack(player));
                    return out.toString();
                }

                if (mode.equals("respiration")) {
                    int air = action.has("air")
                        ? action.get("air").getAsInt() : 300;
                    if (air < -20 || air > 300)
                        return err("invalid Respiration air");
                    net.minecraft.item.ItemStack helmet =
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.DIAMOND_HELMET);
                    if (level > 0) helmet.addEnchantment(
                        net.minecraft.init.Enchantments.RESPIRATION, level);
                    player.inventory.armorInventory.set(3, helmet);
                    setJavaRandomSeed48(entityRandom(player), seed);
                    java.lang.reflect.Method decrease =
                        net.minecraft.entity.EntityLivingBase.class
                            .getDeclaredMethod("decreaseAirSupply", int.class);
                    decrease.setAccessible(true);
                    int result = ((Integer)decrease.invoke(
                        player, Integer.valueOf(air))).intValue();
                    JsonObject out = new JsonObject();
                    out.addProperty("ok", true);
                    out.addProperty("mode", mode);
                    out.addProperty("air", result);
                    out.addProperty("player_seed48",
                        javaRandomSeed48(entityRandom(player)));
                    return out.toString();
                }

                int centerX = (int)Math.floor(player.posX);
                int centerZ = (int)Math.floor(player.posZ);
                int baseY = 220;
                int radius = mode.equals("frost")
                    ? Math.min(16, 2 + level) : 5;
                cleanupBox = new net.minecraft.world.gen.structure
                    .StructureBoundingBox(
                        centerX - radius - 1, baseY - 2,
                        centerZ - radius - 1,
                        centerX + radius + 1, baseY + 4,
                        centerZ + radius + 1);
                java.util.List<net.minecraft.world.NextTickListEntry> priorTicks =
                    world.getPendingBlockUpdates(cleanupBox, false);
                if (priorTicks != null && !priorTicks.isEmpty())
                    return err("equipment fixture area has pending ticks");

                int minY = mode.equals("frost") ? baseY : baseY - 1;
                int maxY = mode.equals("frost") ? baseY + 1 : baseY + 2;
                for (int z = centerZ - radius; z <= centerZ + radius; ++z)
                    for (int y = minY; y <= maxY; ++y)
                        for (int x = centerX - radius;
                                x <= centerX + radius; ++x) {
                            BlockPos pos = new BlockPos(x, y, z);
                            fixturePositions.add(pos);
                            fixtureStates.add(world.getBlockState(pos));
                            boolean water = mode.equals("frost")
                                ? y == baseY : true;
                            world.setBlockState(pos,
                                water
                                    ? net.minecraft.init.Blocks.WATER
                                        .getDefaultState()
                                    : net.minecraft.init.Blocks.AIR
                                        .getDefaultState(),
                                2);
                        }
                /* Water placement schedules its own updates. They are setup
                 * artifacts, not consequences of the enchantment boundary. */
                world.getPendingBlockUpdates(cleanupBox, true);

                if (mode.equals("frost")) {
                    player.setPosition(
                        centerX + 0.5D, baseY + 1.0D, centerZ + 0.5D);
                    player.motionX = player.motionY = player.motionZ = 0.0D;
                    player.onGround = onGround;
                    setJavaRandomSeed48(entityRandom(player), seed);
                    net.minecraft.enchantment.EnchantmentFrostWalker
                        .freezeNearby(
                            player, world, new BlockPos(player), level);
                    JsonArray changed = new JsonArray();
                    for (int z = centerZ - radius;
                            z <= centerZ + radius; ++z)
                        for (int x = centerX - radius;
                                x <= centerX + radius; ++x)
                            if (world.getBlockState(
                                    new BlockPos(x, baseY, z)).getBlock()
                                    == net.minecraft.init.Blocks.FROSTED_ICE) {
                                JsonArray row = new JsonArray();
                                row.add(new JsonPrimitive(x - centerX));
                                row.add(new JsonPrimitive(-1));
                                row.add(new JsonPrimitive(z - centerZ));
                                changed.add(row);
                            }
                    JsonObject out = new JsonObject();
                    out.addProperty("ok", true);
                    out.addProperty("mode", mode);
                    out.add("changed", changed);
                    out.add("scheduled", pendingEntriesRelative(
                        world, cleanupBox,
                        centerX, baseY + 1, centerZ));
                    out.addProperty("player_seed48",
                        javaRandomSeed48(entityRandom(player)));
                    return out.toString();
                }

                player.setPosition(
                    centerX + 0.5D, baseY, centerZ + 0.5D);
                player.motionX = player.motionY = player.motionZ = 0.0D;
                player.onGround = onGround;
                player.capabilities.isFlying = false;
                if (mode.equals("aqua")) {
                    player.inventory.mainInventory.set(
                        player.inventory.currentItem,
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.IRON_PICKAXE));
                    net.minecraft.item.ItemStack helmet =
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.DIAMOND_HELMET);
                    if (level > 0) helmet.addEnchantment(
                        net.minecraft.init.Enchantments.AQUA_AFFINITY, level);
                    player.inventory.armorInventory.set(3, helmet);
                    float speed = player.getDigSpeed(
                        net.minecraft.init.Blocks.STONE.getDefaultState(),
                        new BlockPos(centerX, baseY, centerZ));
                    JsonObject out = new JsonObject();
                    out.addProperty("ok", true);
                    out.addProperty("mode", mode);
                    out.addProperty("speed_bits", oracleFloatBits(speed));
                    return out.toString();
                }

                float forward = action.has("forward")
                    ? action.get("forward").getAsFloat() : 1.0F;
                float strafe = action.has("strafe")
                    ? action.get("strafe").getAsFloat() : 0.0F;
                float yaw = action.has("yaw")
                    ? action.get("yaw").getAsFloat() : 0.0F;
                float aiSpeed = action.has("ai_speed")
                    ? action.get("ai_speed").getAsFloat() : 0.1F;
                if (!Float.isFinite(forward) || !Float.isFinite(strafe)
                        || !Float.isFinite(yaw) || !Float.isFinite(aiSpeed)
                        || Math.abs(forward) > 1.0F
                        || Math.abs(strafe) > 1.0F || aiSpeed < 0.0F
                        || aiSpeed > 16.0F)
                    return err("invalid Depth Strider movement");
                net.minecraft.item.ItemStack boots =
                    new net.minecraft.item.ItemStack(
                        net.minecraft.init.Items.DIAMOND_BOOTS);
                if (level > 0) boots.addEnchantment(
                    net.minecraft.init.Enchantments.DEPTH_STRIDER, level);
                player.inventory.armorInventory.set(0, boots);
                player.rotationYaw = yaw;
                player.getEntityAttribute(
                    net.minecraft.entity.SharedMonsterAttributes.MOVEMENT_SPEED)
                        .setBaseValue((double)aiSpeed);
                player.handleWaterMovement();
                player.motionX = player.motionY = player.motionZ = 0.0D;
                /* onLivingUpdate scales movement fields before travel(); the
                 * native shared kernel accepts the pre-scale input. */
                player.moveEntityWithHeading(strafe * 0.98F, forward * 0.98F);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("mode", mode);
                out.addProperty("x_bits", oracleDoubleBits(
                    player.posX - (centerX + 0.5D)));
                out.addProperty("y_bits", oracleDoubleBits(
                    player.posY - (double)baseY));
                out.addProperty("z_bits", oracleDoubleBits(
                    player.posZ - (centerZ + 0.5D)));
                out.addProperty("vx_bits", oracleDoubleBits(player.motionX));
                out.addProperty("vy_bits", oracleDoubleBits(player.motionY));
                out.addProperty("vz_bits", oracleDoubleBits(player.motionZ));
                out.addProperty("on_ground", player.onGround);
                return out.toString();
            } catch (Throwable t) {
                return err("equipment_enchantment_locked: " + t);
            } finally {
                try {
                    if (world != null && cleanupBox != null)
                        world.getPendingBlockUpdates(cleanupBox, true);
                    if (world != null)
                        for (int i = 0; i < fixturePositions.size(); ++i)
                            world.setBlockState(
                                fixturePositions.get(i), fixtureStates.get(i), 2);
                    if (player != null && saved != null) {
                        player.readFromNBT(saved);
                        player.setAIMoveSpeed(oldAiSpeed);
                        player.getEntityAttribute(
                            net.minecraft.entity.SharedMonsterAttributes
                                .MOVEMENT_SPEED).setBaseValue(oldMovementBase);
                        player.capabilities.isFlying = oldFlying;
                        player.capabilities.isCreativeMode = oldCreative;
                        if (oldGameType != null)
                            player.interactionManager.setGameType(oldGameType);
                        if (waterField != null)
                            waterField.setBoolean(player, oldWater);
                        if (oldSeed >= 0L)
                            setJavaRandomSeed48(entityRandom(player), oldSeed);
                        oracleCaptureAuthoritativePlayerLocked(player);
                    }
                } catch (Throwable ignored) { }
            }
        }
    }

    private JsonObject oracleDeathStack(
            net.minecraft.item.ItemStack stack) {
        JsonObject value = new JsonObject();
        value.addProperty("item", stackId(stack));
        value.addProperty("count", stack.getCount());
        value.addProperty("meta", oracleStackMeta(stack));
        value.addProperty("repair_cost", stack.getRepairCost());
        JsonArray enchantments = new JsonArray();
        net.minecraft.nbt.NBTTagList tags = stack.getItem()
                == net.minecraft.init.Items.ENCHANTED_BOOK
            ? net.minecraft.init.Items.ENCHANTED_BOOK.getEnchantments(stack)
            : stack.getEnchantmentTagList();
        if (tags != null) {
            for (int i = 0; i < tags.tagCount(); ++i) {
                net.minecraft.nbt.NBTTagCompound tag =
                    tags.getCompoundTagAt(i);
                JsonArray enchantment = new JsonArray();
                enchantment.add(new JsonPrimitive(tag.getShort("id")));
                enchantment.add(new JsonPrimitive(tag.getShort("lvl")));
                enchantments.add(enchantment);
            }
        }
        value.add("enchants", enchantments);
        return value;
    }

    /** EntityPlayerMP.onDeath's destroyVanishingCursedItems followed by
     * InventoryPlayer.dropAllItems. The direct boundary avoids changing the
     * parked player's combat/death state while retaining exact constructor,
     * slot-order, entity-id, and RNG observations. */
    private String oraclePlayerDeathInventoryLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "player_death_inventory_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            long oldPlayerSeed = -1L, oldMathSeed = -1L;
            int oldNextId = -1;
            boolean oldCapture = false;
            java.util.ArrayList<net.minecraft.entity.item.EntityItem>
                oldCaptured = null;
            try {
                long playerSeed = action.get("player_seed48").getAsLong();
                long mathSeed = action.get("math_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                boolean keep = action.has("keep_inventory")
                    && action.get("keep_inventory").getAsBoolean();
                if (playerSeed < 0L || playerSeed >= (1L << 48)
                        || mathSeed < 0L || mathSeed >= (1L << 48)
                        || nextId <= 0 || !action.has("stacks"))
                    return err("invalid player death inventory fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                saved = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldPlayerSeed = javaRandomSeed48(entityRandom(player));
                oldMathSeed = mathRandomSeed48();
                oldNextId = nextEntityId();
                oldCapture = player.captureDrops;
                oldCaptured = new java.util.ArrayList<
                    net.minecraft.entity.item.EntityItem>(player.capturedDrops);

                for (int i = 0; i < 36; ++i)
                    player.inventory.mainInventory.set(
                        i, net.minecraft.item.ItemStack.EMPTY);
                for (int i = 0; i < 4; ++i)
                    player.inventory.armorInventory.set(
                        i, net.minecraft.item.ItemStack.EMPTY);
                player.inventory.offHandInventory.set(
                    0, net.minecraft.item.ItemStack.EMPTY);
                for (com.google.gson.JsonElement element
                        : action.getAsJsonArray("stacks")) {
                    JsonObject encoded = element.getAsJsonObject();
                    int slot = encoded.get("slot").getAsInt();
                    net.minecraft.item.ItemStack stack =
                        AnvilOracle.stack(encoded);
                    if (slot >= 0 && slot < 36)
                        player.inventory.mainInventory.set(slot, stack);
                    else if (slot >= 36 && slot < 40)
                        player.inventory.armorInventory.set(slot - 36, stack);
                    else if (slot == 40)
                        player.inventory.offHandInventory.set(0, stack);
                    else return err("invalid player death inventory slot");
                }
                player.setLocationAndAngles(
                    8.5D, 220.0D, 8.5D, 23.0F, -17.0F);
                setJavaRandomSeed48(entityRandom(player), playerSeed);
                setMathRandomSeed48(mathSeed);
                setNextEntityId(nextId);
                player.captureDrops = true;
                player.capturedDrops.clear();
                if (!keep) {
                    java.lang.reflect.Method destroy =
                        net.minecraft.entity.player.EntityPlayer.class
                            .getDeclaredMethod("destroyVanishingCursedItems");
                    destroy.setAccessible(true);
                    destroy.invoke(player);
                    player.inventory.dropAllItems();
                }

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                JsonArray drops = new JsonArray();
                for (net.minecraft.entity.item.EntityItem item
                        : player.capturedDrops) {
                    JsonObject value = oracleDeathStack(item.getEntityItem());
                    value.addProperty("eid", item.getEntityId());
                    value.add("position_bits", oracleEntityDoubleBits(
                        item.posX, item.posY, item.posZ));
                    value.add("motion_bits", oracleEntityDoubleBits(
                        item.motionX, item.motionY, item.motionZ));
                    value.addProperty(
                        "yaw_bits", oracleFloatBits(item.rotationYaw));
                    value.addProperty(
                        "hover_start_bits", oracleFloatBits(item.hoverStart));
                    value.addProperty("age", item.getAge());
                    value.addProperty("pickup_delay",
                        itemField(item, "delayBeforeCanPickup"));
                    drops.add(value);
                }
                out.add("drops", drops);
                JsonArray inventory = new JsonArray();
                for (int slot = 0; slot <= 40; ++slot) {
                    net.minecraft.item.ItemStack stack = slot < 36
                        ? player.inventory.mainInventory.get(slot)
                        : slot < 40
                            ? player.inventory.armorInventory.get(slot - 36)
                            : player.inventory.offHandInventory.get(0);
                    if (stack.isEmpty()) continue;
                    JsonObject value = oracleDeathStack(stack);
                    value.addProperty("slot", slot);
                    inventory.add(value);
                }
                out.add("inventory", inventory);
                out.addProperty("player_seed48",
                    javaRandomSeed48(entityRandom(player)));
                out.addProperty("math_seed48", mathRandomSeed48());
                out.addProperty("next_entity_id", nextEntityId());
                return out.toString();
            } catch (Throwable t) {
                return err("player_death_inventory_locked: " + t);
            } finally {
                if (player != null) try {
                    player.captureDrops = oldCapture;
                    player.capturedDrops.clear();
                    if (oldCaptured != null)
                        player.capturedDrops.addAll(oldCaptured);
                    if (saved != null) player.readFromNBT(saved);
                    if (oldPlayerSeed >= 0L)
                        setJavaRandomSeed48(
                            entityRandom(player), oldPlayerSeed);
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (oldNextId > 0) setNextEntityId(oldNextId);
                    oracleCaptureAuthoritativePlayerLocked(player);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Exact terminal XP, child split, and parent RNG for Slime/Magma Cube. */
    private String oracleSlimeTerminalLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("slime_terminal_locked requires a parked oracle server");
            long oldMathSeed = -1L;
            int oldNextEntityId = -1;
            String oldDoMobLoot = null;
            net.minecraft.world.WorldServer world = null;
            try {
                String type = action.get("type").getAsString();
                int size = action.get("size").getAsInt();
                long entitySeed = action.get("entity_seed48").getAsLong();
                long mathSeed = action.get("math_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                boolean doMobLoot = action.get("do_mob_loot").getAsBoolean();
                if ((!type.equals("slime") && !type.equals("magma_cube"))
                        || (size != 1 && size != 2 && size != 4)
                        || entitySeed < 0L || entitySeed >= (1L << 48)
                        || mathSeed < 0L || mathSeed >= (1L << 48)
                        || nextId <= 0 || nextId > Integer.MAX_VALUE - 8)
                    return err("invalid Slime terminal fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player =
                    server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                oldMathSeed = mathRandomSeed48();
                oldNextEntityId = nextEntityId();
                oldDoMobLoot = world.getGameRules().getString("doMobLoot");
                int bx = net.minecraft.util.math.MathHelper.floor(player.posX);
                int bz = net.minecraft.util.math.MathHelper.floor(player.posZ);
                net.minecraft.entity.monster.EntitySlime slime;
                if (type.equals("magma_cube")) {
                    OracleTerminalMagma magma =
                        new OracleTerminalMagma(world);
                    magma.configure(size, player);
                    slime = magma;
                } else {
                    OracleTerminalSlime ordinary =
                        new OracleTerminalSlime(world);
                    ordinary.configure(size, player);
                    slime = ordinary;
                }
                slime.setLocationAndAngles(
                    bx + 40.5D, 220.0D, bz + 0.5D, 0.0F, 0.0F);
                setJavaRandomSeed48(entityRandom(slime), entitySeed);
                setJavaRandomGaussianState(
                    entityRandom(slime), false, 0.0D);
                setMathRandomSeed48(mathSeed);
                setNextEntityId(nextId);
                world.getGameRules().setOrCreateGameRule(
                    "doMobLoot", doMobLoot ? "true" : "false");

                TerminalXpCapture xp = new TerminalXpCapture(world, slime);
                SlimeSplitCapture split =
                    new SlimeSplitCapture(world, slime);
                oracleTerminalXpCapture.set(xp);
                oracleSlimeSplitCapture.set(split);
                try {
                    if (slime instanceof OracleTerminalMagma)
                        ((OracleTerminalMagma)slime).terminal();
                    else
                        ((OracleTerminalSlime)slime).terminal();
                } finally {
                    oracleSlimeSplitCapture.remove();
                    oracleTerminalXpCapture.remove();
                }

                JsonArray orbs = new JsonArray();
                for (net.minecraft.entity.item.EntityXPOrb orb : xp.orbs) {
                    JsonObject row = new JsonObject();
                    row.addProperty("eid", orb.getEntityId());
                    row.addProperty("value", orb.xpValue);
                    row.add("position_bits", oracleEntityDoubleBits(
                        orb.posX - slime.posX,
                        orb.posY - slime.posY,
                        orb.posZ - slime.posZ));
                    row.add("motion_bits", oracleEntityDoubleBits(
                        orb.motionX, orb.motionY, orb.motionZ));
                    row.addProperty("yaw_bits",
                        oracleFloatBits(orb.rotationYaw));
                    row.addProperty("age", orb.xpOrbAge);
                    row.addProperty("pickup_delay",
                        orb.delayBeforeCanPickup);
                    row.addProperty("health",
                        xpOrbField(orb, "xpOrbHealth"));
                    row.addProperty("color", orb.xpColor);
                    java.lang.reflect.Field target =
                        net.minecraft.entity.item.EntityXPOrb.class
                            .getDeclaredField("xpTargetColor");
                    target.setAccessible(true);
                    row.addProperty("target_color", target.getInt(orb));
                    orbs.add(row);
                }
                JsonArray children = new JsonArray();
                for (net.minecraft.entity.monster.EntitySlime child :
                        split.children) {
                    JsonObject row = new JsonObject();
                    row.addProperty("eid", child.getEntityId());
                    row.addProperty("size", child.getSlimeSize());
                    row.addProperty("health_bits",
                        oracleFloatBits(child.getHealth()));
                    row.add("position_bits", oracleEntityDoubleBits(
                        child.posX - slime.posX,
                        child.posY - slime.posY,
                        child.posZ - slime.posZ));
                    row.add("motion_bits", oracleEntityDoubleBits(
                        child.motionX, child.motionY, child.motionZ));
                    JsonArray rotation = new JsonArray();
                    rotation.add(new JsonPrimitive(
                        oracleFloatBits(child.rotationYaw)));
                    rotation.add(new JsonPrimitive(
                        oracleFloatBits(child.rotationPitch)));
                    row.add("rotation_bits", rotation);
                    JsonArray dimensions = new JsonArray();
                    dimensions.add(new JsonPrimitive(
                        oracleFloatBits(child.width)));
                    dimensions.add(new JsonPrimitive(
                        oracleFloatBits(child.height)));
                    row.add("size_bits", dimensions);
                    row.addProperty("is_dead", child.isDead);
                    children.add(row);
                }
                java.util.Random random = entityRandom(slime);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("type", type);
                out.addProperty("size", size);
                out.addProperty("do_mob_loot", doMobLoot);
                out.add("orbs", orbs);
                out.add("children", children);
                out.addProperty("death_time", slime.deathTime);
                out.addProperty("entity_dead", slime.isDead);
                out.addProperty("entity_seed48", javaRandomSeed48(random));
                out.addProperty("entity_have_gaussian",
                    javaRandomHaveNextGaussian(random));
                out.addProperty("entity_next_gaussian_bits",
                    oracleDoubleBits(javaRandomNextGaussian(random)));
                out.addProperty("math_seed48", doMobLoot
                    ? xp.mathSeed48 : mathSeed);
                out.addProperty("next_entity_id", nextEntityId());
                return out.toString();
            } catch (Throwable t) {
                return err("slime_terminal_locked: " + t);
            } finally {
                oracleSlimeSplitCapture.remove();
                oracleTerminalXpCapture.remove();
                try {
                    if (world != null && oldDoMobLoot != null)
                        world.getGameRules().setOrCreateGameRule(
                            "doMobLoot", oldDoMobLoot);
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Exact WorldServer.spawnParticle descriptor before float packet packing. */
    public static void oracleCapturePlayerAttackParticle(
            net.minecraft.world.WorldServer world,
            net.minecraft.util.EnumParticleTypes type, boolean longDistance,
            double x, double y, double z, int count,
            double xOffset, double yOffset, double zOffset, double speed,
            int[] parameters) {
        AttackParticleProbe probe = oracleAttackParticleProbe.get();
        if (probe == null || probe.world != world || type == null) return;
        AttackParticleRow row = new AttackParticleRow();
        row.id = type.getParticleID();
        row.count = count;
        row.longDistance = longDistance;
        row.x = x;
        row.y = y;
        row.z = z;
        row.xOffset = xOffset;
        row.yOffset = yOffset;
        row.zOffset = zOffset;
        row.speed = speed;
        row.parameters = parameters == null
            ? new int[0] : parameters.clone();
        probe.rows.add(row);
    }

    /** Exact EntityPlayerMP critical/enchantment animation emitter seam. */
    public static void oracleCapturePlayerAttackEmitter(
            net.minecraft.entity.player.EntityPlayerMP player,
            net.minecraft.entity.Entity target, int particleId) {
        AttackParticleProbe probe = oracleAttackParticleProbe.get();
        if (probe == null || probe.player != player || target == null) return;
        AttackParticleRow row = new AttackParticleRow();
        row.id = particleId;
        row.count = -1;
        row.entityId = target.getEntityId();
        row.x = target.posX;
        row.y = target.getEntityBoundingBox().minY;
        row.z = target.posZ;
        row.entityWidth = target.width;
        row.entityHeight = target.height;
        probe.rows.add(row);
    }

    /* Direct EntityPlayer.attackTargetEntityWithCurrentItem fixture for the
     * critical-hit predicate, sweep branch, sound order, and damage ordering. */
    private String oraclePlayerCriticalLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("player_critical_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            net.minecraft.entity.Entity oldRide = null;
            java.lang.reflect.Field swingField = null;
            java.lang.reflect.Field waterField = null;
            net.minecraft.item.ItemStack fixtureHeld = null;
            net.minecraft.item.ItemStack oldHeld = null;
            net.minecraft.entity.passive.EntityPig sweepNeighbor = null;
            AttackSoundProbe soundProbe = null;
            AttackParticleProbe particleProbe = null;
            net.minecraft.world.WorldServer world = null;
            OracleLivingDropsCapture deathDropCapture = null;
            long oldMathSeed = -1L;
            int oldNextEntityId = -1;
            String oldDoMobLoot = null;
            int oldSwing = 0;
            boolean oldWater = false;
            float oldDistanceWalked = 0.0F;
            float oldPrevDistanceWalked = 0.0F;
            try {
                int swingTicks = action.has("cooldown_ticks")
                    ? action.get("cooldown_ticks").getAsInt() : 5;
                float fall = action.has("fall_distance")
                    ? action.get("fall_distance").getAsFloat() : 1.0F;
                boolean onGround = action.has("on_ground")
                    && action.get("on_ground").getAsBoolean();
                boolean sprinting = action.has("sprinting")
                    && action.get("sprinting").getAsBoolean();
                boolean blindness = action.has("blindness")
                    && action.get("blindness").getAsBoolean();
                boolean riding = action.has("riding")
                    && action.get("riding").getAsBoolean();
                boolean inWater = action.has("in_water")
                    && action.get("in_water").getAsBoolean();
                boolean targetOnGround = action.has("target_on_ground")
                    && action.get("target_on_ground").getAsBoolean();
                boolean sweepNeighborEnabled = action.has("sweep_neighbor")
                    && action.get("sweep_neighbor").getAsBoolean();
                float distanceWalkedDelta = action.has("distance_walked_delta")
                    ? action.get("distance_walked_delta").getAsFloat() : 0.0F;
                double targetMotionX = action.has("target_motion_x")
                    ? action.get("target_motion_x").getAsDouble() : 0.0D;
                double targetMotionY = action.has("target_motion_y")
                    ? action.get("target_motion_y").getAsDouble() : 0.0D;
                double targetMotionZ = action.has("target_motion_z")
                    ? action.get("target_motion_z").getAsDouble() : 0.0D;
                double playerMotionX = action.has("player_motion_x")
                    ? action.get("player_motion_x").getAsDouble() : 0.0D;
                double playerMotionZ = action.has("player_motion_z")
                    ? action.get("player_motion_z").getAsDouble() : 0.0D;
                int targetFireTicks = action.has("target_fire_ticks")
                    ? action.get("target_fire_ticks").getAsInt() : 0;
                int targetHurtResistant = action.has("target_hurt_resistant")
                    ? action.get("target_hurt_resistant").getAsInt() : 0;
                float targetLastDamage = action.has("target_last_damage")
                    ? action.get("target_last_damage").getAsFloat() : 0.0F;
                float targetHealth = action.has("target_health")
                    ? action.get("target_health").getAsFloat() : -1.0F;
                int enchantId = action.has("enchant_id")
                    ? action.get("enchant_id").getAsInt() : 0;
                int enchantLevel = action.has("enchant_level")
                    ? action.get("enchant_level").getAsInt() : 0;
                int heldItem = action.has("held_item")
                    ? action.get("held_item").getAsInt() : 0;
                String targetName = action.has("target")
                    ? action.get("target").getAsString() : "pig";
                int targetSize = action.has("target_size")
                    ? action.get("target_size").getAsInt() : 1;
                long targetSeed = action.has("target_seed48")
                    ? action.get("target_seed48").getAsLong() : -1L;
                long neighborSeed = action.has("neighbor_seed48")
                    ? action.get("neighbor_seed48").getAsLong() : -1L;
                boolean captureDeath = action.has("capture_death")
                    && action.get("capture_death").getAsBoolean();
                long deathMathSeed = action.has("math_seed48")
                    ? action.get("math_seed48").getAsLong() : 0L;
                int deathNextEntityId = action.has("next_entity_id")
                    ? action.get("next_entity_id").getAsInt() : 1000;
                boolean doMobLoot = !action.has("do_mob_loot")
                    || action.get("do_mob_loot").getAsBoolean();
                if (swingTicks < 0 || swingTicks > 100 || !Float.isFinite(fall)
                        || fall < 0.0F || heldItem < 0 || heldItem > 4095
                        || !Double.isFinite(targetMotionX)
                        || !Double.isFinite(targetMotionY)
                        || !Double.isFinite(targetMotionZ)
                        || !Double.isFinite(playerMotionX)
                        || !Double.isFinite(playerMotionZ)
                        || targetFireTicks < -20 || targetFireTicks > 32767
                        || targetHurtResistant < 0 || targetHurtResistant > 20
                        || !Float.isFinite(targetLastDamage)
                        || targetLastDamage < 0.0F
                        || !Float.isFinite(targetHealth)
                        || !Float.isFinite(distanceWalkedDelta)
                        || distanceWalkedDelta < 0.0F
                        || enchantId < 0 || enchantId > 255
                        || enchantLevel < 0 || enchantLevel > 255
                        || targetSeed < -1L || targetSeed >= (1L << 48)
                        || neighborSeed < -1L || neighborSeed >= (1L << 48)
                        || deathMathSeed < 0L
                        || deathMathSeed >= (1L << 48)
                        || deathNextEntityId <= 0
                        || deathNextEntityId > Integer.MAX_VALUE - 8
                        || (targetSize != 1 && targetSize != 2
                            && targetSize != 4))
                    return err("invalid player critical fixture");
                MinecraftServer server = Minecraft.getMinecraft().getIntegratedServer();
                if (server == null || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                saved = player.writeToNBT(new net.minecraft.nbt.NBTTagCompound());
                oldRide = player.getRidingEntity();
                if (oldRide != null) player.dismountRidingEntity();
                swingField = net.minecraft.entity.EntityLivingBase.class
                    .getDeclaredField("ticksSinceLastSwing");
                swingField.setAccessible(true);
                oldSwing = swingField.getInt(player);
                waterField = net.minecraft.entity.Entity.class
                    .getDeclaredField("inWater");
                waterField.setAccessible(true);
                oldWater = waterField.getBoolean(player);
                oldDistanceWalked = player.distanceWalkedModified;
                oldPrevDistanceWalked = player.prevDistanceWalkedModified;

                net.minecraft.entity.EntityLivingBase target =
                    oraclePlayerAttackTarget(world, targetName);
                if (target == null) return err("invalid player critical target");
                if (target instanceof net.minecraft.entity.monster.EntitySlime) {
                    java.lang.reflect.Method sizeMethod =
                        net.minecraft.entity.monster.EntitySlime.class
                            .getDeclaredMethod(
                                "setSlimeSize", int.class, boolean.class);
                    sizeMethod.setAccessible(true);
                    sizeMethod.invoke(target, targetSize, false);
                } else if (targetSize != 1) {
                    return err("target_size requires slime or magma_cube");
                }
                if (targetSeed >= 0L)
                    setJavaRandomSeed48(entityRandom(target), targetSeed);
                target.setLocationAndAngles(
                    player.posX, 220.0D, player.posZ - 2.0D, 0.0F, 0.0F);
                if (targetHealth < 0.0F) targetHealth = target.getMaxHealth();
                if (targetHealth <= 0.0F || targetHealth > target.getMaxHealth())
                    return err("invalid target health");
                target.setHealth(targetHealth);
                target.motionX = targetMotionX;
                target.motionY = targetMotionY;
                target.motionZ = targetMotionZ;
                target.onGround = targetOnGround;
                java.lang.reflect.Field targetFireField =
                    net.minecraft.entity.Entity.class.getDeclaredField("fire");
                targetFireField.setAccessible(true);
                targetFireField.setInt(target, targetFireTicks);
                target.hurtResistantTime = targetHurtResistant;
                java.lang.reflect.Field targetLastDamageField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("lastDamage");
                targetLastDamageField.setAccessible(true);
                targetLastDamageField.setFloat(target, targetLastDamage);
                player.setPositionAndRotation(
                    player.posX, 220.0D, player.posZ, 180.0F, 0.0F);
                player.motionX = playerMotionX;
                player.motionY = 0.0D;
                player.motionZ = playerMotionZ;
                player.onGround = onGround;
                player.fallDistance = fall;
                player.setSprinting(sprinting);
                waterField.setBoolean(player, inWater);
                player.clearActivePotions();
                if (blindness)
                    player.addPotionEffect(new net.minecraft.potion.PotionEffect(
                        net.minecraft.init.MobEffects.BLINDNESS, 100, 0));
                player.inventory.currentItem = 0;
                oldHeld = player.getHeldItemMainhand().copy();
                net.minecraft.item.Item heldType = heldItem > 0
                    ? net.minecraft.item.Item.getItemById(heldItem)
                    : enchantId > 0 ? net.minecraft.init.Items.STICK : null;
                if ((heldItem > 0 || enchantId > 0) && heldType == null)
                    return err("unknown held attack item");
                net.minecraft.item.ItemStack held = heldType == null
                    ? net.minecraft.item.ItemStack.EMPTY
                    : new net.minecraft.item.ItemStack(heldType);
                if (enchantId > 0 && enchantLevel > 0) {
                    net.minecraft.enchantment.Enchantment enchant =
                        net.minecraft.enchantment.Enchantment.getEnchantmentByID(enchantId);
                    if (enchant == null) return err("unknown attack enchantment");
                    held.addEnchantment(enchant, enchantLevel);
                }
                if (!oldHeld.isEmpty())
                    player.getAttributeMap().removeAttributeModifiers(
                        oldHeld.getAttributeModifiers(
                            net.minecraft.inventory.EntityEquipmentSlot.MAINHAND));
                player.inventory.mainInventory.set(0, held);
                fixtureHeld = held;
                if (!fixtureHeld.isEmpty())
                    player.getAttributeMap().applyAttributeModifiers(
                        fixtureHeld.getAttributeModifiers(
                            net.minecraft.inventory.EntityEquipmentSlot.MAINHAND));
                swingField.setInt(player, swingTicks);
                player.prevDistanceWalkedModified = 10.0F;
                player.distanceWalkedModified = 10.0F + distanceWalkedDelta;
                if (riding && !player.startRiding(target, true))
                    return err("failed to seed riding state");

                if (sweepNeighborEnabled) {
                    sweepNeighbor = new net.minecraft.entity.passive.EntityPig(world);
                    if (neighborSeed >= 0L)
                        setJavaRandomSeed48(
                            entityRandom(sweepNeighbor), neighborSeed);
                    sweepNeighbor.setLocationAndAngles(
                        player.posX + 1.0D, 220.0D, player.posZ - 2.0D,
                        0.0F, 0.0F);
                    sweepNeighbor.setHealth(10.0F);
                    sweepNeighbor.onGround = true;
                    if (!world.spawnEntity(sweepNeighbor))
                        return err("failed to seed sweep neighbor");
                }
                soundProbe = new AttackSoundProbe();
                world.addEventListener(soundProbe);
                particleProbe = new AttackParticleProbe(world, player);
                oracleAttackParticleProbe.set(particleProbe);
                if (captureDeath) {
                    oldMathSeed = mathRandomSeed48();
                    oldNextEntityId = nextEntityId();
                    oldDoMobLoot = world.getGameRules().getString("doMobLoot");
                    setMathRandomSeed48(deathMathSeed);
                    setNextEntityId(deathNextEntityId);
                    world.getGameRules().setOrCreateGameRule(
                        "doMobLoot", doMobLoot ? "true" : "false");
                    deathDropCapture = new OracleLivingDropsCapture(target);
                    MinecraftForge.EVENT_BUS.register(deathDropCapture);
                }

                float before = target.getHealth();
                player.attackTargetEntityWithCurrentItem(target);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("target", targetName);
                out.addProperty("before_bits", oracleFloatBits(before));
                out.addProperty("after_bits", oracleFloatBits(target.getHealth()));
                out.addProperty("after", target.getHealth());
                out.addProperty("cooldown", player.getCooledAttackStrength(0.0F));
                out.addProperty("hurt_time", target.hurtTime);
                out.addProperty("target_fire_ticks",
                    targetFireField.getInt(target));
                out.add("target_motion_bits", oracleEntityDoubleBits(
                    target.motionX, target.motionY, target.motionZ));
                out.add("player_motion_bits", oracleEntityDoubleBits(
                    player.motionX, player.motionY, player.motionZ));
                out.addProperty("player_sprinting", player.isSprinting());
                net.minecraft.item.ItemStack afterHeld =
                    player.inventory.mainInventory.get(0);
                out.addProperty("held_count", afterHeld.isEmpty()
                    ? 0 : afterHeld.getCount());
                out.addProperty("held_damage", afterHeld.isEmpty()
                    ? 0 : afterHeld.getItemDamage());
                out.add("player_position_bits", oracleEntityDoubleBits(
                    player.posX, player.posY, player.posZ));
                out.addProperty("sweep_neighbor_after_bits",
                    sweepNeighbor == null ? ""
                        : oracleFloatBits(sweepNeighbor.getHealth()));
                JsonArray sounds = new JsonArray();
                for (AttackSoundRow row : soundProbe.sounds) {
                    JsonObject sound = new JsonObject();
                    sound.addProperty("sound", row.sound);
                    sound.addProperty("category", row.category);
                    sound.add("position_bits", oracleEntityDoubleBits(
                        row.x, row.y, row.z));
                    sound.addProperty("volume_bits", oracleFloatBits(row.volume));
                    sound.addProperty("pitch_bits", oracleFloatBits(row.pitch));
                    sounds.add(sound);
                }
                out.add("sounds", sounds);
                JsonArray particles = new JsonArray();
                for (AttackParticleRow row : particleProbe.rows) {
                    JsonObject particle = new JsonObject();
                    particle.addProperty("id", row.id);
                    particle.addProperty("count", row.count);
                    particle.addProperty("long_distance", row.longDistance);
                    particle.addProperty("entity_id", row.entityId);
                    particle.add("position_bits", oracleEntityDoubleBits(
                        row.x, row.y, row.z));
                    JsonArray descriptorBits = new JsonArray();
                    descriptorBits.add(new JsonPrimitive(
                        oracleDoubleBits(row.xOffset)));
                    descriptorBits.add(new JsonPrimitive(
                        oracleDoubleBits(row.yOffset)));
                    descriptorBits.add(new JsonPrimitive(
                        oracleDoubleBits(row.zOffset)));
                    descriptorBits.add(new JsonPrimitive(
                        oracleDoubleBits(row.speed)));
                    particle.add("descriptor_bits", descriptorBits);
                    JsonArray sizeBits = new JsonArray();
                    sizeBits.add(new JsonPrimitive(
                        oracleFloatBits(row.entityWidth)));
                    sizeBits.add(new JsonPrimitive(
                        oracleFloatBits(row.entityHeight)));
                    particle.add("entity_size_bits", sizeBits);
                    particles.add(particle);
                }
                out.add("particles", particles);
                if (captureDeath) {
                    if (target.getHealth() <= 0.0F
                            && (deathDropCapture == null
                                || !deathDropCapture.fired))
                        return err("player death fixture missed LivingDropsEvent");
                    JsonArray drops = new JsonArray();
                    for (net.minecraft.entity.item.EntityItem entity :
                            target.capturedDrops) {
                        net.minecraft.item.ItemStack stack =
                            entity.getEntityItem();
                        net.minecraft.nbt.NBTTagCompound nbt =
                            entity.writeToNBT(
                                new net.minecraft.nbt.NBTTagCompound());
                        JsonObject row = new JsonObject();
                        row.addProperty("eid", entity.getEntityId());
                        row.addProperty("item",
                            net.minecraft.item.Item.getIdFromItem(
                                stack.getItem()));
                        row.addProperty("count", stack.getCount());
                        row.addProperty("meta", oracleStackMeta(stack));
                        row.add("position_bits", oracleEntityDoubleBits(
                            entity.posX - target.posX,
                            entity.posY - target.posY,
                            entity.posZ - target.posZ));
                        row.add("motion_bits", oracleEntityDoubleBits(
                            entity.motionX, entity.motionY, entity.motionZ));
                        row.addProperty("yaw_bits",
                            oracleFloatBits(entity.rotationYaw));
                        row.addProperty("hover_bits",
                            oracleFloatBits(entity.hoverStart));
                        row.addProperty("pickup_delay",
                            nbt.getShort("PickupDelay"));
                        row.addProperty("age", nbt.getShort("Age"));
                        drops.add(row);
                    }
                    out.add("drops", drops);
                    out.addProperty("death_time", target.deathTime);
                    out.addProperty("is_dead", target.isDead);
                    out.addProperty("entity_seed48",
                        javaRandomSeed48(entityRandom(target)));
                    out.addProperty("math_seed48",
                        deathDropCapture.mathSeed48);
                    out.addProperty("next_entity_id", nextEntityId());
                    out.addProperty("do_mob_loot", doMobLoot);
                }
                return out.toString();
            } catch (Throwable t) {
                return err("player_critical_locked: " + t);
            } finally {
                if (player != null) try {
                    oracleAttackParticleProbe.remove();
                    if (deathDropCapture != null)
                        MinecraftForge.EVENT_BUS.unregister(deathDropCapture);
                    if (soundProbe != null)
                        player.getServerWorld().removeEventListener(soundProbe);
                    if (sweepNeighbor != null)
                        player.getServerWorld().removeEntityDangerously(sweepNeighbor);
                    if (player.isRiding()) player.dismountRidingEntity();
                    if (fixtureHeld != null && !fixtureHeld.isEmpty())
                        player.getAttributeMap().removeAttributeModifiers(
                            fixtureHeld.getAttributeModifiers(
                                net.minecraft.inventory.EntityEquipmentSlot.MAINHAND));
                    if (saved != null) player.readFromNBT(saved);
                    if (oldHeld != null && !oldHeld.isEmpty())
                        player.getAttributeMap().applyAttributeModifiers(
                            oldHeld.getAttributeModifiers(
                                net.minecraft.inventory.EntityEquipmentSlot.MAINHAND));
                    if (oldRide != null) player.startRiding(oldRide, true);
                    if (swingField != null) swingField.setInt(player, oldSwing);
                    player.distanceWalkedModified = oldDistanceWalked;
                    player.prevDistanceWalkedModified = oldPrevDistanceWalked;
                    if (waterField != null) waterField.setBoolean(player, oldWater);
                    if (world != null && oldDoMobLoot != null)
                        world.getGameRules().setOrCreateGameRule(
                            "doMobLoot", oldDoMobLoot);
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                } catch (Throwable ignored) { }
            }
        }
    }

    /* EntityThrowable thrower suppression, two-tick release, and a returning
     * splash potion's direct player impact. */
    private String oraclePotionPlayerReturnLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("potion_player_return_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.entity.projectile.EntityPotion potion = null;
            net.minecraft.entity.Entity oldRide = null;
            net.minecraft.nbt.NBTTagCompound saved = null;
            java.util.List<net.minecraft.entity.Entity> displaced =
                new java.util.ArrayList<>();
            java.util.List<double[]> displacedPositions =
                new java.util.ArrayList<>();
            java.lang.reflect.Field respawnInvulnerability = null;
            boolean oldDisableDamage = false;
            int oldRespawnInvulnerability = 0;
            try {
                MinecraftServer server = Minecraft.getMinecraft().getIntegratedServer();
                if (server == null || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                net.minecraft.world.WorldServer world = player.getServerWorld();
                saved = player.writeToNBT(new net.minecraft.nbt.NBTTagCompound());
                oldRide = player.getRidingEntity();
                if (oldRide != null) player.dismountRidingEntity();
                respawnInvulnerability =
                    net.minecraft.entity.player.EntityPlayerMP.class
                        .getDeclaredField("respawnInvulnerabilityTicks");
                respawnInvulnerability.setAccessible(true);
                oldRespawnInvulnerability =
                    respawnInvulnerability.getInt(player);
                oldDisableDamage = player.capabilities.disableDamage;
                respawnInvulnerability.setInt(player, 0);
                player.capabilities.disableDamage = false;
                player.motionX = player.motionY = player.motionZ = 0.0D;
                player.setHealth(20.0F);
                player.setAbsorptionAmount(0.0F);
                player.hurtResistantTime = 0;
                player.hurtTime = 0;
                player.deathTime = 0;
                player.clearActivePotions();

                net.minecraft.item.ItemStack stack =
                    net.minecraft.potion.PotionUtils.addPotionToItemStack(
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.SPLASH_POTION),
                        net.minecraft.init.PotionTypes.STRONG_HARMING);
                net.minecraft.potion.PotionUtils.appendEffects(
                    stack,
                    java.util.Arrays.asList(
                        new net.minecraft.potion.PotionEffect(
                            net.minecraft.init.MobEffects.FIRE_RESISTANCE,
                            101, 0, true, false),
                        new net.minecraft.potion.PotionEffect(
                            net.minecraft.init.MobEffects.INSTANT_HEALTH,
                            1, 0, false, true)));
                potion = new net.minecraft.entity.projectile.EntityPotion(
                    world, player, stack);
                double px = player.posX;
                double py = player.posY;
                double pz = player.posZ;
                potion.setPosition(px, py + 0.8D, pz - 1.0D);
                potion.motionX = potion.motionY = 0.0D;
                potion.motionZ = 2.0D;
                net.minecraft.util.math.AxisAlignedBB firstQuery =
                    potion.getEntityBoundingBox()
                        .addCoord(potion.motionX, potion.motionY, potion.motionZ)
                        .expandXyz(1.0D);
                for (net.minecraft.entity.Entity entity :
                        world.getEntitiesWithinAABBExcludingEntity(
                            potion, firstQuery)) {
                    if (entity == player || !entity.canBeCollidedWith())
                        continue;
                    displaced.add(entity);
                    displacedPositions.add(new double[] {
                        entity.posX, entity.posY, entity.posZ
                    });
                    entity.setPosition(entity.posX + 1024.0D,
                        entity.posY, entity.posZ + 1024.0D);
                }

                java.lang.reflect.Field ignoreEntity =
                    net.minecraft.entity.projectile.EntityThrowable.class
                        .getDeclaredField("ignoreEntity");
                java.lang.reflect.Field ignoreTime =
                    net.minecraft.entity.projectile.EntityThrowable.class
                        .getDeclaredField("ignoreTime");
                ignoreEntity.setAccessible(true);
                ignoreTime.setAccessible(true);
                JsonArray ages = new JsonArray();
                JsonArray dead = new JsonArray();
                JsonArray ignored = new JsonArray();
                JsonArray ignoreTimes = new JsonArray();
                JsonArray healthBits = new JsonArray();
                for (int tick = 0; tick < 5; ++tick) {
                    if (tick == 1) {
                        potion.setPosition(px, py + 0.8D, pz + 12.0D);
                        potion.motionX = potion.motionY = potion.motionZ = 0.0D;
                    } else if (tick == 4) {
                        potion.setPosition(px, py + 0.8D, pz - 1.0D);
                        potion.motionX = potion.motionY = 0.0D;
                        potion.motionZ = 2.0D;
                    }
                    ++potion.ticksExisted;
                    potion.onUpdate();
                    ages.add(new JsonPrimitive(potion.ticksExisted));
                    dead.add(new JsonPrimitive(potion.isDead));
                    ignored.add(new JsonPrimitive(
                        ignoreEntity.get(potion) == player));
                    ignoreTimes.add(new JsonPrimitive(
                        ignoreTime.getInt(potion)));
                    healthBits.add(new JsonPrimitive(
                        oracleFloatBits(player.getHealth())));
                }
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.add("ages", ages);
                out.add("dead", dead);
                out.add("ignored", ignored);
                out.add("ignore_times", ignoreTimes);
                out.add("health_bits", healthBits);
                out.addProperty("hurt_time", player.hurtTime);
                out.addProperty("hurt_resistant_time", player.hurtResistantTime);
                out.add("effects", oraclePotionEffects(
                    player.getActivePotionEffects()));
                player.clearActivePotions();
                net.minecraft.item.ItemStack drink =
                    net.minecraft.potion.PotionUtils.addPotionToItemStack(
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.POTIONITEM),
                        net.minecraft.init.PotionTypes.STRONG_SWIFTNESS);
                net.minecraft.potion.PotionUtils.appendEffects(
                    drink, java.util.Arrays.asList(
                        new net.minecraft.potion.PotionEffect(
                            net.minecraft.init.MobEffects.STRENGTH,
                            300, 1, true, false),
                        new net.minecraft.potion.PotionEffect(
                            net.minecraft.init.MobEffects.SATURATION,
                            1, 2, false, true)));
                net.minecraft.item.ItemStack drinkResult =
                    drink.getItem().onItemUseFinish(drink, world, player);
                out.addProperty("drink_item", stackId(drinkResult));
                out.addProperty("drink_count", drinkResult.getCount());
                out.addProperty(
                    "drink_meta", oracleStackMeta(drinkResult));
                out.add("drink_effects", oraclePotionEffects(
                    player.getActivePotionEffects()));
                player.clearActivePotions();
                net.minecraft.nbt.NBTTagCompound foodState =
                    new net.minecraft.nbt.NBTTagCompound();
                foodState.setInteger("foodLevel", 11);
                foodState.setInteger("foodTickTimer", 0);
                foodState.setFloat("foodSaturationLevel", 2.5F);
                foodState.setFloat("foodExhaustionLevel", 0.0F);
                player.getFoodStats().readNBT(foodState);
                net.minecraft.potion.PotionEffect saturation =
                    new net.minecraft.potion.PotionEffect(
                        net.minecraft.init.MobEffects.SATURATION,
                        1, 2, false, true);
                out.addProperty(
                    "saturation_alive", saturation.onUpdate(player));
                player.addPotionEffect(new net.minecraft.potion.PotionEffect(
                    net.minecraft.init.MobEffects.LUCK,
                    2, 1, false, true));
                player.addPotionEffect(new net.minecraft.potion.PotionEffect(
                    net.minecraft.init.MobEffects.UNLUCK,
                    2, 0, false, true));
                out.addProperty(
                    "effect_food", player.getFoodStats().getFoodLevel());
                out.addProperty("effect_saturation_bits",
                    oracleFloatBits(
                        player.getFoodStats().getSaturationLevel()));
                out.addProperty(
                    "effect_luck_bits", oracleFloatBits(player.getLuck()));
                return out.toString();
            } catch (Throwable t) {
                return err("potion_player_return_locked: " + t);
            } finally {
                if (potion != null) potion.setDead();
                for (int i = 0; i < displaced.size(); ++i) {
                    double[] position = displacedPositions.get(i);
                    displaced.get(i).setPosition(
                        position[0], position[1], position[2]);
                }
                if (player != null && saved != null) try {
                    if (player.isRiding()) player.dismountRidingEntity();
                    player.readFromNBT(saved);
                    if (oldRide != null) player.startRiding(oldRide, true);
                    player.capabilities.disableDamage = oldDisableDamage;
                    if (respawnInvulnerability != null)
                        respawnInvulnerability.setInt(
                            player, oldRespawnInvulnerability);
                } catch (Throwable ignored) { }
            }
        }
    }

    /* A real pre-tick save boundary for bounded thrown-potion and
     * area-effect-cloud payloads, followed by one authoritative entity tick.
     * The world lists and process-global entity cursor are restored. */
    private String oraclePotionCapsuleLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("potion_capsule_locked requires a parked oracle server");
            net.minecraft.world.WorldServer world = null;
            net.minecraft.entity.player.EntityPlayerMP player = null;
                net.minecraft.entity.projectile.EntityPotion potion = null;
                net.minecraft.entity.EntityAreaEffectCloud cloud = null;
                net.minecraft.entity.passive.EntityCow cow = null;
            java.util.List<net.minecraft.entity.Entity> savedLoaded = null;
            java.util.List<net.minecraft.potion.PotionEffect>
                savedPlayerEffects = null;
            boolean playerEffectsFixture = false;
            int oldNextEntityId = -1;
            try {
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                if (action.has("player_effects")) {
                    JsonArray requested = action.getAsJsonArray(
                        "player_effects");
                    if (requested.size() > 32)
                        return err("too many player potion effects");
                    savedPlayerEffects = new java.util.ArrayList<
                        net.minecraft.potion.PotionEffect>();
                    for (net.minecraft.potion.PotionEffect effect
                            : player.getActivePotionEffects())
                        savedPlayerEffects.add(
                            new net.minecraft.potion.PotionEffect(effect));
                    player.clearActivePotions();
                    for (com.google.gson.JsonElement element : requested) {
                        JsonObject effect = element.getAsJsonObject();
                        int id = effect.get("id").getAsInt();
                        int amplifier = effect.get("amp").getAsInt();
                        int duration = effect.get("dur").getAsInt();
                        boolean ambient = effect.get("ambient").getAsBoolean();
                        boolean showParticles = effect.get(
                            "show_particles").getAsBoolean();
                        net.minecraft.potion.Potion kind =
                            net.minecraft.potion.Potion.getPotionById(id);
                        if (kind == null || amplifier < 0 || amplifier > 255
                                || duration <= 1)
                            return err("invalid player potion effect");
                        player.addPotionEffect(
                            new net.minecraft.potion.PotionEffect(
                                kind, duration, amplifier,
                                ambient, showParticles));
                    }
                    playerEffectsFixture = true;
                }
                savedLoaded = new java.util.ArrayList<
                    net.minecraft.entity.Entity>(world.loadedEntityList);
                oldNextEntityId = nextEntityId();
                int fixtureNextId = action.has("next_entity_id")
                    ? action.get("next_entity_id").getAsInt() : 680000;
                if (fixtureNextId <= 0 || fixtureNextId >= 2147483645)
                    return err("invalid potion capsule entity cursor");
                setNextEntityId(fixtureNextId);

                net.minecraft.item.ItemStack stack =
                    net.minecraft.potion.PotionUtils.addPotionToItemStack(
                        new net.minecraft.item.ItemStack(
                            net.minecraft.init.Items.SPLASH_POTION),
                        net.minecraft.init.PotionTypes.STRONG_HARMING);
                net.minecraft.potion.PotionUtils.appendEffects(
                    stack,
                    java.util.Arrays.asList(
                        new net.minecraft.potion.PotionEffect(
                            net.minecraft.init.MobEffects.FIRE_RESISTANCE,
                            401, 0, true, false),
                        new net.minecraft.potion.PotionEffect(
                            net.minecraft.init.MobEffects.POISON,
                            433, 1, false, true)));
                stack.getTagCompound().setInteger(
                    "CustomPotionColor", 0x315A7D);
                potion = new net.minecraft.entity.projectile.EntityPotion(
                    world, player, stack);
                potion.setPosition(
                    player.posX + 4.0D, player.posY + 20.0D,
                    player.posZ + 0.5D);
                potion.motionX = 0.25D;
                potion.motionY = 0.5D;
                potion.motionZ = -0.125D;
                potion.ticksExisted = 7;
                java.lang.reflect.Field ignoreEntity =
                    net.minecraft.entity.projectile.EntityThrowable.class
                        .getDeclaredField("ignoreEntity");
                java.lang.reflect.Field ignoreTime =
                    net.minecraft.entity.projectile.EntityThrowable.class
                        .getDeclaredField("ignoreTime");
                ignoreEntity.setAccessible(true);
                ignoreTime.setAccessible(true);
                ignoreEntity.set(potion, player);
                ignoreTime.setInt(potion, 2);

                cloud = new net.minecraft.entity.EntityAreaEffectCloud(world);
                cloud.setPosition(
                    player.posX + 8.0D, player.posY + 20.0D,
                    player.posZ + 0.5D);
                cloud.setPotion(
                    net.minecraft.init.PotionTypes.STRONG_SWIFTNESS);
                cloud.addEffect(new net.minecraft.potion.PotionEffect(
                    net.minecraft.init.MobEffects.INVISIBILITY,
                    377, 0, true, false));
                cloud.addEffect(new net.minecraft.potion.PotionEffect(
                    net.minecraft.init.MobEffects.ABSORPTION,
                    289, 1, false, true));
                cloud.setColor(0x6A2C91);
                cloud.setOwner(player);
                cloud.setRadius(3.0F);
                cloud.setRadiusOnUse(-0.5F);
                cloud.setRadiusPerTick(-0.005F);
                cloud.setDuration(600);
                cloud.setWaitTime(10);
                cloud.setParticle(
                    net.minecraft.util.EnumParticleTypes.BLOCK_CRACK);
                cloud.setParticleParam1(1);
                cloud.setParticleParam2(73);
                java.lang.reflect.Field durationOnUse =
                    net.minecraft.entity.EntityAreaEffectCloud.class
                        .getDeclaredField("durationOnUse");
                durationOnUse.setAccessible(true);
                durationOnUse.setInt(cloud, -37);
                java.lang.reflect.Method setIgnoreRadius =
                    net.minecraft.entity.EntityAreaEffectCloud.class
                        .getDeclaredMethod("setIgnoreRadius", boolean.class);
                setIgnoreRadius.setAccessible(true);
                setIgnoreRadius.invoke(cloud, Boolean.TRUE);
                cloud.motionX = 0.375D;
                cloud.motionY = -0.0625D;
                cloud.motionZ = -0.21875D;
                cloud.rotationYaw = 31.25F;
                cloud.rotationPitch = -12.5F;
                cloud.prevRotationYaw = 29.75F;
                cloud.prevRotationPitch = -11.0F;
                cloud.prevPosX = cloud.posX - 2.0D;
                cloud.prevPosY = cloud.posY - 3.0D;
                cloud.prevPosZ = cloud.posZ - 4.0D;
                cloud.lastTickPosX = cloud.posX - 5.0D;
                cloud.lastTickPosY = cloud.posY - 6.0D;
                cloud.lastTickPosZ = cloud.posZ - 7.0D;
                cloud.fallDistance = 3.25F;
                setEntityFireTicks(cloud, 17);
                cloud.setAir(123);
                cloud.onGround = true;
                cloud.setEntityInvulnerable(true);
                cloud.timeUntilPortal = 7;
                cloud.setSilent(true);
                cloud.setNoGravity(true);
                cloud.setGlowing(true);
                cloud.updateBlocked = action.has("cloud_update_blocked")
                    && action.get("cloud_update_blocked").getAsBoolean();
                setJavaRandomSeed48(
                    entityRandom(cloud), 0x1234ABCD5678L);
                setJavaRandomGaussianState(
                    entityRandom(cloud), true, -0.78125D);
                cloud.ticksExisted = 14;

                cow = new net.minecraft.entity.passive.EntityCow(world);
                cow.setNoAI(true);
                cow.setPosition(
                    cloud.posX + 0.25D, cloud.posY, cloud.posZ + 0.25D);
                cloud.setOwner(cow);
                @SuppressWarnings("unchecked")
                java.util.Map<net.minecraft.entity.Entity, Integer>
                    fixtureDeadlines =
                        (java.util.Map<net.minecraft.entity.Entity, Integer>)
                            oraclePrivateField(
                                cloud,
                                net.minecraft.entity
                                    .EntityAreaEffectCloud.class,
                                "reapplicationDelayMap");
                fixtureDeadlines.put(player, Integer.valueOf(12));
                fixtureDeadlines.put(cow, Integer.valueOf(33));

                world.loadedEntityList.clear();
                world.loadedEntityList.add(potion);
                world.loadedEntityList.add(cloud);
                world.loadedEntityList.add(cow);
                oracleCaptureAuthoritativePlayerLocked(player);
                JsonObject before = oracleAuthoritativeJsonLocked();
                if (before == null)
                    return err("potion capsule before-state capture failed");

                potion.lastTickPosX = potion.posX;
                potion.lastTickPosY = potion.posY;
                potion.lastTickPosZ = potion.posZ;
                potion.prevRotationYaw = potion.rotationYaw;
                potion.prevRotationPitch = potion.rotationPitch;
                ++potion.ticksExisted;
                if (!potion.updateBlocked) potion.onUpdate();
                cloud.lastTickPosX = cloud.posX;
                cloud.lastTickPosY = cloud.posY;
                cloud.lastTickPosZ = cloud.posZ;
                cloud.prevRotationYaw = cloud.rotationYaw;
                cloud.prevRotationPitch = cloud.rotationPitch;
                ++cloud.ticksExisted;
                if (!cloud.updateBlocked) cloud.onUpdate();
                if (playerEffectsFixture) {
                    for (net.minecraft.potion.PotionEffect effect
                            : new java.util.ArrayList<
                                net.minecraft.potion.PotionEffect>(
                                    player.getActivePotionEffects()))
                        effect.onUpdate(player);
                }
                oracleCaptureAuthoritativePlayerLocked(player);
                JsonObject after = oracleAuthoritativeJsonLocked();
                if (after == null)
                    return err("potion capsule after-state capture failed");
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.add("before", before);
                out.add("after", after);
                return out.toString();
            } catch (Throwable t) {
                return err("potion_capsule_locked: " + t);
            } finally {
                if (world != null && savedLoaded != null) try {
                    oracleReplaceList(world.loadedEntityList, savedLoaded);
                } catch (Throwable ignored) { }
                try {
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                } catch (Throwable ignored) { }
                if (player != null && savedPlayerEffects != null) try {
                    player.clearActivePotions();
                    for (net.minecraft.potion.PotionEffect effect
                            : savedPlayerEffects)
                        player.addPotionEffect(effect);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Potion.affectEntity with an EntityAreaEffectCloud immediate source and
     * its nullable living owner as the true indirect-magic source. */
    private String oraclePotionOwnerDamageLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "potion_owner_damage_locked requires a parked oracle server");
            net.minecraft.entity.player.EntityPlayerMP player = null;
            net.minecraft.nbt.NBTTagCompound savedPlayer = null;
            JsonObject oldSeedHelper = null;
            int oldNextEntityId = -1;
            long oldMathSeed = -1L, oldPlayerSeed = -1L;
            boolean oldPlayerHaveGaussian = false;
            double oldPlayerGaussian = 0.0D;
            java.lang.reflect.Field respawnInvulnerabilityField = null;
            int oldRespawnInvulnerability = 0;
            boolean oldDisableDamage = false;
            net.minecraft.scoreboard.ScorePlayerTeam oldPlayerTeam = null;
            boolean oldPlayerTeamFriendlyFire = false;
            try {
                String targetKind = action.get("target").getAsString();
                String ownerKind = action.get("owner").getAsString();
                float health = action.get("health").getAsFloat();
                int hurtResistant =
                    action.get("hurt_resistant_time").getAsInt();
                float lastDamage = action.get("last_damage").getAsFloat();
                boolean onGround = action.get("on_ground").getAsBoolean();
                long targetSeed = action.get("target_seed48").getAsLong();
                long mathSeed = action.get("math_seed48").getAsLong();
                int amplifier = action.has("amplifier")
                    ? action.get("amplifier").getAsInt() : 0;
                double factor = action.has("factor")
                    ? action.get("factor").getAsDouble() : 0.5D;
                float maxHealth = targetKind.equals("pig") ? 10.0F
                    : targetKind.equals("witch") ? 26.0F
                    : targetKind.equals("zombie")
                        || targetKind.equals("player") ? 20.0F : -1.0F;
                if (maxHealth < 0.0F
                        || (!ownerKind.equals("player")
                            && !ownerKind.equals("cow")
                            && !ownerKind.equals("none"))
                        || health <= 0.0F || health > maxHealth
                        || hurtResistant < 0 || hurtResistant > 20
                        || lastDamage < 0.0F || targetSeed < 0L
                        || targetSeed >= (1L << 48) || mathSeed < 0L
                        || mathSeed >= (1L << 48)
                        || amplifier < 0 || amplifier > 8
                        || !Double.isFinite(factor) || factor < 0.0D
                        || factor > 1.0D)
                    return err("invalid potion owner damage fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                player = server.getPlayerList().getPlayers().get(0);
                net.minecraft.world.WorldServer world =
                    player.getServerWorld();
                savedPlayer = player.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                oldSeedHelper = oracleSeedHelperState();
                oldNextEntityId = nextEntityId();
                oldMathSeed = mathRandomSeed48();
                oldPlayerSeed = javaRandomSeed48(entityRandom(player));
                oldPlayerHaveGaussian =
                    javaRandomHaveNextGaussian(entityRandom(player));
                oldPlayerGaussian =
                    javaRandomNextGaussian(entityRandom(player));
                respawnInvulnerabilityField =
                    net.minecraft.entity.player.EntityPlayerMP.class
                        .getDeclaredField("respawnInvulnerabilityTicks");
                respawnInvulnerabilityField.setAccessible(true);
                oldRespawnInvulnerability =
                    respawnInvulnerabilityField.getInt(player);
                oldDisableDamage = player.capabilities.disableDamage;
                respawnInvulnerabilityField.setInt(player, 0);
                player.setEntityInvulnerable(false);
                player.capabilities.disableDamage = false;
                if (player.getTeam()
                        instanceof net.minecraft.scoreboard.ScorePlayerTeam) {
                    oldPlayerTeam = (net.minecraft.scoreboard.ScorePlayerTeam)
                        player.getTeam();
                    oldPlayerTeamFriendlyFire =
                        oldPlayerTeam.getAllowFriendlyFire();
                    oldPlayerTeam.setAllowFriendlyFire(true);
                }

                player.setLocationAndAngles(
                    24.5D, 220.0D, 24.5D, 0.0F, 0.0F);
                player.motionX = player.motionY = player.motionZ = 0.0D;
                player.onGround = true;
                net.minecraft.entity.EntityLivingBase target =
                    targetKind.equals("player") ? player
                    : targetKind.equals("pig")
                        ? new net.minecraft.entity.passive.EntityPig(world)
                    : targetKind.equals("witch")
                        ? new net.minecraft.entity.monster.EntityWitch(world)
                        : new net.minecraft.entity.monster.EntityZombie(world);
                target.setLocationAndAngles(
                    25.5D, 220.0D, 24.5D, 0.0F, 0.0F);
                target.motionX = target.motionY = target.motionZ = 0.0D;
                target.onGround = onGround;
                target.setHealth(health);
                target.setAbsorptionAmount(0.0F);
                target.clearActivePotions();
                if (target == player)
                    player.inventory.clear();
                target.hurtTime = 0;
                target.maxHurtTime = 0;
                target.hurtResistantTime = hurtResistant;
                target.deathTime = 0;
                target.limbSwingAmount = 0.0F;
                target.attackedAtYaw = 0.0F;
                target.velocityChanged = false;
                target.setRevengeTarget(null);
                java.lang.reflect.Field lastDamageField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("lastDamage");
                java.lang.reflect.Field entityAgeField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("entityAge");
                java.lang.reflect.Field recentlyHitField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("recentlyHit");
                java.lang.reflect.Field attackingPlayerField =
                    net.minecraft.entity.EntityLivingBase.class
                        .getDeclaredField("attackingPlayer");
                lastDamageField.setAccessible(true);
                entityAgeField.setAccessible(true);
                recentlyHitField.setAccessible(true);
                attackingPlayerField.setAccessible(true);
                lastDamageField.setFloat(target, lastDamage);
                entityAgeField.setInt(target, 42);
                recentlyHitField.setInt(target, 0);
                attackingPlayerField.set(target, null);
                setJavaRandomSeed48(entityRandom(target), targetSeed);
                setJavaRandomGaussianState(
                    entityRandom(target), false, 0.0D);
                setMathRandomSeed48(mathSeed);

                net.minecraft.entity.EntityLivingBase owner = null;
                if (ownerKind.equals("player")) {
                    owner = player;
                } else if (ownerKind.equals("cow")) {
                    owner = new net.minecraft.entity.passive.EntityCow(world);
                    owner.setLocationAndAngles(
                        24.5D, 220.0D, 24.5D, 0.0F, 0.0F);
                }
                net.minecraft.entity.EntityAreaEffectCloud cloud =
                    new net.minecraft.entity.EntityAreaEffectCloud(world);
                cloud.setLocationAndAngles(
                    25.0D, 220.0D, 24.5D, 0.0F, 0.0F);
                cloud.setOwner(owner);
                /* EntityCow construction may consume Math.random while
                 * selecting attributes. Pin the attack boundary after every
                 * fixture entity exists. */
                setMathRandomSeed48(mathSeed);
                net.minecraft.init.MobEffects.INSTANT_DAMAGE.affectEntity(
                    cloud, cloud.getOwner(), target, amplifier, factor);

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("target_health_bits",
                    oracleFloatBits(target.getHealth()));
                out.add("target_motion_bits", oracleEntityDoubleBits(
                    target.motionX, target.motionY, target.motionZ));
                out.addProperty("target_hurt_time", target.hurtTime);
                out.addProperty("target_max_hurt_time", target.maxHurtTime);
                out.addProperty("target_hurt_resistant_time",
                    target.hurtResistantTime);
                out.addProperty("target_last_damage_bits",
                    oracleFloatBits(lastDamageField.getFloat(target)));
                out.addProperty("target_recently_hit",
                    recentlyHitField.getInt(target));
                out.addProperty("target_attacking_player",
                    attackingPlayerField.get(target) == player);
                out.addProperty("target_revenge_present",
                    target.getAITarget() != null);
                out.addProperty("target_revenge_owner",
                    owner != null && target.getAITarget() == owner);
                out.addProperty("target_entity_age",
                    entityAgeField.getInt(target));
                out.addProperty("target_limb_swing_amount_bits",
                    oracleFloatBits(target.limbSwingAmount));
                out.addProperty("target_attacked_yaw_bits",
                    oracleFloatBits(target.attackedAtYaw));
                out.addProperty("target_velocity_changed",
                    target.velocityChanged);
                if (targetKind.equals("player")) {
                    out.addProperty("target_velocity_packet_present",
                        target.velocityChanged);
                    if (target.velocityChanged) {
                        net.minecraft.network.play.server
                            .SPacketEntityVelocity packet =
                            new net.minecraft.network.play.server
                                .SPacketEntityVelocity(target);
                        out.add("target_velocity_packet_bits",
                            oracleEntityDoubleBits(
                                packet.getMotionX() / 8000.0D,
                                packet.getMotionY() / 8000.0D,
                                packet.getMotionZ() / 8000.0D));
                    }
                }
                out.addProperty("target_seed48",
                    javaRandomSeed48(entityRandom(target)));
                out.addProperty("math_seed48", mathRandomSeed48());
                return out.toString();
            } catch (Throwable t) {
                return err("potion_owner_damage_locked: " + t);
            } finally {
                try {
                    if (player != null && savedPlayer != null)
                        player.readFromNBT(savedPlayer);
                    if (oldSeedHelper != null)
                        oracleRestoreSeedHelperState(oldSeedHelper);
                    if (oldNextEntityId > 0)
                        setNextEntityId(oldNextEntityId);
                    if (oldMathSeed >= 0L)
                        setMathRandomSeed48(oldMathSeed);
                    if (player != null && oldPlayerSeed >= 0L) {
                        setJavaRandomSeed48(
                            entityRandom(player), oldPlayerSeed);
                        setJavaRandomGaussianState(entityRandom(player),
                            oldPlayerHaveGaussian, oldPlayerGaussian);
                    }
                    if (player != null) {
                        player.capabilities.disableDamage = oldDisableDamage;
                        if (respawnInvulnerabilityField != null)
                            respawnInvulnerabilityField.setInt(
                                player, oldRespawnInvulnerability);
                    }
                    if (oldPlayerTeam != null)
                        oldPlayerTeam.setAllowFriendlyFire(
                            oldPlayerTeamFriendlyFire);
                    if (player != null)
                        oracleCaptureAuthoritativePlayerLocked(player);
                } catch (Throwable ignored) { }
            }
        }
    }

    /* Execute EntityAreaEffectCloud.onUpdate's real client branch against a
     * parked WorldServer. isRemote is changed only for the bounded call, and
     * an ordinary IWorldEventListener records every spawnAlwaysVisibleParticle
     * argument before ParticleManager constructor entropy is introduced. */
    /** EntityPlayerSP's client-only timeInPortal state machine, including the
     * Nausea threshold and its explicit removal reset. */
    private String oracleNauseaPortalLocked(final JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "nausea_portal_locked requires a parked oracle server");
        }
        try {
            return Minecraft.getMinecraft().addScheduledTask(
                new java.util.concurrent.Callable<String>() {
                    public String call() {
                        return oracleNauseaPortalClientLocked(action);
                    }
                }).get(30L, TimeUnit.SECONDS);
        } catch (Throwable t) {
            return err("nausea portal client task: " + t);
        }
    }

    private String oracleNauseaPortalClientLocked(JsonObject action) {
        net.minecraft.client.entity.EntityPlayerSP player =
            Minecraft.getMinecraft().player;
        if (player == null) return err("no client player");
        java.lang.reflect.Field inPortalField = null;
        net.minecraft.nbt.NBTTagCompound savedPlayer = null;
        java.util.ArrayList<net.minecraft.potion.PotionEffect> savedEffects =
            new java.util.ArrayList<net.minecraft.potion.PotionEffect>();
        float savedTime = player.timeInPortal;
        float savedPrev = player.prevTimeInPortal;
        boolean savedInPortal = false;
        try {
            if (!action.has("current_bits") || !action.has("prev_bits")
                    || !action.has("in_portal")
                    || !action.has("nausea_duration")
                    || !action.has("mode"))
                return err("incomplete Nausea portal fixture");
            String mode = action.get("mode").getAsString();
            int nauseaDuration = action.get("nausea_duration").getAsInt();
            if ((!mode.equals("step") && !mode.equals("remove"))
                    || nauseaDuration < 0 || nauseaDuration > 1000000)
                return err("invalid Nausea portal fixture");
            int currentBits = (int)Long.parseLong(
                action.get("current_bits").getAsString(), 16);
            int prevBits = (int)Long.parseLong(
                action.get("prev_bits").getAsString(), 16);
            float current = Float.intBitsToFloat(currentBits);
            float previous = Float.intBitsToFloat(prevBits);
            if (!Float.isFinite(current) || !Float.isFinite(previous)
                    || current < 0.0F || current > 1.0F
                    || previous < 0.0F || previous > 1.0F)
                return err("invalid Nausea portal float");

            inPortalField = net.minecraft.entity.Entity.class
                .getDeclaredField("inPortal");
            inPortalField.setAccessible(true);
            savedInPortal = inPortalField.getBoolean(player);
            savedPlayer = player.writeToNBT(
                new net.minecraft.nbt.NBTTagCompound());
            for (net.minecraft.potion.PotionEffect effect
                    : player.getActivePotionEffects())
                savedEffects.add(new net.minecraft.potion.PotionEffect(
                    effect.getPotion(), effect.getDuration(),
                    effect.getAmplifier(), effect.getIsAmbient(),
                    effect.doesShowParticles()));
            for (net.minecraft.potion.PotionEffect effect
                    : new java.util.ArrayList<
                        net.minecraft.potion.PotionEffect>(
                            player.getActivePotionEffects()))
                player.removePotionEffect(effect.getPotion());
            player.timeInPortal = current;
            player.prevTimeInPortal = previous;
            inPortalField.setBoolean(
                player, action.get("in_portal").getAsBoolean());
            if (nauseaDuration > 0)
                player.addPotionEffect(new net.minecraft.potion.PotionEffect(
                    net.minecraft.init.MobEffects.NAUSEA,
                    nauseaDuration, 0, false, true));

            JsonObject out = new JsonObject();
            out.addProperty("ok", true);
            out.addProperty("before_bits", oracleFloatBits(
                player.timeInPortal));
            out.addProperty("prev_before_bits", oracleFloatBits(
                player.prevTimeInPortal));
            if (mode.equals("remove"))
                player.removeActivePotionEffect(
                    net.minecraft.init.MobEffects.NAUSEA);
            else
                player.onLivingUpdate();
            out.addProperty("after_bits", oracleFloatBits(
                player.timeInPortal));
            out.addProperty("prev_after_bits", oracleFloatBits(
                player.prevTimeInPortal));
            out.addProperty("in_portal_after",
                inPortalField.getBoolean(player));
            out.addProperty("nausea_active_after", player.isPotionActive(
                net.minecraft.init.MobEffects.NAUSEA));
            return out.toString();
        } catch (Throwable t) {
            return err("nausea_portal_locked: " + t);
        } finally {
            if (savedPlayer != null) try {
                player.readFromNBT(savedPlayer);
            } catch (Throwable ignored) { }
            try {
                for (net.minecraft.potion.PotionEffect effect
                        : new java.util.ArrayList<
                            net.minecraft.potion.PotionEffect>(
                                player.getActivePotionEffects()))
                    player.removePotionEffect(effect.getPotion());
                for (net.minecraft.potion.PotionEffect effect : savedEffects)
                    player.addPotionEffect(effect);
                player.timeInPortal = savedTime;
                player.prevTimeInPortal = savedPrev;
                if (inPortalField != null)
                    inPortalField.setBoolean(player, savedInPortal);
            } catch (Throwable ignored) { }
        }
    }

    private String oracleAreaEffectCloudParticlesLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("area_effect_cloud_particles_locked requires a parked oracle server");
            net.minecraft.world.WorldServer world = null;
            net.minecraft.entity.EntityAreaEffectCloud cloud = null;
            OracleWorldEventCapture particles = null;
            java.lang.reflect.Field remoteField = null;
            boolean oldRemote = false;
            try {
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player =
                    server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                boolean waiting = action.has("waiting")
                    && action.get("waiting").getAsBoolean();
                long seed48 = action.has("entity_seed48")
                    ? action.get("entity_seed48").getAsLong()
                    : 0x123456789ABCL;
                float radius = action.has("radius")
                    ? action.get("radius").getAsFloat() : 3.0F;
                int particleId = action.has("particle")
                    ? action.get("particle").getAsInt()
                    : net.minecraft.util.EnumParticleTypes.SPELL_MOB
                        .getParticleID();
                int particleParam1 = action.has("particle_param1")
                    ? action.get("particle_param1").getAsInt() : 0;
                int particleParam2 = action.has("particle_param2")
                    ? action.get("particle_param2").getAsInt() : 0;
                net.minecraft.util.EnumParticleTypes particle =
                    net.minecraft.util.EnumParticleTypes
                        .getParticleFromId(particleId);
                if (seed48 < 0L || seed48 >= (1L << 48)
                        || !Float.isFinite(radius) || radius < 0.5F
                        || particle == null)
                    return err("invalid area-effect-cloud particle fixture");

                cloud = new net.minecraft.entity.EntityAreaEffectCloud(world);
                cloud.setPosition(
                    player.posX + 8.0D, player.posY + 20.0D,
                    player.posZ + 0.5D);
                cloud.setPotion(
                    net.minecraft.init.PotionTypes.STRONG_SWIFTNESS);
                cloud.setRadius(radius);
                cloud.setDuration(600);
                cloud.setWaitTime(10);
                cloud.ticksExisted = waiting ? 5 : 20;
                cloud.setParticle(particle);
                cloud.setParticleParam1(particleParam1);
                cloud.setParticleParam2(particleParam2);
                java.lang.reflect.Method setIgnoreRadius =
                    net.minecraft.entity.EntityAreaEffectCloud.class
                        .getDeclaredMethod("setIgnoreRadius", boolean.class);
                setIgnoreRadius.setAccessible(true);
                setIgnoreRadius.invoke(cloud, Boolean.valueOf(waiting));
                setJavaRandomSeed48(entityRandom(cloud), seed48);

                particles = new OracleWorldEventCapture(
                    (int)Math.floor(cloud.posX - radius - 1.0D),
                    (int)Math.floor(cloud.posY - 1.0D),
                    (int)Math.floor(cloud.posZ - radius - 1.0D),
                    (int)Math.floor(cloud.posX + radius + 1.0D),
                    (int)Math.floor(cloud.posY + 1.0D),
                    (int)Math.floor(cloud.posZ + radius + 1.0D));
                particles.captureParticles = true;
                world.addEventListener(particles);
                remoteField = net.minecraft.world.World.class
                    .getDeclaredField("isRemote");
                remoteField.setAccessible(true);
                oldRemote = remoteField.getBoolean(world);
                remoteField.setBoolean(world, true);
                cloud.onUpdate();

                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("waiting", waiting);
                out.addProperty("radius_bits", oracleFloatBits(radius));
                out.addProperty("particle", particleId);
                out.addProperty("particle_param1", particleParam1);
                out.addProperty("particle_param2", particleParam2);
                out.addProperty("x_bits", oracleDoubleBits(cloud.posX));
                out.addProperty("y_bits", oracleDoubleBits(cloud.posY));
                out.addProperty("z_bits", oracleDoubleBits(cloud.posZ));
                out.addProperty("entity_seed48",
                    javaRandomSeed48(entityRandom(cloud)));
                out.add("particles", particles.particlesToJson());
                return out.toString();
            } catch (Throwable t) {
                return err("area_effect_cloud_particles_locked: " + t);
            } finally {
                if (world != null && remoteField != null) try {
                    remoteField.setBoolean(world, oldRemote);
                } catch (Throwable ignored) { }
                if (world != null && particles != null) try {
                    world.removeEventListener(particles);
                } catch (Throwable ignored) { }
                if (cloud != null) cloud.setDead();
            }
        }
    }

    /**
     * Export the initialized vanilla registries that drive completeness
     * fixture generation. This is deliberately observational: callback
     * methods are identified from their declaring classes and no world
     * transition is invoked on the socket thread.
     */
    private String oracleRegistrySurfaces() {
        try {
            JsonObject out = new JsonObject();
            out.addProperty("ok", true);
            out.addProperty("schema", "qrl.registry_surfaces.v1");

            JsonArray blocks = new JsonArray();
            final java.util.Set<String> callbackNames =
                new java.util.TreeSet<String>(java.util.Arrays.asList(
                    "breakBlock", "dropBlockAsItemWithChance",
                    "eventReceived", "getComparatorInputOverride",
                    "hasComparatorInputOverride", "neighborChanged",
                    "onBlockActivated", "onBlockAdded",
                    "onBlockClicked", "onBlockDestroyedByExplosion",
                    "onBlockHarvested", "onBlockPlacedBy",
                    "onEntityCollidedWithBlock", "onEntityWalk",
                    "onFallenUpon", "randomDisplayTick", "randomTick",
                    "updateTick"));
            for (net.minecraft.block.Block block :
                    net.minecraft.block.Block.REGISTRY) {
                JsonObject row = new JsonObject();
                row.addProperty("id",
                    net.minecraft.block.Block.getIdFromBlock(block));
                net.minecraft.util.ResourceLocation name =
                    net.minecraft.block.Block.REGISTRY.getNameForObject(block);
                row.addProperty("name", name == null ? "" : name.toString());
                row.addProperty("class", block.getClass().getName());
                java.util.TreeSet<String> overrides =
                    new java.util.TreeSet<String>();
                JsonObject callbackOwners = new JsonObject();
                for (java.lang.reflect.Method method :
                        block.getClass().getMethods()) {
                    if (callbackNames.contains(method.getName())
                            && method.getDeclaringClass()
                                != net.minecraft.block.Block.class) {
                        overrides.add(method.getName());
                        callbackOwners.addProperty(method.getName(),
                            method.getDeclaringClass().getName());
                    }
                }
                JsonArray callbackArray = new JsonArray();
                for (String callback : overrides)
                    callbackArray.add(new JsonPrimitive(callback));
                row.add("callback_overrides", callbackArray);
                row.add("callback_owners", callbackOwners);
                row.addProperty("tick_randomly", block.getTickRandomly());
                boolean comparator = false;
                for (net.minecraft.block.state.IBlockState state :
                        block.getBlockState().getValidStates())
                    if (block.hasComparatorInputOverride(state)) {
                        comparator = true;
                        break;
                    }
                row.addProperty("comparator_override", comparator);
                blocks.add(row);
            }
            out.add("blocks", blocks);

            JsonArray items = new JsonArray();
            final java.util.Set<String> itemCallbackNames =
                new java.util.TreeSet<String>(java.util.Arrays.asList(
                    "canHarvestBlock", "doesSneakBypassUse",
                    "getAttributeModifiers", "getContainerItem",
                    "getDestroySpeed", "getHarvestLevel",
                    "getItemUseAction", "getMaxItemUseDuration",
                    "hasContainerItem", "hitEntity", "isValidArmor",
                    "itemInteractionForEntity", "onBlockDestroyed",
                    "onCreated", "onItemRightClick", "onItemUse",
                    "onPlayerStoppedUsing", "onUpdate", "onUsingTick"));
            for (net.minecraft.item.Item item :
                    net.minecraft.item.Item.REGISTRY) {
                JsonObject row = new JsonObject();
                int itemId = net.minecraft.item.Item.getIdFromItem(item);
                net.minecraft.util.ResourceLocation name =
                    net.minecraft.item.Item.REGISTRY.getNameForObject(item);
                row.addProperty("id", itemId);
                row.addProperty("name", name == null ? "" : name.toString());
                row.addProperty("class", item.getClass().getName());
                row.addProperty("stack_limit", item.getItemStackLimit());
                row.addProperty("max_damage", item.getMaxDamage());
                row.addProperty("repairable", item.isRepairable());
                row.addProperty("subtypes", item.getHasSubtypes());
                net.minecraft.item.ItemStack probe =
                    new net.minecraft.item.ItemStack(item, 1, 0);
                row.addProperty("use_action",
                    item.getItemUseAction(probe).name());
                row.addProperty("use_duration",
                    item.getMaxItemUseDuration(probe));
                row.addProperty("container_item", item.hasContainerItem()
                    ? net.minecraft.item.Item.getIdFromItem(
                        item.getContainerItem()) : 0);
                row.addProperty("placed_block",
                    item instanceof net.minecraft.item.ItemBlock
                    ? net.minecraft.block.Block.getIdFromBlock(
                        ((net.minecraft.item.ItemBlock)item).getBlock()) : 0);
                if (item instanceof net.minecraft.item.ItemFood) {
                    net.minecraft.item.ItemFood food =
                        (net.minecraft.item.ItemFood)item;
                    java.lang.reflect.Field alwaysField =
                        net.minecraft.item.ItemFood.class
                            .getDeclaredField("alwaysEdible");
                    java.lang.reflect.Field effectField =
                        net.minecraft.item.ItemFood.class
                            .getDeclaredField("potionId");
                    java.lang.reflect.Field probabilityField =
                        net.minecraft.item.ItemFood.class
                            .getDeclaredField("potionEffectProbability");
                    alwaysField.setAccessible(true);
                    effectField.setAccessible(true);
                    probabilityField.setAccessible(true);
                    row.addProperty("food_always_edible",
                        alwaysField.getBoolean(food));
                    row.addProperty("food_wolf", food.isWolfsFavoriteMeat());
                    net.minecraft.potion.PotionEffect effect =
                        (net.minecraft.potion.PotionEffect)
                            effectField.get(food);
                    row.addProperty("food_effect_id", effect == null ? -1
                        : net.minecraft.potion.Potion.getIdFromPotion(
                            effect.getPotion()));
                    row.addProperty("food_effect_duration", effect == null
                        ? 0 : effect.getDuration());
                    row.addProperty("food_effect_amplifier", effect == null
                        ? 0 : effect.getAmplifier());
                    row.addProperty("food_effect_probability_bits",
                        oracleFloatBits(probabilityField.getFloat(food)));
                    net.minecraft.util.NonNullList<net.minecraft.item.ItemStack>
                        variants = net.minecraft.util.NonNullList.create();
                    item.getSubItems(item, item.getCreativeTab(), variants);
                    if (variants.isEmpty()) variants.add(probe);
                    JsonArray foodVariants = new JsonArray();
                    for (net.minecraft.item.ItemStack variant : variants) {
                        JsonObject foodVariant = new JsonObject();
                        foodVariant.addProperty(
                            "meta", variant.getMetadata());
                        foodVariant.addProperty(
                            "heal", food.getHealAmount(variant));
                        foodVariant.addProperty("saturation_bits",
                            oracleFloatBits(
                                food.getSaturationModifier(variant)));
                        foodVariants.add(foodVariant);
                    }
                    row.add("food_variants", foodVariants);
                }
                java.util.TreeSet<String> overrides =
                    new java.util.TreeSet<String>();
                JsonObject callbackOwners = new JsonObject();
                for (java.lang.reflect.Method method :
                        item.getClass().getMethods()) {
                    if (itemCallbackNames.contains(method.getName())
                            && method.getDeclaringClass()
                                != net.minecraft.item.Item.class) {
                        overrides.add(method.getName());
                        callbackOwners.addProperty(method.getName(),
                            method.getDeclaringClass().getName());
                    }
                }
                JsonArray callbackArray = new JsonArray();
                for (String callback : overrides)
                    callbackArray.add(new JsonPrimitive(callback));
                row.add("callback_overrides", callbackArray);
                row.add("callback_owners", callbackOwners);
                items.add(row);
            }
            out.add("items", items);

            JsonArray recipes = new JsonArray();
            java.util.List<net.minecraft.item.crafting.IRecipe> recipeList =
                net.minecraft.item.crafting.CraftingManager.getInstance()
                    .getRecipeList();
            for (int index = 0; index < recipeList.size(); ++index) {
                net.minecraft.item.crafting.IRecipe recipe =
                    recipeList.get(index);
                net.minecraft.item.ItemStack result =
                    recipe.getRecipeOutput();
                JsonObject row = new JsonObject();
                row.addProperty("index", index);
                row.addProperty("class", recipe.getClass().getName());
                row.addProperty("dynamic", result == null || result.isEmpty());
                if (result != null && !result.isEmpty()) {
                    row.addProperty("output_item",
                        net.minecraft.item.Item.getIdFromItem(result.getItem()));
                    row.addProperty("output_meta", result.getMetadata());
                    row.addProperty("output_count", result.getCount());
                }
                if (recipe.getClass()
                        == net.minecraft.item.crafting.ShapedRecipes.class) {
                    net.minecraft.item.crafting.ShapedRecipes shaped =
                        (net.minecraft.item.crafting.ShapedRecipes)recipe;
                    row.addProperty("kind", "shaped");
                    row.addProperty("width", shaped.recipeWidth);
                    row.addProperty("height", shaped.recipeHeight);
                    row.addProperty("mirrored", true);
                    JsonArray ingredients = new JsonArray();
                    for (net.minecraft.item.ItemStack stack :
                            shaped.recipeItems)
                        ingredients.add(oracleRecipeIngredient(stack));
                    row.add("ingredients", ingredients);
                } else if (recipe.getClass()
                        == net.minecraft.item.crafting.ShapelessRecipes.class) {
                    net.minecraft.item.crafting.ShapelessRecipes shapeless =
                        (net.minecraft.item.crafting.ShapelessRecipes)recipe;
                    row.addProperty("kind", "shapeless");
                    row.addProperty("width", 0);
                    row.addProperty("height", 0);
                    row.addProperty("mirrored", false);
                    JsonArray ingredients = new JsonArray();
                    for (net.minecraft.item.ItemStack stack :
                            shapeless.recipeItems)
                        ingredients.add(oracleRecipeIngredient(stack));
                    row.add("ingredients", ingredients);
                } else if (recipe.getClass()
                        == net.minecraftforge.oredict.ShapedOreRecipe.class) {
                    row.addProperty("kind", "shaped_ore");
                    row.addProperty("width", ((Integer)oracleRecipeField(
                        recipe, "width")).intValue());
                    row.addProperty("height", ((Integer)oracleRecipeField(
                        recipe, "height")).intValue());
                    row.addProperty("mirrored", ((Boolean)oracleRecipeField(
                        recipe, "mirrored")).booleanValue());
                    JsonArray ingredients = new JsonArray();
                    for (Object ingredient : (Object[])oracleRecipeField(
                            recipe, "input"))
                        ingredients.add(oracleRecipeIngredient(ingredient));
                    row.add("ingredients", ingredients);
                } else if (recipe.getClass()
                        == net.minecraftforge.oredict.ShapelessOreRecipe.class) {
                    row.addProperty("kind", "shapeless_ore");
                    row.addProperty("width", 0);
                    row.addProperty("height", 0);
                    row.addProperty("mirrored", false);
                    JsonArray ingredients = new JsonArray();
                    for (Object ingredient : (java.util.List<?>)
                            oracleRecipeField(recipe, "input"))
                        ingredients.add(oracleRecipeIngredient(ingredient));
                    row.add("ingredients", ingredients);
                } else {
                    row.addProperty("kind", "special");
                }
                recipes.add(row);
            }
            out.add("crafting_recipes", recipes);

            java.util.ArrayList<JsonObject> smeltingRows =
                new java.util.ArrayList<JsonObject>();
            for (java.util.Map.Entry<net.minecraft.item.ItemStack,
                    net.minecraft.item.ItemStack> entry :
                    net.minecraft.item.crafting.FurnaceRecipes.instance()
                        .getSmeltingList().entrySet()) {
                net.minecraft.item.ItemStack input = entry.getKey();
                net.minecraft.item.ItemStack result = entry.getValue();
                JsonObject row = new JsonObject();
                row.addProperty("input_item",
                    net.minecraft.item.Item.getIdFromItem(input.getItem()));
                row.addProperty("input_meta", input.getMetadata());
                row.addProperty("output_item",
                    net.minecraft.item.Item.getIdFromItem(result.getItem()));
                row.addProperty("output_meta", result.getMetadata());
                row.addProperty("output_count", result.getCount());
                smeltingRows.add(row);
            }
            java.util.Collections.sort(smeltingRows,
                new java.util.Comparator<JsonObject>() {
                    public int compare(JsonObject left, JsonObject right) {
                        for (String key : new String[] {
                                "input_item", "input_meta", "output_item",
                                "output_meta", "output_count"}) {
                            int compared = Integer.compare(
                                left.get(key).getAsInt(),
                                right.get(key).getAsInt());
                            if (compared != 0) return compared;
                        }
                        return 0;
                    }
                });
            JsonArray smelting = new JsonArray();
            for (JsonObject row : smeltingRows) smelting.add(row);
            out.add("smelting_recipes", smelting);

            JsonArray potions = new JsonArray();
            for (net.minecraft.potion.Potion potion :
                    net.minecraft.potion.Potion.REGISTRY) {
                JsonObject row = new JsonObject();
                row.addProperty("id",
                    net.minecraft.potion.Potion.getIdFromPotion(potion));
                row.addProperty("name",
                    net.minecraft.potion.Potion.REGISTRY
                        .getNameForObject(potion).toString());
                row.addProperty("class", potion.getClass().getName());
                potions.add(row);
            }
            out.add("potions", potions);

            JsonArray potionTypes = new JsonArray();
            for (net.minecraft.potion.PotionType potionType :
                    net.minecraft.potion.PotionType.REGISTRY) {
                JsonObject row = new JsonObject();
                row.addProperty("id",
                    net.minecraft.potion.PotionType.REGISTRY
                        .getIDForObject(potionType));
                row.addProperty("name",
                    net.minecraft.potion.PotionType.REGISTRY
                        .getNameForObject(potionType).toString());
                potionTypes.add(row);
            }
            out.add("potion_types", potionTypes);

            java.util.ArrayList<String> lootNames =
                new java.util.ArrayList<String>();
            for (net.minecraft.util.ResourceLocation name :
                    net.minecraft.world.storage.loot.LootTableList.getAll())
                lootNames.add(name.toString());
            java.util.Collections.sort(lootNames);
            JsonArray lootTables = new JsonArray();
            for (String name : lootNames)
                lootTables.add(new JsonPrimitive(name));
            out.add("loot_tables", lootTables);
            return out.toString();
        } catch (Throwable t) {
            return err("registry_surfaces failed: " + t);
        }
    }

    private static Object oracleRecipeField(Object owner, String name)
            throws Exception {
        for (Class<?> type = owner.getClass(); type != null;
                type = type.getSuperclass()) {
            try {
                java.lang.reflect.Field field = type.getDeclaredField(name);
                field.setAccessible(true);
                return field.get(owner);
            } catch (NoSuchFieldException ignored) { }
        }
        throw new NoSuchFieldException(owner.getClass().getName() + "." + name);
    }

    private static JsonObject oracleRecipeStack(
            net.minecraft.item.ItemStack stack) {
        JsonObject out = new JsonObject();
        out.addProperty("item",
            net.minecraft.item.Item.getIdFromItem(stack.getItem()));
        out.addProperty("meta", stack.getMetadata());
        out.addProperty("count", stack.getCount());
        return out;
    }

    private static JsonObject oracleRecipeIngredient(Object ingredient) {
        JsonObject out = new JsonObject();
        JsonArray choices = new JsonArray();
        if (ingredient instanceof net.minecraft.item.ItemStack) {
            net.minecraft.item.ItemStack stack =
                (net.minecraft.item.ItemStack)ingredient;
            if (!stack.isEmpty()) choices.add(oracleRecipeStack(stack));
        } else if (ingredient instanceof java.util.List<?>) {
            for (Object choice : (java.util.List<?>)ingredient)
                if (choice instanceof net.minecraft.item.ItemStack
                        && !((net.minecraft.item.ItemStack)choice).isEmpty())
                    choices.add(oracleRecipeStack(
                        (net.minecraft.item.ItemStack)choice));
        }
        out.add("choices", choices);
        return out;
    }

    /** Export furnace fuel and output XP for every initialized item row. */
    private String oracleFurnaceRegistry() {
        try {
            JsonObject out = new JsonObject();
            out.addProperty("ok", true);
            out.addProperty("schema", "qrl.furnace_registry.v2");
            java.util.ArrayList<JsonObject> rows =
                new java.util.ArrayList<JsonObject>();
            for (net.minecraft.item.Item item : net.minecraft.item.Item.REGISTRY) {
                JsonObject row = new JsonObject();
                int id = net.minecraft.item.Item.getIdFromItem(item);
                net.minecraft.util.ResourceLocation name =
                    net.minecraft.item.Item.REGISTRY.getNameForObject(item);
                net.minecraft.item.ItemStack stack =
                    new net.minecraft.item.ItemStack(item, 1, 0);
                row.addProperty("id", id);
                row.addProperty("name", name == null ? "" : name.toString());
                row.addProperty("class", item.getClass().getName());
                row.addProperty("burn_time",
                    net.minecraft.tileentity.TileEntityFurnace
                        .getItemBurnTime(stack));
                JsonArray experienceBits = new JsonArray();
                for (int meta = 0; meta < 16; ++meta) {
                    float experience = net.minecraft.item.crafting
                        .FurnaceRecipes.instance().getSmeltingExperience(
                            new net.minecraft.item.ItemStack(item, 1, meta));
                    experienceBits.add(new JsonPrimitive(
                        Float.floatToRawIntBits(experience)));
                }
                row.add("experience_bits", experienceBits);
                rows.add(row);
            }
            java.util.Collections.sort(rows,
                new java.util.Comparator<JsonObject>() {
                    public int compare(JsonObject left, JsonObject right) {
                        return Integer.compare(
                            left.get("id").getAsInt(),
                            right.get("id").getAsInt());
                    }
                });
            JsonArray items = new JsonArray();
            for (JsonObject row : rows) items.add(row);
            out.add("items", items);
            return out.toString();
        } catch (Throwable t) {
            return err("furnace_registry failed: " + t);
        }
    }

    /** Read the client resource pack's resolved baked quads on the render
     * thread, including Forge's active vertex format and post-rotation face. */
    private String oracleBakedModelProbe(final JsonObject action) {
        try {
            return Minecraft.getMinecraft().addScheduledTask(
                new java.util.concurrent.Callable<String>() {
                    public String call() {
                        try {
                            String name = action.has("block")
                                ? action.get("block").getAsString()
                                : "red_mushroom";
                            net.minecraft.block.Block block =
                                net.minecraft.block.Block.getBlockFromName(name);
                            if (block == null && name.indexOf(':') < 0)
                                block = net.minecraft.block.Block.getBlockFromName(
                                    "minecraft:" + name);
                            if (block == null) return err("unknown block " + name);
                            net.minecraft.block.state.IBlockState state =
                                block.getDefaultState();
                            net.minecraft.client.renderer.block.model.IBakedModel model =
                                Minecraft.getMinecraft().getBlockRendererDispatcher()
                                    .getModelForState(state);
                            JsonObject out = new JsonObject();
                            out.addProperty("ok", true);
                            out.addProperty("block", String.valueOf(
                                net.minecraft.block.Block.REGISTRY.getNameForObject(block)));
                            out.addProperty("ambient_occlusion", model.isAmbientOcclusion());
                            out.addProperty("gui3d", model.isGui3d());
                            JsonArray quads = new JsonArray();
                            net.minecraft.util.EnumFacing[] sides =
                                net.minecraft.util.EnumFacing.values();
                            for (int sideIndex = 0; sideIndex <= sides.length;
                                    ++sideIndex) {
                                net.minecraft.util.EnumFacing side =
                                    sideIndex == sides.length ? null : sides[sideIndex];
                                java.util.List<net.minecraft.client.renderer.block.model.BakedQuad>
                                    list = model.getQuads(state, side, 0L);
                                for (int qi = 0; qi < list.size(); ++qi) {
                                    net.minecraft.client.renderer.block.model.BakedQuad q =
                                        list.get(qi);
                                    JsonObject row = new JsonObject();
                                    row.addProperty("query_side",
                                        side == null ? "null" : side.getName());
                                    row.addProperty("index", qi);
                                    row.addProperty("face", q.getFace().getName());
                                    row.addProperty("tint", q.getTintIndex());
                                    row.addProperty("diffuse",
                                        q.shouldApplyDiffuseLighting());
                                    row.addProperty("stride_ints",
                                        q.getFormat().getNextOffset() / 4);
                                    row.addProperty("sprite", q.getSprite().getIconName());
                                    JsonArray data = new JsonArray();
                                    for (int value : q.getVertexData())
                                        data.add(new JsonPrimitive(String.format(
                                            java.util.Locale.ROOT, "%08x", value)));
                                    row.add("vertex_data_hex", data);
                                    quads.add(row);
                                }
                            }
                            out.add("quads", quads);
                            return out.toString();
                        } catch (Throwable t) {
                            return err("baked model probe: " + t);
                        }
                    }
                }).get(30L, TimeUnit.SECONDS);
        } catch (Throwable t) {
            return err("baked model probe task: " + t);
        }
    }

    /**
     * Export immutable legacy block-state predicates directly from the
     * initialized 1.11.2 registry. The socket thread may read these objects:
     * registration has completed before the bridge starts and the states are
     * immutable. Masks use raw metadata bits 0..15; canonical_meta records the
     * state mapping applied by each Block.getStateFromMeta implementation.
     */
    private String blockStateProperties() {
        JsonObject out = new JsonObject();
        JsonArray blocks = new JsonArray();
        int errors = 0;
        for (int id = 0; id < 256; ++id) {
            net.minecraft.block.Block block =
                net.minecraft.block.Block.getBlockById(id);
            if (block == null) continue;
            int normalMask = 0;
            int fullMask = 0;
            int fullyOpaqueMask = 0;
            int suffocationMask = 0;
            int opaqueMask = 0;
            int solidMask = 0;
            int burningMask = 0;
            int blocksMovementMask = 0;
            int noteRockMask = 0;
            int noteSandMask = 0;
            int noteGlassMask = 0;
            int noteWoodMask = 0;
            int powerMask = 0;
            int pistonDestroyMask = 0;
            int pistonBlockMask = 0;
            int pistonUnbreakableMask = 0;
            int tileEntityMask = 0;
            JsonArray canonicalMeta = new JsonArray();
            for (int meta = 0; meta < 16; ++meta) {
                try {
                    net.minecraft.block.state.IBlockState state =
                        block.getStateFromMeta(meta);
                    canonicalMeta.add(
                        new JsonPrimitive(block.getMetaFromState(state)));
                    if (state.isNormalCube())
                        normalMask |= 1 << meta;
                    if (state.isFullCube())
                        fullMask |= 1 << meta;
                    if (state.isFullyOpaque())
                        fullyOpaqueMask |= 1 << meta;
                    if (state.causesSuffocation())
                        suffocationMask |= 1 << meta;
                    if (state.getMaterial().isOpaque())
                        opaqueMask |= 1 << meta;
                    if (state.getMaterial().isSolid())
                        solidMask |= 1 << meta;
                    if (state.getMaterial().getCanBurn())
                        burningMask |= 1 << meta;
                    if (state.getMaterial().blocksMovement())
                        blocksMovementMask |= 1 << meta;
                    if (state.getMaterial()
                            == net.minecraft.block.material.Material.ROCK)
                        noteRockMask |= 1 << meta;
                    if (state.getMaterial()
                            == net.minecraft.block.material.Material.SAND)
                        noteSandMask |= 1 << meta;
                    if (state.getMaterial()
                            == net.minecraft.block.material.Material.GLASS)
                        noteGlassMask |= 1 << meta;
                    if (state.getMaterial()
                            == net.minecraft.block.material.Material.WOOD)
                        noteWoodMask |= 1 << meta;
                    if (state.canProvidePower())
                        powerMask |= 1 << meta;
                    if (state.getMobilityFlag()
                            == net.minecraft.block.material.EnumPushReaction
                                .DESTROY)
                        pistonDestroyMask |= 1 << meta;
                    if (state.getMobilityFlag()
                            == net.minecraft.block.material.EnumPushReaction
                                .BLOCK)
                        pistonBlockMask |= 1 << meta;
                    if (Float.floatToRawIntBits(
                            state.getBlockHardness(null, null))
                            == Float.floatToRawIntBits(-1.0F))
                        pistonUnbreakableMask |= 1 << meta;
                    if (block.hasTileEntity(state))
                        tileEntityMask |= 1 << meta;
                } catch (Throwable t) {
                    canonicalMeta.add(new JsonPrimitive(-1));
                    ++errors;
                }
            }
            JsonObject row = new JsonObject();
            row.addProperty("id", id);
            net.minecraft.util.ResourceLocation name =
                net.minecraft.block.Block.REGISTRY.getNameForObject(block);
            row.addProperty("name", name == null ? "" : name.toString());
            row.addProperty("normal_cube_mask", normalMask);
            row.addProperty("full_cube_mask", fullMask);
            row.addProperty("fully_opaque_mask", fullyOpaqueMask);
            row.addProperty("causes_suffocation_mask", suffocationMask);
            row.addProperty("opaque_material_mask", opaqueMask);
            row.addProperty("solid_material_mask", solidMask);
            row.addProperty("burning_material_mask", burningMask);
            row.addProperty("blocks_movement_mask", blocksMovementMask);
            row.addProperty("note_rock_material_mask", noteRockMask);
            row.addProperty("note_sand_material_mask", noteSandMask);
            row.addProperty("note_glass_material_mask", noteGlassMask);
            row.addProperty("note_wood_material_mask", noteWoodMask);
            row.addProperty("can_provide_power_mask", powerMask);
            row.addProperty("piston_destroy_mask", pistonDestroyMask);
            row.addProperty("piston_block_mask", pistonBlockMask);
            row.addProperty(
                "piston_unbreakable_mask", pistonUnbreakableMask);
            row.addProperty("tile_entity_mask", tileEntityMask);
            row.add("canonical_meta", canonicalMeta);
            blocks.add(row);
        }
        out.addProperty("ok", true);
        out.addProperty("schema", "qrl.blockstate_props.v4");
        out.addProperty("minecraft", "1.11.2");
        out.addProperty("error_count", errors);
        out.add("blocks", blocks);
        return out.toString();
    }

    /** Arm/disarm the server-only oracle gate directly from the socket thread. */
    private String handleOracleServerControl(String cmd) throws InterruptedException {
        synchronized (oracleServerMonitor) {
            if (cmd.equals("server_step_unlock")) {
                oracleServerGate = false;
                oracleSuppressWorldgenSpawning = false;
                oracleServerPermits = 0;
                oracleRandomTickPending = false;
                oracleBlockMutationPending = false;
                oraclePlayerUseCursorRestorePending = false;
                oracleTntArrowCursorRestorePending = false;
                oracleTntDetonationCursorRestorePending = false;
                oracleServerMonitor.notifyAll();
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("completed", oracleServerCompleted);
                return out.toString();
            }

            if (oracleServerTickInFlight || oracleServerPermits != 0) {
                return err("cannot arm server gate with a permitted tick in flight");
            }
            oracleServerGate = true;
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
            while (!oracleServerWaiting) {
                long remaining = deadline - System.nanoTime();
                if (remaining <= 0) {
                    oracleServerGate = false;
                    oracleServerMonitor.notifyAll();
                    return err("server did not reach oracle tick boundary");
                }
                TimeUnit.NANOSECONDS.timedWait(oracleServerMonitor, remaining);
            }
            JsonObject out = new JsonObject();
            out.addProperty("ok", true);
            out.addProperty("waiting", true);
            out.addProperty("completed", oracleServerCompleted);
            JsonObject authoritative = oracleAuthoritativeJsonLocked();
            if (authoritative == null) {
                oracleServerGate = false;
                oracleServerMonitor.notifyAll();
                return err("server gate armed without an authoritative player snapshot");
            }
            out.add("authoritative", authoritative);
            return out.toString();
        }
    }

    /**
     * Wait for the permitted server tick and for the server to park again at
     * the following START boundary. The second condition makes a subsequent
     * read-only world dump race-free without granting an extra simulation tick.
     */
    private JsonObject oracleWaitForStep(long target, long timeoutMs)
            throws InterruptedException {
        synchronized (oracleServerMonitor) {
            long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMs);
            while (oracleServerGate
                    && (oracleServerCompleted < target || !oracleServerWaiting)) {
                long remaining = deadline - System.nanoTime();
                if (remaining <= 0) return null;
                TimeUnit.NANOSECONDS.timedWait(oracleServerMonitor, remaining);
            }
            if (!oracleServerGate || oracleServerCompleted != target
                    || !oracleServerWaiting) {
                return null;
            }
            return oracleAuthoritativeJsonLocked();
        }
    }

    private void oracleMirrorPotionsToClient(JsonObject authoritative) {
        if (!oracleMirrorPotionFixture || authoritative == null
                || !authoritative.has("potions")) return;
        oraclePotionClientSnapshot = authoritative;
        net.minecraft.client.entity.EntityPlayerSP cp =
            Minecraft.getMinecraft().player;
        if (cp == null) return;
        /* A late SPacketEntityProperties can leave a potion attribute modifier
         * after the corresponding client PotionEffect has already vanished.
         * Remove every potion-owned attribute UUID first, then rebuild the
         * exact authoritative set below. The fixture replaces all effects, so
         * this is both complete and independent of packet delivery order. */
        for (net.minecraft.potion.Potion potion :
                net.minecraft.potion.Potion.REGISTRY) {
            potion.removeAttributesModifiersFromEntity(
                cp, cp.getAttributeMap(), 0);
        }
        ArrayList<net.minecraft.potion.PotionEffect> active =
            new ArrayList<net.minecraft.potion.PotionEffect>(
                cp.getActivePotionEffects());
        for (net.minecraft.potion.PotionEffect effect : active) {
            effect.getPotion().removeAttributesModifiersFromEntity(
                cp, cp.getAttributeMap(), effect.getAmplifier());
            cp.removePotionEffect(effect.getPotion());
        }
        for (com.google.gson.JsonElement el :
                authoritative.getAsJsonArray("potions")) {
            JsonObject effect = el.getAsJsonObject();
            net.minecraft.potion.Potion potion =
                net.minecraft.potion.Potion.getPotionById(
                    effect.get("id").getAsInt());
            if (potion == null) continue;
            int duration = effect.get("dur").getAsInt();
            int amplifier = effect.get("amp").getAsInt();
            boolean ambient = effect.has("ambient")
                && effect.get("ambient").getAsBoolean();
            boolean showParticles = !effect.has("show_particles")
                || effect.get("show_particles").getAsBoolean();
            cp.addPotionEffect(new net.minecraft.potion.PotionEffect(
                potion, duration, amplifier, ambient, showParticles));
            potion.applyAttributesModifiersToEntity(
                cp, cp.getAttributeMap(), amplifier);
        }
    }

    /** Called on the client tick immediately after an action is installed. */
    private boolean oracleGrantServerTick() {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate) return true;
            if (oracleServerPermits != 0 || oracleServerTickInFlight) return false;
            oracleRestoreIsolatedServerGlobals();
            oracleServerPermits = 1;
            oracleServerMonitor.notifyAll();
            return true;
        }
    }

    /** During cold reload, advance startup at most once per client tick. */
    private void oracleGrantBootstrapTick() {
        synchronized (oracleServerMonitor) {
            if (!oracleAutoParkPending || !oracleServerGate
                    || !oracleServerWaiting || oracleServerPermits != 0
                    || oracleServerTickInFlight) return;
            oracleServerPermits = 1;
            oracleServerMonitor.notifyAll();
        }
    }

    /** ServerTickEvent.START: consume exactly one permit or park the server. */
    private void oracleAwaitServerPermit() {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate) {
                oracleServerWaiting = false;
                oracleServerTickInFlight = false;
                return;
            }
            oracleServerWaiting = true;
            oracleServerMonitor.notifyAll();
            while (oracleServerGate && oracleServerPermits == 0) {
                try {
                    oracleServerMonitor.wait();
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    oracleServerGate = false;
                    oracleServerWaiting = false;
                    oracleServerMonitor.notifyAll();
                    return;
                }
            }
            oracleServerWaiting = false;
            if (oracleServerGate) {
                oracleServerPermits--;
                oracleServerTickInFlight = true;
                oracleEntityCollisions.clear();
                oracleEntityCollisionStack.get().clear();
                if (oracleServerDiscardQueuedTasks) {
                    try {
                        MinecraftServer server =
                            net.minecraftforge.fml.common.FMLCommonHandler
                                .instance().getMinecraftServerInstance();
                        if (server != null) {
                            synchronized (server.futureTaskQueue) {
                                server.futureTaskQueue.clear();
                            }
                        }
                    } catch (Throwable t) {
                        throw new IllegalStateException(
                            "could not discard uncontrolled server tasks", t);
                    }
                }
            } else {
                oracleServerTickInFlight = false;
            }
        }
    }

    /** ServerTickEvent.END: publish one atomic authoritative checkpoint. */
    private void oracleFinishServerTick() {
        net.minecraft.entity.player.EntityPlayerMP p = null;
        try {
            MinecraftServer srv =
                net.minecraftforge.fml.common.FMLCommonHandler.instance()
                    .getMinecraftServerInstance();
            java.util.List<net.minecraft.entity.player.EntityPlayerMP> players =
                srv == null ? null : srv.getPlayerList().getPlayers();
            if (players != null && !players.isEmpty()) p = players.get(0);
        } catch (Throwable ig) {}
        synchronized (oracleServerMonitor) {
            if (oracleServerTickInFlight && oracleServerGlobalIsolation) {
                try {
                    java.util.Random inventoryRandom = inventoryHelperRandom();
                    oracleServerInventoryHelperSeed48 =
                        javaRandomSeed48(inventoryRandom);
                    oracleServerInventoryHelperHaveGaussian =
                        javaRandomHaveNextGaussian(inventoryRandom);
                    oracleServerInventoryHelperGaussian =
                        javaRandomNextGaussian(inventoryRandom);
                } catch (Exception e) {
                    throw new IllegalStateException(
                        "could not capture InventoryHelper.RANDOM", e);
                }
            }
            if (p != null) {
                oracleCaptureAuthoritativePlayerLocked(p);
                if (oracleControlledInputValid) {
                    oracleAuthControlledInputValid = true;
                    oracleAuthControlledBeforeWorldRandSeed48 =
                        oracleControlledBeforeWorldRandSeed48;
                    oracleAuthControlledBeforeMathRandSeed48 =
                        oracleControlledBeforeMathRandSeed48;
                    oracleAuthControlledBeforeBlockRandSeed48 =
                        oracleControlledBeforeBlockRandSeed48;
                    oracleAuthControlledBeforeInventoryHelperRandSeed48 =
                        oracleControlledBeforeInventoryHelperRandSeed48;
                    oracleAuthControlledBeforeInventoryHelperRandHaveGaussian =
                        oracleControlledBeforeInventoryHelperRandHaveGaussian;
                    oracleAuthControlledBeforeInventoryHelperRandGaussian =
                        oracleControlledBeforeInventoryHelperRandGaussian;
                    oracleAuthControlledBeforeWorldUpdateLCG =
                        oracleControlledBeforeWorldUpdateLCG;
                    oracleAuthControlledBeforeNextEntityId =
                        oracleControlledBeforeNextEntityId;
                    oracleAuthControlledWorldRandSeed48 =
                        oracleControlledWorldRandSeed48;
                    oracleAuthControlledMathRandSeed48 =
                        oracleControlledMathRandSeed48;
                    oracleAuthControlledBlockRandSeed48 =
                        oracleControlledBlockRandSeed48;
                    oracleAuthControlledInventoryHelperRandSeed48 =
                        oracleControlledInventoryHelperRandSeed48;
                    oracleAuthControlledInventoryHelperRandHaveGaussian =
                        oracleControlledInventoryHelperRandHaveGaussian;
                    oracleAuthControlledInventoryHelperRandGaussian =
                        oracleControlledInventoryHelperRandGaussian;
                    oracleAuthControlledWorldUpdateLCG =
                        oracleControlledWorldUpdateLCG;
                    oracleAuthControlledNextEntityId =
                        oracleControlledNextEntityId;
                }
                oraclePlayerUseItemRandomPending = false;
            }
            oracleAuthMovePacketCursorValid = false;
            if (oracleServerTickInFlight) {
                if (oracleServerGlobalIsolation) {
                    oracleServerBlockSeed48 = blockRandomSeed48();
                }
                oracleServerCompleted++;
                oracleServerTickInFlight = false;
                oracleServerDiscardQueuedTasks = false;
            }
            oracleServerMonitor.notifyAll();
        }
    }

    /** Must be called with oracleServerMonitor held. */
    private int[] oracleBoundedTimeCommand(String command) {
        if (command == null) return null;
        String lower = command.toLowerCase(java.util.Locale.ROOT);
        int kind;
        String argument;
        if (lower.startsWith("time set ")) {
            kind = 1;
            argument = lower.substring(9);
            if ("day".equals(argument)) return new int[] {kind, 1000};
            if ("night".equals(argument)) return new int[] {kind, 13000};
        } else if (lower.startsWith("time add ")) {
            kind = 2;
            argument = lower.substring(9);
        } else if (lower.startsWith("time query ")) {
            argument = lower.substring(11);
            if ("daytime".equals(argument)) return new int[] {3, 0};
            if ("day".equals(argument)) return new int[] {4, 0};
            if ("gametime".equals(argument)) return new int[] {5, 0};
            return null;
        } else {
            return null;
        }
        if (!argument.matches("[0-9]+")) return null;
        try {
            int value = Integer.parseInt(argument);
            return value >= 0 ? new int[] {kind, value} : null;
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    private int[] oracleBoundedWeatherCommand(String command) {
        if (command == null) return null;
        String[] fields = command.toLowerCase(java.util.Locale.ROOT)
            .split(" ", -1);
        if ((fields.length != 2 && fields.length != 3)
                || !"weather".equals(fields[0])) return null;
        int kind = "clear".equals(fields[1]) ? 1
            : "rain".equals(fields[1]) ? 2
            : "thunder".equals(fields[1]) ? 3 : 0;
        if (kind == 0) return null;
        if (fields.length == 2) return new int[] {kind, 0};
        if (!fields[2].matches("[0-9]+")) return null;
        try {
            int seconds = Integer.parseInt(fields[2]);
            return seconds >= 1 && seconds <= 1000000
                ? new int[] {kind, seconds * 20} : null;
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    private String[] oracleBoundedGameRuleCommand(String command) {
        if (command == null) return null;
        String[] fields = command.split(" ", -1);
        if (fields.length != 3
                || !"gamerule".equalsIgnoreCase(fields[0])) return null;
        java.util.Set<String> booleans = new java.util.HashSet<String>(
            java.util.Arrays.asList(
                "doDaylightCycle", "doMobSpawning", "doFireTick",
                "mobGriefing", "keepInventory", "doTileDrops",
                "naturalRegeneration", "doWeatherCycle"));
        if (booleans.contains(fields[1])) {
            if (!"true".equals(fields[2]) && !"false".equals(fields[2]))
                return null;
            return new String[] {fields[1], fields[2]};
        }
        if (!"randomTickSpeed".equals(fields[1])
                && !"maxEntityCramming".equals(fields[1])) return null;
        try {
            Integer.parseInt(fields[2]);
            return new String[] {fields[1], fields[2]};
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    private boolean oracleBoundedSetBlockCommand(String command) {
        if (command == null) return false;
        String[] fields = command.split(" ", -1);
        if (fields.length < 5 || fields.length > 7
                || !"setblock".equalsIgnoreCase(fields[0])) return false;
        for (int index = 1; index <= 3; ++index)
            if (!fields[index].matches("(?:~(?:-?[0-9]+)?)|-?[0-9]+"))
                return false;
        net.minecraft.block.Block block = net.minecraft.block.Block.REGISTRY
            .getObject(new net.minecraft.util.ResourceLocation(fields[4]));
        if (block == null || block == net.minecraft.init.Blocks.AIR
                && !"minecraft:air".equals(fields[4])) return false;
        if (fields.length >= 6) {
            try {
                int meta = Integer.parseInt(fields[5]);
                if (meta < 0 || meta > 15) return false;
            } catch (NumberFormatException ignored) {
                return false;
            }
        }
        return fields.length < 7 || "replace".equals(fields[6])
            || "keep".equals(fields[6]) || "destroy".equals(fields[6]);
    }

    private boolean oracleBoundedTestForBlockCommand(String command) {
        if (command == null) return false;
        String[] fields = command.split(" ", -1);
        if ((fields.length != 5 && fields.length != 6)
                || !"testforblock".equalsIgnoreCase(fields[0])) return false;
        for (int index = 1; index <= 3; ++index)
            if (!fields[index].matches("(?:~(?:-?[0-9]+)?)|-?[0-9]+"))
                return false;
        net.minecraft.block.Block block = net.minecraft.block.Block.REGISTRY
            .getObject(new net.minecraft.util.ResourceLocation(fields[4]));
        if (block == null || block == net.minecraft.init.Blocks.AIR
                && !"minecraft:air".equals(fields[4])) return false;
        if (fields.length == 5 || "*".equals(fields[5])) return true;
        try {
            int meta = Integer.parseInt(fields[5]);
            return meta >= 0 && meta <= 15;
        } catch (NumberFormatException ignored) {
            return false;
        }
    }

    private boolean oracleBoundedCompareCommand(String command) {
        if (command == null) return false;
        String[] fields = command.split(" ", -1);
        if ((fields.length != 10 && fields.length != 11)
                || !"testforblocks".equalsIgnoreCase(fields[0])) return false;
        for (int index = 1; index <= 9; ++index)
            if (!fields[index].matches("(?:~(?:-?[0-9]+)?)|-?[0-9]+"))
                return false;
        return fields.length == 10 || "all".equals(fields[10])
            || "masked".equals(fields[10]);
    }

    private boolean oracleBoundedFillCommand(String command) {
        if (command == null) return false;
        String[] fields = command.split(" ", -1);
        if ((fields.length != 8 && fields.length != 9
                    && fields.length != 10)
                || !"fill".equalsIgnoreCase(fields[0])) return false;
        for (int index = 1; index <= 6; ++index)
            if (!fields[index].matches("(?:~(?:-?[0-9]+)?)|-?[0-9]+"))
                return false;
        net.minecraft.block.Block block = net.minecraft.block.Block.REGISTRY
            .getObject(new net.minecraft.util.ResourceLocation(fields[7]));
        if (block == null || block == net.minecraft.init.Blocks.AIR
                && !"minecraft:air".equals(fields[7])) return false;
        if (fields.length >= 9) try {
            int meta = Integer.parseInt(fields[8]);
            if (meta < 0 || meta > 15) return false;
        } catch (NumberFormatException ignored) {
            return false;
        }
        return fields.length < 10 || "replace".equals(fields[9])
            || "keep".equals(fields[9]) || "outline".equals(fields[9])
            || "hollow".equals(fields[9]);
    }

    private boolean oracleBoundedCloneCommand(String command) {
        if (command == null) return false;
        String[] fields = command.split(" ", -1);
        if (fields.length < 10 || fields.length > 14
                || !"clone".equalsIgnoreCase(fields[0])) return false;
        for (int index = 1; index <= 9; ++index)
            if (!fields[index].matches("(?:~(?:-?[0-9]+)?)|-?[0-9]+"))
                return false;
        if (fields.length >= 11 && "filtered".equals(fields[10])) {
            if (fields.length < 13 || fields.length > 14
                    || !"normal".equals(fields[11])
                        && !"force".equals(fields[11])
                        && !"move".equals(fields[11])) return false;
            net.minecraft.block.Block filter = net.minecraft.block.Block.REGISTRY
                .getObject(new net.minecraft.util.ResourceLocation(fields[12]));
            if (filter == null || filter == net.minecraft.init.Blocks.AIR
                    && !"minecraft:air".equals(fields[12])) return false;
            if (fields.length == 14) try {
                int meta = Integer.parseInt(fields[13]);
                if (meta < 0 || meta > 15) return false;
            } catch (NumberFormatException ignored) {
                return false;
            }
            return true;
        }
        if (fields.length >= 11 && !"replace".equals(fields[10])
                && !"masked".equals(fields[10])) return false;
        if (fields.length > 12) return false;
        return fields.length < 12 || "normal".equals(fields[11])
            || "force".equals(fields[11]) || "move".equals(fields[11]);
    }

    private boolean oracleBoundedLiteralChatCommand(String command) {
        if (command == null) return false;
        String message = command.regionMatches(true, 0, "say ", 0, 4)
            ? command.substring(4)
            : command.regionMatches(true, 0, "me ", 0, 3)
            ? command.substring(3) : null;
        if (message == null || message.length() == 0
                || message.indexOf('@') >= 0) return false;
        for (int index = 0; index < message.length(); ++index)
            if (message.charAt(index) < 32 || message.charAt(index) > 126)
                return false;
        return true;
    }

