    private int[] oracleBoundedXpCommand(String command) {
        if (command == null) return null;
        String[] fields = command.split(" ", -1);
        if (fields.length != 3 || !"xp".equalsIgnoreCase(fields[0])
                || !"@p".equals(fields[2])) return null;
        String value = fields[1];
        boolean levels = value.length() > 1
            && (value.endsWith("l") || value.endsWith("L"));
        if (levels) value = value.substring(0, value.length() - 1);
        try {
            int amount = Integer.parseInt(value);
            if (amount == Integer.MIN_VALUE || (amount < 0 && !levels))
                return null;
            return new int[] {
                amount < 0 ? -amount : amount,
                levels ? 1 : 0,
                amount < 0 ? 1 : 0
            };
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

