    private int oracleBoundedSinglePlayerTeleportCommand(String command) {
        if ("tp @p 8.5 78 8.5".equalsIgnoreCase(command)) return 1;
        if ("teleport @p 8.5 78 8.5".equalsIgnoreCase(command)) return 2;
        if ("tp @p -1 80 4".equalsIgnoreCase(command)) return 3;
        if ("tp @p ~1 ~2 ~-3 450 -80".equalsIgnoreCase(command)) return 4;
        return "teleport @p ~ ~2 ~".equalsIgnoreCase(command) ? 5 : 0;
    }

