                        java.lang.reflect.Field lifetimeField =
                            net.minecraft.entity.monster.EntityEndermite.class
                                .getDeclaredField("lifetime");
                        lifetimeField.setAccessible(true);
                        lifetimeField.setInt(endermite, lifetime);
