    @SuppressWarnings("unchecked")
    private static void oracleActivateHorseCrazyTask(
            net.minecraft.entity.passive.AbstractHorse horse)
            throws Exception {
        Object entriesValue = oracleObjectField(horse.tasks, "taskEntries");
        Object executingValue = oracleObjectField(
            horse.tasks, "executingTaskEntries");
        if (!(entriesValue instanceof Iterable<?>)
                || !(executingValue instanceof java.util.Collection<?>))
            throw new IllegalStateException("missing horse AI task sets");
        Object selected = null;
        for (Object entry : (Iterable<?>)entriesValue) {
            Object action = oracleObjectField(entry, "action");
            if (action instanceof
                    net.minecraft.entity.ai.EntityAIRunAroundLikeCrazy) {
                selected = entry;
                break;
            }
        }
        if (selected == null)
            throw new IllegalStateException("missing horse crazy task");
        oracleDeclaredField(selected, "using").setBoolean(selected, true);
        ((java.util.Collection<Object>)executingValue).add(selected);
        oracleDeclaredField(horse.tasks, "tickCount").setInt(horse.tasks, 1);
        int bx = net.minecraft.util.math.MathHelper.floor(horse.posX);
        int by = net.minecraft.util.math.MathHelper.floor(horse.posY);
        int bz = net.minecraft.util.math.MathHelper.floor(horse.posZ);
        net.minecraft.pathfinding.Path path = new net.minecraft.pathfinding.Path(
            new net.minecraft.pathfinding.PathPoint[] {
                new net.minecraft.pathfinding.PathPoint(bx + 1, by, bz - 1),
            });
        if (!horse.getNavigator().setPath(path, 1.2D))
            throw new IllegalStateException("failed to stage horse crazy path");
    }

