                        continue;
                    net.minecraft.entity.projectile.EntityArrow arrow =
                        (net.minecraft.entity.projectile.EntityArrow)entity;
                    JsonObject row = new JsonObject();
                    row.addProperty("order", order);
                    row.addProperty("eid", arrow.getEntityId());
                    row.addProperty("class", arrow.getClass().getSimpleName());
                    row.addProperty("uuid", arrow.getUniqueID().toString());
