    private static final ThreadLocal<SlimeSplitCapture>
        oracleSlimeSplitCapture = new ThreadLocal<SlimeSplitCapture>();

    /** Mixin seam for observing actual EntityXPOrb constructor results. */
    public static int oracleTerminalXpSpawn(
            net.minecraft.world.World world,
            net.minecraft.entity.Entity entity,
            net.minecraft.entity.EntityLivingBase owner) {
        TerminalXpCapture capture = oracleTerminalXpCapture.get();
        if (capture == null || capture.world != world || capture.owner != owner
                || !(entity instanceof
                    net.minecraft.entity.item.EntityXPOrb))
            return -1;
        capture.orbs.add((net.minecraft.entity.item.EntityXPOrb)entity);
        capture.mathSeed48 = mathRandomSeed48();
        return 1;
    }

    /** Prevent terminal Slime children from reaching the live oracle world. */
    public static int oracleSlimeSplitSpawn(
            net.minecraft.world.World world,
            net.minecraft.entity.Entity entity,
            net.minecraft.entity.monster.EntitySlime owner) {
        SlimeSplitCapture capture = oracleSlimeSplitCapture.get();
        if (capture == null || capture.world != world
                || capture.owner != owner
                || !(entity instanceof
                    net.minecraft.entity.monster.EntitySlime))
            return -1;
        capture.children.add(
            (net.minecraft.entity.monster.EntitySlime)entity);
        return 1;
    }

    /** Exact isolated Witch self-potion selection or completion boundary. */
    private String oracleWitchSelfPotionLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("witch_self_potion_locked requires a parked oracle server");
            long oldMathSeed = -1L;
            int oldNextId = -1;
            net.minecraft.world.WorldServer world = null;
            BlockPos waterPos = null;
            net.minecraft.block.state.IBlockState oldWater = null;
            AttackSoundProbe soundProbe = null;
            try {
                String phase = action.get("phase").getAsString();
                String scenario = action.get("scenario").getAsString();
                long seed48 = action.get("entity_seed48").getAsLong();
                if ((!phase.equals("start") && !phase.equals("finish"))
                        || seed48 < 0L || seed48 >= (1L << 48))
                    return err("invalid witch self-potion fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null) return err("no server");
                java.util.List<net.minecraft.entity.player.EntityPlayerMP>
                    players = server.getPlayerList().getPlayers();
                if (players.isEmpty()) return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player = players.get(0);
                world = player.getServerWorld();
                oldMathSeed = mathRandomSeed48();
                oldNextId = nextEntityId();
                int bx = net.minecraft.util.math.MathHelper.floor(player.posX);
                int bz = net.minecraft.util.math.MathHelper.floor(player.posZ);
                net.minecraft.entity.monster.EntityWitch witch =
                    new net.minecraft.entity.monster.EntityWitch(world);
                witch.enablePersistence();
                witch.setLocationAndAngles(
                    bx + 0.5D, 200.0D, bz + 0.5D, 0.0F, 0.0F);
                WitchTraceRandom trace = new WitchTraceRandom();
                setJavaRandomSeed48(trace, seed48);
                setJavaRandomGaussianState(trace, false, 0.0D);
                setEntityRandom(witch, trace);

                net.minecraft.potion.PotionType requested = null;
                if (scenario.equals("water"))
                    requested = net.minecraft.init.PotionTypes.WATER_BREATHING;
                else if (scenario.equals("fire"))
                    requested = net.minecraft.init.PotionTypes.FIRE_RESISTANCE;
                else if (scenario.equals("heal"))
                    requested = net.minecraft.init.PotionTypes.HEALING;
                else if (scenario.equals("speed"))
                    requested = net.minecraft.init.PotionTypes.SWIFTNESS;
                else if (!scenario.equals("none"))
                    return err("unknown witch self-potion scenario");

                if (phase.equals("start")) {
                    if (scenario.equals("water")) {
                        waterPos = new BlockPos(bx, 201, bz);
                        oldWater = world.getBlockState(waterPos);
                        world.setBlockState(waterPos,
                            net.minecraft.init.Blocks.WATER.getDefaultState(), 2);
                    } else if (scenario.equals("fire")) {
                        witch.setFire(20);
                    } else if (scenario.equals("heal")) {
                        witch.setHealth(20.0F);
                    } else if (scenario.equals("speed")) {
                        witch.setAttackTarget(player);
                    }
                } else {
                    if (requested == null)
                        return err("finish requires a potion scenario");
                    net.minecraft.item.ItemStack potion =
                        net.minecraft.potion.PotionUtils.addPotionToItemStack(
                            new net.minecraft.item.ItemStack(
                                net.minecraft.init.Items.POTIONITEM), requested);
                    witch.setItemStackToSlot(
                        net.minecraft.inventory.EntityEquipmentSlot.MAINHAND,
                        potion);
                    witch.setAggressive(true);
                    setWitchAttackTimer(witch, 0);
                    java.util.UUID modifierId = java.util.UUID.fromString(
                        "5CD17E52-A79A-43D3-A529-90FDE04B181E");
                    net.minecraft.entity.ai.attributes.IAttributeInstance speed =
                        witch.getEntityAttribute(
                            net.minecraft.entity.SharedMonsterAttributes.MOVEMENT_SPEED);
                    net.minecraft.entity.ai.attributes.AttributeModifier present =
                        speed.getModifier(modifierId);
                    if (present != null) speed.removeModifier(present);
                    speed.applyModifier((new
                        net.minecraft.entity.ai.attributes.AttributeModifier(
                            modifierId, "Drinking speed penalty", -0.25D, 0))
                        .setSaved(false));
                    if (scenario.equals("heal")) witch.setHealth(20.0F);
                }

                soundProbe = new AttackSoundProbe();
                world.addEventListener(soundProbe);
                witch.onLivingUpdate();
                net.minecraft.item.ItemStack held = witch.getHeldItemMainhand();
                net.minecraft.potion.PotionType heldType =
                    net.minecraft.potion.PotionUtils.getPotionFromItem(held);
                net.minecraft.util.ResourceLocation heldName =
                    net.minecraft.potion.PotionType.REGISTRY
                        .getNameForObject(heldType);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("phase", phase);
                out.addProperty("scenario", scenario);
                out.addProperty("drinking", witch.isDrinkingPotion());
                out.addProperty("timer", witchAttackTimer(witch));
                out.addProperty("mainhand_item",
                    held.isEmpty() ? 0
                        : net.minecraft.item.Item.getIdFromItem(held.getItem()));
                out.addProperty("mainhand_potion",
                    held.isEmpty() || heldName == null ? "" : heldName.toString());
                out.addProperty("health", witch.getHealth());
                out.addProperty("movement_speed", witch.getEntityAttribute(
                    net.minecraft.entity.SharedMonsterAttributes.MOVEMENT_SPEED)
                    .getAttributeValue());
                java.util.Collection<net.minecraft.potion.PotionEffect> effects =
                    witch.getActivePotionEffects();
                out.addProperty("effect_count", effects.size());
                int effectId = -1, effectDuration = 0, effectAmplifier = -1;
                if (!effects.isEmpty()) {
                    net.minecraft.potion.PotionEffect effect =
                        effects.iterator().next();
                    effectId = net.minecraft.potion.Potion.getIdFromPotion(
                        effect.getPotion());
                    effectDuration = effect.getDuration();
                    effectAmplifier = effect.getAmplifier();
                }
                out.addProperty("effect_id", effectId);
                out.addProperty("effect_duration", effectDuration);
                out.addProperty("effect_amplifier", effectAmplifier);
                JsonArray sounds = new JsonArray();
                for (AttackSoundRow row : soundProbe.sounds) {
                    JsonObject sound = new JsonObject();
                    sound.addProperty("sound", row.sound);
                    sound.addProperty("category", row.category);
                    sound.add("position_bits", oracleEntityDoubleBits(
                        row.x - witch.posX, row.y - witch.posY,
                        row.z - witch.posZ));
                    sound.addProperty("volume_bits",
                        oracleFloatBits(row.volume));
                    sound.addProperty("pitch_bits",
                        oracleFloatBits(row.pitch));
                    sounds.add(sound);
                }
                out.add("sounds", sounds);
                out.add("direct_random_calls", trace.callsJson());
                return out.toString();
            } catch (Throwable t) {
                return err("witch_self_potion_locked: " + t);
            } finally {
                try {
                    if (world != null && soundProbe != null)
                        world.removeEventListener(soundProbe);
                    if (world != null && waterPos != null && oldWater != null)
                        world.setBlockState(waterPos, oldWater, 2);
                    if (oldMathSeed >= 0L) setMathRandomSeed48(oldMathSeed);
                    if (oldNextId >= 0) setNextEntityId(oldNextId);
                } catch (Throwable ignored) { }
            }
        }
    }

    /** Exact Snow Golem ranged spawn, owner, sound, UUID, and heading math. */
    private String oracleSnowmanRangedLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err(
                    "snowman_ranged_locked requires a parked oracle server");
            JsonObject oldSeedHelper = null;
            int oldNextId = -1;
            long oldUuidSeed = -1L;
            boolean oldUuidPinned = false;
            boolean oldUuidFixtureIsolation = false;
            net.minecraft.world.WorldServer world = null;
            net.minecraft.entity.projectile.EntitySnowball spawned = null;
            AttackSoundProbe soundProbe = null;
            try {
                double ownerX = action.get("owner_x").getAsDouble();
                double ownerY = action.get("owner_y").getAsDouble();
                double ownerZ = action.get("owner_z").getAsDouble();
                double targetX = action.get("target_x").getAsDouble();
                double targetY = action.get("target_y").getAsDouble();
                double targetZ = action.get("target_z").getAsDouble();
                long ownerSeed = action.get("owner_seed48").getAsLong();
                long entitySeed = action.get("entity_seed48").getAsLong();
                long uuidSeed = action.get("server_uuid_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                if (!Double.isFinite(ownerX) || !Double.isFinite(ownerY)
                        || !Double.isFinite(ownerZ)
                        || !Double.isFinite(targetX)
                        || !Double.isFinite(targetY)
                        || !Double.isFinite(targetZ)
                        || ownerSeed < 0L || ownerSeed >= (1L << 48)
                        || entitySeed < 0L || entitySeed >= (1L << 48)
                        || uuidSeed < 0L || uuidSeed >= (1L << 48)
                        || nextId <= 0 || nextId == Integer.MAX_VALUE)
                    return err("invalid Snow Golem ranged fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null
                        || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                world = server.worldServerForDimension(-1);
                world.getChunkProvider().provideChunk(
                    net.minecraft.util.math.MathHelper.floor(ownerX) >> 4,
                    net.minecraft.util.math.MathHelper.floor(ownerZ) >> 4);
                net.minecraft.entity.monster.EntitySnowman snowman =
                    new net.minecraft.entity.monster.EntitySnowman(world);
                net.minecraft.entity.monster.EntityZombie target =
                    new net.minecraft.entity.monster.EntityZombie(world);
                snowman.setLocationAndAngles(
                    ownerX, ownerY, ownerZ, 0.0F, 0.0F);
                target.setLocationAndAngles(
                    targetX, targetY, targetZ, 0.0F, 0.0F);
                snowman.setEntityId(100);
                target.setEntityId(101);
                setJavaRandomSeed48(entityRandom(snowman), ownerSeed);
                setJavaRandomGaussianState(
                    entityRandom(snowman), false, 0.0D);

                oldSeedHelper = oracleSeedHelperState();
                oldNextId = nextEntityId();
                oldUuidSeed = javaRandomSeed48(oracleServerUuidRandom);
                oldUuidPinned = oracleServerUuidPinned;
                oldUuidFixtureIsolation = oracleServerUuidFixtureIsolation;
                java.lang.reflect.Field currentSeed =
                    com.microsoft.Malmo.Utils.SeedHelper.class
                        .getDeclaredField("currentSeed");
                currentSeed.setAccessible(true);
                currentSeed.set(null, Long.valueOf(0L));
                setJavaRandomSeed48(
                    oracleSeedHelperGeneratorEnsure("entity"), entitySeed);
                setJavaRandomGaussianState(
                    oracleSeedHelperGenerator("entity"), false, 0.0D);
                setJavaRandomSeed48(oracleServerUuidRandom, uuidSeed);
                oracleServerUuidPinned = true;
                oracleServerUuidFixtureIsolation = true;
                setNextEntityId(nextId);

                java.util.Set<net.minecraft.entity.Entity> before =
                    new java.util.HashSet<net.minecraft.entity.Entity>(
                        world.loadedEntityList);
                soundProbe = new AttackSoundProbe();
                world.addEventListener(soundProbe);
                snowman.attackEntityWithRangedAttack(target, 1.0F);
                for (net.minecraft.entity.Entity entity
                        : world.loadedEntityList)
                    if (!before.contains(entity)
                            && entity instanceof net.minecraft.entity.projectile
                                .EntitySnowball) {
                        spawned = (net.minecraft.entity.projectile
                            .EntitySnowball)entity;
                        break;
                    }
                if (spawned == null)
                    return err("Snow Golem did not spawn a snowball");
                java.util.Random random = entityRandom(spawned);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("eid", spawned.getEntityId());
                out.addProperty("owner_eid",
                    spawned.getThrower() == null
                        ? -1 : spawned.getThrower().getEntityId());
                out.add("position_bits", oracleEntityDoubleBits(
                    spawned.posX, spawned.posY, spawned.posZ));
                out.add("motion_bits", oracleEntityDoubleBits(
                    spawned.motionX, spawned.motionY, spawned.motionZ));
                JsonArray rotation = new JsonArray();
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(spawned.rotationYaw)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(spawned.rotationPitch)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(spawned.prevRotationYaw)));
                rotation.add(new JsonPrimitive(
                    oracleFloatBits(spawned.prevRotationPitch)));
                out.add("rotation_bits", rotation);
                out.addProperty("seed48", javaRandomSeed48(random));
                out.addProperty("have_gaussian",
                    javaRandomHaveNextGaussian(random));
                out.addProperty("next_gaussian_bits",
                    oracleDoubleBits(javaRandomNextGaussian(random)));
                out.addProperty("uuid_most",
                    spawned.getUniqueID().getMostSignificantBits());
                out.addProperty("uuid_least",
                    spawned.getUniqueID().getLeastSignificantBits());
                out.addProperty("owner_seed48",
                    javaRandomSeed48(entityRandom(snowman)));
                out.addProperty("entity_seed48",
                    oracleSeedHelperGeneratorSeed48("entity"));
                out.addProperty("server_uuid_seed48",
                    javaRandomSeed48(oracleServerUuidRandom));
                out.addProperty("next_entity_id", nextEntityId());
                if (soundProbe.sounds.size() != 1)
                    return err("Snow Golem emitted "
                        + soundProbe.sounds.size() + " ranged sounds");
                AttackSoundRow sound = soundProbe.sounds.get(0);
                /* Stable native manifest discriminator, compared alongside
                 * the authoritative resource name below. */
                out.addProperty("sound", 164);
                out.addProperty("sound_name", sound.sound);
                out.addProperty("sound_category", sound.category);
                out.addProperty("sound_volume_bits",
                    oracleFloatBits(sound.volume));
                out.addProperty("sound_pitch_bits",
                    oracleFloatBits(sound.pitch));
                return out.toString();
            } catch (Throwable t) {
                return err("snowman_ranged_locked: " + t);
            } finally {
                try {
                    if (world != null && soundProbe != null)
                        world.removeEventListener(soundProbe);
                    if (world != null && spawned != null)
                        world.removeEntityDangerously(spawned);
                    if (oldSeedHelper != null)
                        oracleRestoreSeedHelperState(oldSeedHelper);
                    if (oldNextId > 0) setNextEntityId(oldNextId);
                    if (oldUuidSeed >= 0L)
                        setJavaRandomSeed48(
                            oracleServerUuidRandom, oldUuidSeed);
                    oracleServerUuidPinned = oldUuidPinned;
                    oracleServerUuidFixtureIsolation =
                        oldUuidFixtureIsolation;
                } catch (Throwable ignored) { }
            }
        }
    }

