    private String oracleWitchTerminalXpLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0)
                return err("witch_terminal_xp_locked requires a parked oracle server");
            long oldMathSeed = -1L;
            long oldWorldSeed = -1L;
            int oldNextId = -1;
            String oldDoMobLoot = null;
            net.minecraft.world.WorldServer world = null;
            java.util.ArrayList<net.minecraft.entity.item.EntityXPOrb> spawned =
                new java.util.ArrayList<net.minecraft.entity.item.EntityXPOrb>();
            try {
                long entitySeed48 = action.get("entity_seed48").getAsLong();
                long mathSeed48 = action.get("math_seed48").getAsLong();
                long worldSeed48 = action.get("world_seed48").getAsLong();
                int nextId = action.get("next_entity_id").getAsInt();
                boolean doMobLoot = action.get("do_mob_loot").getAsBoolean();
                if (entitySeed48 < 0L || entitySeed48 >= (1L << 48)
                        || mathSeed48 < 0L || mathSeed48 >= (1L << 48)
                        || worldSeed48 < 0L || worldSeed48 >= (1L << 48)
                        || nextId <= 0 || nextId > Integer.MAX_VALUE - 3)
                    return err("invalid Witch terminal XP fixture");
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null || server.getPlayerList().getPlayers().isEmpty())
                    return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player =
                    server.getPlayerList().getPlayers().get(0);
                world = player.getServerWorld();
                oldMathSeed = mathRandomSeed48();
                oldWorldSeed = javaRandomSeed48(world.rand);
                oldNextId = nextEntityId();
                oldDoMobLoot = world.getGameRules().getString("doMobLoot");
                int bx = net.minecraft.util.math.MathHelper.floor(player.posX);
                int bz = net.minecraft.util.math.MathHelper.floor(player.posZ);
                OracleLootWitch witch = new OracleLootWitch(world);
                witch.setLocationAndAngles(
                    bx + 0.5D, 220.0D, bz + 0.5D, 0.0F, 0.0F);
                setJavaRandomSeed48(entityRandom(witch), entitySeed48);
                setJavaRandomGaussianState(
                    entityRandom(witch), false, 0.0D);
                setJavaRandomSeed48(world.rand, worldSeed48);
                setMathRandomSeed48(mathSeed48);
                setNextEntityId(nextId);
                world.getGameRules().setOrCreateGameRule(
                    "doMobLoot", doMobLoot ? "true" : "false");
                TerminalXpCapture capture =
                    new TerminalXpCapture(world, witch);
                oracleTerminalXpCapture.set(capture);
                try {
                    witch.generateTerminalXp(player);
                } finally {
                    oracleTerminalXpCapture.remove();
                }
                spawned.addAll(capture.orbs);

                JsonArray orbs = new JsonArray();
                for (net.minecraft.entity.item.EntityXPOrb orb : spawned) {
                    JsonObject row = new JsonObject();
                    row.addProperty("eid", orb.getEntityId());
                    row.addProperty("value", orb.xpValue);
                    row.add("position_bits", oracleEntityDoubleBits(
                        orb.posX - witch.posX,
                        orb.posY - witch.posY,
                        orb.posZ - witch.posZ));
                    row.add("motion_bits", oracleEntityDoubleBits(
                        orb.motionX, orb.motionY, orb.motionZ));
                    row.addProperty("yaw_bits",
                        oracleFloatBits(orb.rotationYaw));
                    row.addProperty("age", orb.xpOrbAge);
                    row.addProperty("pickup_delay", orb.delayBeforeCanPickup);
                    row.addProperty("health", xpOrbField(orb, "xpOrbHealth"));
                    row.addProperty("color", orb.xpColor);
                    java.lang.reflect.Field target =
                        net.minecraft.entity.item.EntityXPOrb.class
                            .getDeclaredField("xpTargetColor");
                    target.setAccessible(true);
                    row.addProperty("target_color", target.getInt(orb));
                    orbs.add(row);
                }

                java.util.Random entityRandom = entityRandom(witch);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("do_mob_loot", doMobLoot);
                out.add("orbs", orbs);
                out.addProperty("death_time", witch.deathTime);
                out.addProperty("entity_dead", witch.isDead);
                out.addProperty("entity_seed48",
                    javaRandomSeed48(entityRandom));
                out.addProperty("entity_have_gaussian",
                    javaRandomHaveNextGaussian(entityRandom));
                out.addProperty("entity_next_gaussian_bits",
                    oracleDoubleBits(javaRandomNextGaussian(entityRandom)));
                out.addProperty("world_seed48", javaRandomSeed48(world.rand));
                out.addProperty("math_seed48", mathRandomSeed48());
                out.addProperty("next_entity_id", nextEntityId());
                return out.toString();
            } catch (Throwable t) {
                return err("witch_terminal_xp_locked: " + t);
            } finally {
                try {
                    oracleTerminalXpCapture.remove();
                    if (world != null && oldDoMobLoot != null)
                        world.getGameRules().setOrCreateGameRule(
                            "doMobLoot", oldDoMobLoot);
                    if (world != null && oldWorldSeed >= 0L)
                        setJavaRandomSeed48(world.rand, oldWorldSeed);
                    if (oldMathSeed >= 0L) setMathRandomSeed48(oldMathSeed);
                    if (oldNextId >= 0) setNextEntityId(oldNextId);
                } catch (Throwable ignored) { }
            }
        }
    }

