    /** Spawn one minecart whose MobSpawnerBaseLogic has exact persisted NBT. */
    private String oracleSpawnSpawnerMinecartLocked(JsonObject action) {
        synchronized (oracleServerMonitor) {
            if (!oracleServerGate || !oracleServerWaiting
                    || oracleServerTickInFlight || oracleServerPermits != 0) {
                return err(
                    "spawn_spawner_minecart_locked requires a parked server");
            }
            try {
                MinecraftServer server =
                    Minecraft.getMinecraft().getIntegratedServer();
                if (server == null) return err("no server");
                java.util.List<net.minecraft.entity.player.EntityPlayerMP>
                    players = server.getPlayerList().getPlayers();
                if (players.isEmpty()) return err("no server player");
                net.minecraft.entity.player.EntityPlayerMP player =
                    players.get(0);
                net.minecraft.world.WorldServer world =
                    player.getServerWorld();
                double x = action.get("x").getAsDouble();
                double y = action.get("y").getAsDouble();
                double z = action.get("z").getAsDouble();
                if (!Double.isFinite(x) || !Double.isFinite(y)
                        || !Double.isFinite(z) || y < 0.0D || y > 255.0D
                        || !action.has("nbt"))
                    return err("invalid spawner minecart fixture");
                net.minecraft.nbt.NBTTagCompound logic = oracleNbtFromHex(
                    action.get("nbt").getAsString());
                String[] fields = {
                    "Delay", "MinSpawnDelay", "MaxSpawnDelay",
                    "SpawnCount", "MaxNearbyEntities",
                    "RequiredPlayerRange", "SpawnRange", "SpawnData",
                    "SpawnPotentials"
                };
                for (String field : fields)
                    if (!logic.hasKey(field))
                        return err("spawner minecart NBT misses " + field);
                net.minecraft.entity.item.EntityMinecartMobSpawner cart =
                    new net.minecraft.entity.item.EntityMinecartMobSpawner(
                        world, x, y, z);
                net.minecraft.nbt.NBTTagCompound full = cart.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                for (String field : fields)
                    full.setTag(field, logic.getTag(field).copy());
                cart.readFromNBT(full);
                net.minecraft.nbt.NBTTagCompound roundTrip = cart.writeToNBT(
                    new net.minecraft.nbt.NBTTagCompound());
                for (String field : fields)
                    if (!roundTrip.getTag(field).equals(logic.getTag(field)))
                        return err(
                            "spawner minecart NBT is not canonical at "
                            + field);
                if (!world.spawnEntity(cart))
                    return err("could not spawn spawner minecart fixture");
                oracleCaptureAuthoritativePlayerLocked(player);
                JsonObject out = new JsonObject();
                out.addProperty("ok", true);
                out.addProperty("eid", cart.getEntityId());
                out.add("authoritative", oracleAuthoritativeJsonLocked());
                return out.toString();
            } catch (Throwable t) {
                return err("spawn_spawner_minecart_locked: " + t);
            }
        }
    }

